  ui_story_5038_50380001_4_dialog_content = "트위티, 왜 그렇게 숨이 잔뜩 찬 거죠? 급하게 온 건가요?",
  ui_story_5038_50380001_5_dialog_content = "쪼매 전에 편지를 배달해 주러 갔는디, 편지 받는 사람이 지가 하는 말을\n몬 알아듣겠다고 사인을 안 해줄라켔다 아입니꺼.",
  ui_story_5038_50380001_6_dialog_content = "지도 통용어를 쓸라꼬 억수로 노력 중인데, 와 자꾸 이래 되는지 참말로 모르겠심더.",
  ui_story_5038_50380001_7_dialog_content = "후훗, 고생 많았어요. 타지에서 일하는 건 많이 힘들죠?",
