  ui_story_5038_50380001_10_dialog_content = "아니에요. 오늘은 조금 한가하거든요.",
  ui_story_5038_50380001_11_dialog_content = "엄밀히 말하면 제가 트위티의 시간을 뺏고 있는 걸지도 모르겠네요...",
  ui_story_5038_50380001_12_dialog_content = "에? 그기 몬 말씀임니꺼?",
