  ui_story_5038_50380001_14_dialog_content = "<size=50>하이고야?! 30통이나 되네예?!</size>",
  ui_story_5038_50380001_15_dialog_content = "그건 긴급 우편이고, 뒤쪽에 보면 일반 우편으로 50통 더 있어요.",
