  ui_story_5038_50380001_19_dialog_content = "우편물 배송도 성수기와 비수기가 있어요. 지금은 마침 한창 바쁠 때죠.",
  ui_story_5038_50380001_20_dialog_content = "게다가 왠지 움브라톤 쪽에 돌발 상황이 발생한 것 같거든요...",
  ui_story_5038_50380001_21_dialog_content = "그 소포 위에 적혀 있는 수신자 주소를 확인해 보세요, 트위티.",
