  ui_story_5038_50380001_24_dialog_content = "맞아요. 움브라톤에서 갑자기 많은 화물들을 쌍사성의 여러 지역으로 급히 발송하고 있어요.",
  ui_story_5038_50380001_25_dialog_content = "최대한 빨리 배송해 달라는 요청이 들어오는 바람에, 앞으로 이틀 동안은 많이 힘들 거예요.",
  ui_story_5038_50380001_26_dialog_content = "거 쌍사성이라는 곳은 머 하는 뎁니꺼?\n지는 가 본 적도 읍고, 오데 있는지도 모르는데예?!",
