  ui_story_5038_50380001_30_dialog_content = "<color=#e8d9bb>5일 후</color>",
  ui_story_5038_50380001_31_dialog_content = "<size=50>으아아아아앗!</size>",
  ui_story_5038_50380001_32_dialog_content = "<size=50>PlayerName 오빠야! 지 좀 살려주이소!</size>",
  ui_story_5038_50380001_33_dialog_content = "어? 트위티? 왜 그래?!",
  ui_story_5038_50380001_34_dialog_content = "무슨 일 있어?",
  ui_story_5038_50380001_35_dialog_content = "편지랑 소포를 배송해야 카는디, 고마 끝이 안 보입니더!",
  ui_story_5038_50380001_36_dialog_content = "일단 진정하고, 앉아서 천천히 이야기해 봐.",
  ui_story_5038_50380001_37_dialog_content = "그니까예, 얼마 전에 움브라톤에서 쿠리어 길드에 <color=#FFB400>빨간색 색지</color>를 잔뜩\n배송해 달라고 의뢰를 해 왔심더.",
  ui_story_5038_50380001_38_dialog_content = "양도 많은디 그걸 또 싸게 좀 가따 주라캐싸서 지가 며칠 동안\n야근까지 해가 배달을 했다 아입니꺼...",
  ui_story_5038_50380001_39_dialog_content = "근디 지도 이제 마 한계입니더...",
