  ui_story_5038_50380001_44_dialog_content = "그카믄 지는 돈도 읍고, 돈이 읍스면 밥도 몬 먹고, 오데 살 데도 읍서가...",
  ui_story_5038_50380001_45_dialog_content = "결국엔 운산에 돌아가 장작이나 패믄서 살아야겠지예!",
  ui_story_5038_50380001_46_dialog_content = "그렇게 심각하다고?!",
  ui_story_5038_50380001_47_dialog_content = "그래가... PlayerName 오빠야한테 좀 도와 달라 카고 싶어가 찾아 왔심더.",
  ui_story_5038_50380001_48_dialog_content = "지는 스카이워커호를 고용하고 싶심더!",
  ui_story_5038_50380001_49_dialog_content = "비용은 당연히 낼 깁니더! 이번 달에 월급을 받으면 마카 다 드리겠심더!",
  ui_story_5038_50380001_50_dialog_content = "트위티를 도울 수 있다면 그걸로 괜찮아. 돈은 안 줘도 돼.",
  ui_story_5038_50380001_51_dialog_content = "급하다고 했으니까 그럼 지금 바로 출발하자!",
  ui_story_5038_50380001_52_dialog_content = "근데 목적지가 어디라고?",
  ui_story_5038_50380001_53_dialog_content = "「쌍사성」이라카는 항구 도시입니더.",
  ui_story_5038_50380001_54_dialog_content = "음, 마침 지금 스카이워커호는 골드리버 바로 위에 있어.",
  ui_story_5038_50380001_55_dialog_content = "골드리버를 따라 바다가 나오는 곳까지 이동하면 쌍사성에 도착할 거야.",
  ui_story_5038_50380001_56_dialog_content = "어?! 카렌 넌... 거기 가 본 적 있어?",
  ui_story_5038_50380001_57_dialog_content = "아니, 백야성 도서관에서 읽었던 책의 내용을 봤을 뿐이야.",
  ui_story_5038_50380001_58_dialog_content = "쌍사성은 골드리버 하구 쪽에 있는 곳인데, 문화나 풍습이 다른 곳과는 많이 달라서\n여러 책에서 자주 다루곤 하거든.",
  ui_story_5038_50380001_59_dialog_content = "그러고 보니 쌍사성의 기원은 네겐 낯설진 않을 거라고 생각해.",
  ui_story_5038_50380001_60_dialog_content = "응? 왜?",
  ui_story_5038_50380001_61_dialog_content = "거긴 <color=#FFB400>린 가문 상회</color>가 세운 도시거든.",
  ui_story_5038_50380001_62_dialog_content = "린 가문 상회?! 린 가문 상회는 움브라톤에 있는 거 아니었어?",
  ui_story_5038_50380001_63_dialog_content = "움브라톤은 린 가문 상회에서 무역업을 하는 곳이고,\n쌍사성은 아스트라 대륙에 위치한 그들의 중요 거점이야.",
  ui_story_5038_50380001_64_dialog_content = "린 가문 상회가 머나먼 동방의 다른 대륙에서 왔다는 거, 아직 기억하지?",
  ui_story_5038_50380001_65_dialog_content = "그 사람들이 나타나기 전까지 골드리버의 하구 쪽은 작고 가난한 어촌 마을에 불과했어.",
  ui_story_5038_50380001_66_dialog_content = "그러다 어느 날 거대한 선박이 그 마을에 정박했고,\n린 가문 상회의 몇몇 사람들이 아스트라에 도착했지.",
  ui_story_5038_50380001_67_dialog_content = "저들은 극동에서 운반해 온 화물들을 내려서, 골드리버를 따라 움브라톤으로 운송했어.",
  ui_story_5038_50380001_68_dialog_content = "그러려면 사람들을 고용해야 했고, 묵을 곳과 먹을 음식도 있어야 하니까,\n덕분에 어촌 마을에도 새로운 일자리들이 생겨났고.",
  ui_story_5038_50380001_69_dialog_content = "린 가문 상회의 사업 규모가 커질수록 어촌도 덩달아 함께 부유해지기 시작했어.",
  ui_story_5038_50380001_70_dialog_content = "그렇게 기존의 마을 주민들도 동방의 문화를 받아들였고,\n용주 대륙의 양식에 따라 도시를 세웠어.",
  ui_story_5038_50380001_71_dialog_content = "그러다 보니 기존 주민들과 린 가문의 사업으로 유입된 새로운 주민들이\n한 도시에서 함께 생활하게 됐고.",
  ui_story_5038_50380001_72_dialog_content = "그 도시가 바로 우리가 지금 가려는 쌍사성이야.",
  ui_story_5038_50380001_73_dialog_content = "와, 상인이 세운 도시라니! 그런 건 처음 들어봤어.",
  ui_story_5038_50380001_74_dialog_content = "호, 혹시 물가가 엄청 비싸고 그런 건 아니지?\n우린 지금 잔고가 그렇게 여유롭지가 않거든.",
  ui_story_5038_50380001_75_dialog_content = "부촌 같은 곳은 주차비도 따로 내야 한다고 들었는데...\n그게 사실이라면 스카이워커호는...",
  ui_story_5038_50380001_76_dialog_content = "음, 주차비 걱정은 안 해도 될 것 같지만, 그래도 불필요한 걱정거리는 만들지 않는 편이 좋겠지.",
  ui_story_5038_50380001_77_dialog_content = "PlayerName, 스카이워커호는 도시 바깥에 세워 두자.",
  ui_story_5038_50380001_78_dialog_content = "응, 그게 좋겠어.",
  ui_story_5038_50380001_79_dialog_content = "저기 좀 봐! 거의 다 도착했나 봐!",
  ui_story_5038_50380001_80_dialog_content = "우와! 거리가 엄청 예뻐!",
  ui_story_5038_50380001_81_dialog_content = "맞지예? 오만 데가 다 빨긋빨긋해가 진짜 억수로 대단함미더!",
  ui_story_5038_50380001_82_dialog_content = "그러게, 거리에 활력이 넘치는 것 같아.",
  ui_story_5038_50380001_83_dialog_content = "응, 책에 나와 있던 것처럼 아스트라와는 전혀 다른 분위기가 나는걸.",
  ui_story_5038_50380001_84_dialog_content = "바다 건너편에 있는 다른 대륙의 건물과 거리는 아마 이렇게 생겼겠구나.",
  ui_story_5038_50380001_85_dialog_content = "바다 하나를 사이에 두고 있는 것뿐인데도, 마치 우리와는 전혀 다른 세계 같은걸.",
  ui_story_5038_50380001_86_dialog_content = "아, 그라고 여 사람들은 명절도 우리랑 다르게 쇤다 아입니꺼!",
  ui_story_5038_50380001_87_dialog_content = "어제아래부터 가따 준 빨간색 색지를 어따 쓰나 켔는데,\n여 사람들은 명절 쇨 때 그기 꼭 필요하다 카대예.",
  ui_story_5038_50380001_88_dialog_content = "뭔 명절이라 켔더라... 와 기억이...",
  ui_story_5038_50380001_89_dialog_content = "즐거운 명절 되십시오! 여러분도 춘삭절을 쇠러 온 겁니까?",
  ui_story_5038_50380001_90_dialog_content = "아! 맞네! 「춘삭절」이라 켔심더!",
  ui_story_5038_50380001_91_dialog_content = "외지인을 만난 건 반년만이군요. 다들 외지에서 오셨죠?",
  ui_story_5038_50380001_92_dialog_content = "옷만 봐도 알 수 있거든요.",
  ui_story_5038_50380001_93_dialog_content = "아재요, 마침 잘 나오셨심더.\n주문하신 빨간색 색지를 가 왔쓰니까 받고 사인해 주이소!",
  ui_story_5038_50380001_94_dialog_content = "오, 고맙습니다. 명절 다 지나고야 받겠거니 했었는데!",
  ui_story_5038_50380001_95_dialog_content = "혹시 뭐 좀 물어봐도 될까요?\n왜 움브라톤에서 빨간색 색지를 이렇게 많이 주문하신 거죠?",
  ui_story_5038_50380001_96_dialog_content = "우린 명절 분위기를 내려면 빨간색 색지가 반드시 필요하거든요.",
  ui_story_5038_50380001_97_dialog_content = "용주는 춘삭절이 되면 빨간색 색지에 시를 적거나\n「복」이라는 글자를 써서 문 양옆에 붙이는 풍습이 있습니다.",
  ui_story_5038_50380001_98_dialog_content = "새로운 한 해에는 좋은 일이 가득하길 비는 거죠!",
  ui_story_5038_50380001_99_dialog_content = "동쪽에 있다는 대륙의 이름이... 바로 「용주」인가요?",
  ui_story_5038_50380001_100_dialog_content = "맞습니다. 표정을 보니 처음 들으시는 모양이군요.",
  ui_story_5038_50380001_101_dialog_content = "우리 쌍사성 주민들은 항상 자급자족해 왔습니다. 그래서 내륙과 왕래할 일이 거의 없었지요.",
  ui_story_5038_50380001_102_dialog_content = "이 빨간색 색지들만 해도, 원래라면 쌍사성에 있는 가게에서 샀으면 됐을 일입니다.",
  ui_story_5038_50380001_103_dialog_content = "그런데 올해에는... 문제가 조금 생겼습니다.",
  ui_story_5038_50380001_104_dialog_content = "문제? 무슨 일이죠?",
  ui_story_5038_50380001_105_dialog_content = "물건 공급이 확 끊겼거든요.\n색지뿐만이 아니라 명절 용품도 공급량이 거의 없는 수준입니다.",
  ui_story_5038_50380001_106_dialog_content = "상황이 그렇게나 심각하다니... 배급도 없는 건가요?",
  ui_story_5038_50380001_107_dialog_content = "평소에는 분기마다 린 가문 상회의 <color=#FFB400>원양 상선</color>이 용주에서 쌍사성까지 왔었지요.",
  ui_story_5038_50380001_108_dialog_content = "그런데 반년 전부터 무슨 문제가 생긴 모양인지 린 가문의 상선이 안 들어오지 뭡니까.",
  ui_story_5038_50380001_109_dialog_content = "그래서 상선에서 물건을 받아 판매하던 가게들은 거의 문을 닫아야 할 지경이 됐어요.",
  ui_story_5038_50380001_110_dialog_content = "상선에서 납품받던 물건 중에는 빨간색 색지도 있었습니다.\n헌데 사정이 이렇다 보니, 어쩔 수 없이 먼 곳의 움브라톤에 물건을 주문할 수밖에 없었죠.",
  ui_story_5038_50380001_111_dialog_content = "(그랬구나. 꽤 걱정되는 상황인데...)",
  ui_story_5038_50380001_112_dialog_content = "(나도 따지고 보면 린 가문 상회의 도움을 받은 사람이잖아. 그 사람들, 잘 지내려나?)",
  ui_story_5038_50380001_113_dialog_content = "하이고... 아재요, 고향 맛이 윽수로 그립지예? 지도 그 맘 다 암미더.",
  ui_story_5038_50380001_114_dialog_content = "<color=#e8d9bb>뚜우우── 뚜우──</color>",
  ui_story_5038_50380001_115_dialog_content = "어라? 이 먼 소립니꺼?",
  ui_story_5038_50380001_116_dialog_content = "항구 쪽에서 나팔 소리 같은 게 들린 것 같아...",
  ui_story_5038_50380001_117_dialog_content = "이건... 뱃고동 소리입니다!",
  ui_story_5038_50380001_118_dialog_content = "틀림없습니다! 뱃고동 소리가 분명해요!",
  ui_story_5038_50380001_119_dialog_content = "항구에 배가 들어왔대! 설마 린 가문의 배가 들어온 건가?!",
  ui_story_5038_50380001_120_dialog_content = "린 가문의 상선?",
  ui_story_5038_50380001_121_dialog_content = "PlayerName, 우리도 가 봐야 할 것 같아.",
  ui_story_5038_50380001_122_dialog_content = "상선이야! 진짜 린 가문의 상선이라고!",
  ui_story_5038_50380001_123_dialog_content = "살았다! 올해 명절 용품 사는 건 물 건너간 줄 알았는데!",
  ui_story_5038_50380001_124_dialog_content = "배에서 누가 내려오고 있어!",
  ui_story_5038_50380001_125_dialog_content = "......",
  ui_story_5038_50380001_126_dialog_content = "(저기 웬 이상한 남자가 있네. 왠지 하나도 안 기쁜 표정인걸.)",
  ui_story_5038_50380001_127_dialog_content = "여러분, 좀 지나갈게요. 노약자를 배려해 주세요!",
  ui_story_5038_50380001_128_dialog_content = "저기요. 실례지만 지금 종서 형님 이륜거를 가로막고 계시거든요?",
  ui_story_5038_50380001_129_dialog_content = "뭐, 뭔가 했더니... 휠체어였잖아?!",
  ui_story_5038_50380001_130_dialog_content = "시, 실례했어요! 죄송합니다!",
  ui_story_5038_50380001_131_dialog_content = "괜찮소.\n그리고 리청 아우, 그런 표현을 쓸 필요는 없다고 몇 번이나 말하지 않았는가...",
  ui_story_5038_50380001_132_dialog_content = "내 아직 이토록 건장한데, 이런 일조차 손수 못할 성싶으냐.",
  ui_story_5038_50380001_133_dialog_content = "아, 아하핫! 그냥 인파를 빨리 빠져나오고 싶어서 그랬던 거예요!",
  ui_story_5038_50380001_134_dialog_content = "용주 특산품인 최고급 약재를 사고 싶어서 지금 몸이 근질근질하거든요!",
  ui_story_5038_50380001_135_dialog_content = "지나갑시다! 좀 비켜 보세요! 나이티움도 챙겨 왔다고!",
  ui_story_5038_50380001_136_dialog_content = "앞에 자리 비었으면 빨리빨리 좀 움직여요!",
  ui_story_5038_50380001_137_dialog_content = "으앗?! 미, 밀지 마세요!",
  ui_story_5038_50380001_138_dialog_content = "여러분, 모두 조용히 해 주세요.",
  ui_story_5038_50380001_139_dialog_content = "......",
  ui_story_5038_50380001_140_dialog_content = "신풍호가 정말 바뀌긴 한 모양이군. 선장도 처음 보는 얼굴이고.",
  ui_story_5038_50380001_141_dialog_content = "저는 린 가문의 상선 「신풍」의 신임 선장, 목월백이라고 해요.",
  ui_story_5038_50380001_142_dialog_content = "...확실히 이 배를 알아보는 린 가문 분들이 적지 않군요.",
  ui_story_5038_50380001_143_dialog_content = "반년 전, 용주 대륙에 계신 린 가문 가주님께 작은 변고가 있었어요.\n그래서 그동안 쌍사성에 상선을 보낼 수가 없었죠.",
  ui_story_5038_50380001_144_dialog_content = "용주와 아스트라 대륙 사이의 운항이 반년간 중단되는 바람에,\n고향을 그리워하셨을 동포분들이 많으셨겠죠.",
  ui_story_5038_50380001_145_dialog_content = "하지만 이젠 괜찮아요. 제가 이곳에 발을 디딘 순간부터...",
  ui_story_5038_50380001_146_dialog_content = "용주와 아스트라를 오가는 항로는 이미 <color=#FFB400>완전히 재개통</color>됐으니까요.",
  ui_story_5038_50380001_147_dialog_content = "...종서 형님, 저 사람들이 진짜로 배를 여기까지 몰고 왔네요!",
  ui_story_5038_50380001_148_dialog_content = "우리도 이제 용주로 돌아갈 수 있겠어요!",
  ui_story_5038_50380001_149_dialog_content = "......",
  ui_story_5038_50380001_150_dialog_content = "이렇게 갑자기 또 용주로 돌아갈 수 있게 된 거야? 아직 아무 계획도 못 세웠는데...",
  ui_story_5038_50380001_151_dialog_content = "그러게 말이야, 나도 동업자랑 술자리를 여러 건 잡아 놔서 한동안은 돌아갈 수가 없다고...",
  ui_story_5038_50380001_152_dialog_content = "이 배를 타고 용주로 돌아가고 싶으신 분은 승선권만 구매하시면 됩니다.",
  ui_story_5038_50380001_153_dialog_content = "그렇지만 운항 중 여러 변수가 발생할 수 있는 만큼,\n어느 정도의 <color=#FFB400>위험성</color>이 존재한다는 점은 명심해 주세요.",
  ui_story_5038_50380001_154_dialog_content = "뭐 어때, 린 가문이 운행하는 배는 항상 믿을 수 있었으니 괜찮겠지.\n승선권 세 장 주시오!",
  ui_story_5038_50380001_155_dialog_content = "그럼 저도 일단 한 장 주세요! 나중에 못 사는 것보단 나을 테니까...",
  ui_story_5038_50380001_156_dialog_content = "동포 여러분, 급할 거 없으니 서두르지 마시지요~",
  ui_story_5038_50380001_157_dialog_content = "신풍호의 출항까진 아직 시간이 꽤 남았습니다!",
  ui_story_5038_50380001_158_dialog_content = "소생이 방금 신풍호에서 내려와 보니, 이곳 주민들에게는 뭔가\n특별한 게 있다는 느낌이 확 오더군요.",
  ui_story_5038_50380001_159_dialog_content = "그러니 어느 귀인께서 소생에게 점도 한 번 보시고,\n겸사겸사 길도 좀 안내해 주시겠는지요?",
  ui_story_5038_50380001_160_dialog_content = "이천간, 이 천하의 사기꾼이 또 사람들을 속이려 드는구나...",
  ui_story_5038_50380001_161_dialog_content = "공주 전하, 소생은 사기꾼이 아닙니다!",
  ui_story_5038_50380001_162_dialog_content = "...전하! 조심하십시오!",
  ui_story_5038_50380001_163_dialog_content = "우르르르르르──",
  ui_story_5038_50380001_164_dialog_content = "이 신풍호, 저번에 봤을 때보다 훨씬 화려해진 것 같아!",
  ui_story_5038_50380001_165_dialog_content = "게다가 더 넓어진 것 같기도 하고...",
  ui_story_5038_50380001_166_dialog_content = "콜록, 콜록... 역시 구 소저는 언제나 참 민첩하시군요...",
  ui_story_5038_50380001_167_dialog_content = "<color=#e8d9bb>웅성웅성... 웅성웅성...</color>",
  ui_story_5038_50380001_168_dialog_content = "으... 으음...",
  ui_story_5038_50380001_169_dialog_content = "트위티, 왜 그래?",
  ui_story_5038_50380001_170_dialog_content = "지, 지도 신풍호를 구경하러 가고 싶심더...",
  ui_story_5038_50380001_171_dialog_content = "가면 지가 찾을라카는 물건도 볼 수 있을 겁니더...",
  ui_story_5038_50380001_172_dialog_content = "집배원 아가씨, 이걸 찾는 거지?",
  ui_story_5038_50380001_173_dialog_content = "우와와와! 빨간색 색지가 억수로 많네예!",
  ui_story_5038_50380001_174_dialog_content = "하모예! 바로 그기 필요했심더!",
  ui_story_5038_50380001_175_dialog_content = "출발 전에 들었거든. 연말부터 지금까지 쌍사성은 색지까지 부족할 만큼\n명절 용품 공급량이 원활하지 못했다고 말이야.",
  ui_story_5038_50380001_176_dialog_content = "그래서 아스트라 내륙 상회를 통해 물건을 들여오고, 집배원들에게 탁송까지 부탁한 거겠지.",
  ui_story_5038_50380001_177_dialog_content = "이제 용주에서 색지를 실어 왔으니까, 앞으론 이번처럼 힘든 일은 없을 거야.",
  ui_story_5038_50380001_178_dialog_content = "<size=50>우와아아아! 이자 드디어 자유를 얻었심더!</size>",
  ui_story_5038_50380001_179_dialog_content = "트위티가 드디어 업무에서 해방됐구나.",
  ui_story_5038_50380001_180_dialog_content = "세 사람은 아스트라 대륙의 내륙 쪽 사람들이지?",
  ui_story_5038_50380001_181_dialog_content = "...옷만 봐도 알았죠?",
  ui_story_5038_50380001_182_dialog_content = "후훗, 그럼 앞으로 잘 부탁해.",
  ui_story_5038_50380001_183_dialog_content = "신풍호는 한동안 아스트라 대륙에 정박해 있을 예정이야.",
  ui_story_5038_50380001_184_dialog_content = "그동안 같이 잘 지내보자.",
  ui_story_5038_50380001_185_dialog_content = "(와... 무표정에 쿨해 보이는 언니네!)",
  ui_story_5038_50380001_186_dialog_content = "조, 좋아요, 처음 뵙겠습니다. 전 PlayerName입니다...",
  ui_story_5038_50380001_187_dialog_content = "아스트라 대륙에 오신 걸 환영해요! 용주의 손님!",
  ui_story_5038_50380101_1_dialog_content = "<color=#e8d9bb>쌍사성 거리</color>",
  ui_story_5038_50380101_2_dialog_content = "(며칠간 우리는 쌍사성에 머물면서 오랜만의 휴식 시간을 즐겼다...)",
  ui_story_5038_50380101_3_dialog_content = "(춘삭절이 다가올 무렵의 쌍사성은 정말 마음을 편하게 만들어 주는 곳인 것 같다.)",
  ui_story_5038_50380101_4_dialog_content = "PlayerName, 거기서 멍하니 뭐 해?",
  ui_story_5038_50380101_5_dialog_content = "그냥, 우리가 여기서 벌써 며칠이나 쉰 건지 모르겠어서.",
  ui_story_5038_50380101_6_dialog_content = "그거라면 내가 확실히 기록해 뒀어.",
  ui_story_5038_50380101_7_dialog_content = "어디 보자, PlayerName 넌 첫 3일 동안은 이천간 씨와 함께\n동방 특색 먹거리를 파는 먹자골목에 갔었고...",
  ui_story_5038_50380101_8_dialog_content = "4일부터 6일 차에는 우리 모두 쌍사성에서 개최된 바둑 시합에 참가했어.",
  ui_story_5038_50380101_9_dialog_content = "6일부터 10일 차에는 단당 양이 개최하는 새해 서예 대회에 나갔다가\n처참하게 탈락했고...",
  ui_story_5038_50380101_10_dialog_content = "10일부터 15일 차에는...",
  ui_story_5038_50380101_11_dialog_content = "아, 알겠어... 이제 다 기억났어!",
  ui_story_5038_50380101_12_dialog_content = "아무튼 우리도 이제 슬슬 언제 돌아갈지 좀 생각해 봐야 할 것 같아.",
  ui_story_5038_50380101_13_dialog_content = "PlayerName 넌 천천히 생각해도 돼...\n근데 난 내일이면 일루미나로 돌아갈 거야.",
  ui_story_5038_50380101_14_dialog_content = "뭐? 벌써?!",
  ui_story_5038_50380101_15_dialog_content = "이맘때면 일루미나도 동계 특별 보급을 시행하거든.",
  ui_story_5038_50380101_16_dialog_content = "이제 가서 물자 보급 일을 좀 도와야 돼~",
  ui_story_5038_50380101_17_dialog_content = "나도 돌아갈 때가 됐어.\n매년 해온 대로 북방에서 베들레헴 폐하와 새해를 맞아야 하니까.",
  ui_story_5038_50380101_18_dialog_content = "중간에 지체되지 않았다면 북방에서 보낸 마차가 오늘 밤이면 여기 도착할 거야.",
  ui_story_5038_50380101_19_dialog_content = "카렌 너까지 가는 거야?!",
  ui_story_5038_50380101_20_dialog_content = "알겠어, 둘 다 조심해서 가. 그럼 내 휴일도 안녕이구나...",
  ui_story_5038_50380101_21_dialog_content = "하이고?! 이게 누구십니꺼!",
  ui_story_5038_50380101_22_dialog_content = "PlayerName 오빠야, 바이스 언니야, 카렌 언니야! 좋은 아침입니더!",
  ui_story_5038_50380101_23_dialog_content = "응, 트위티! 안녕!",
  ui_story_5038_50380101_24_dialog_content = "배송 일은 어떻게 됐어? 아직도 바빠?",
  ui_story_5038_50380101_25_dialog_content = "인자 개안심더. 정상적으로 돌아왔다 아입니꺼!",
  ui_story_5038_50380101_26_dialog_content = "편지도 한 통만 더 가따 주면 이걸로 시마이입니더!",
  ui_story_5038_50380101_27_dialog_content = "그래? 혹시 우리가 도와줄 거 있어? 내일까지는 아직 시간이 있으니까~",
  ui_story_5038_50380101_28_dialog_content = "고맙심더, 바이스 언니야, 근디 이번엔 지 혼자서도 할 수 있심더! 그라고...",
  ui_story_5038_50380101_29_dialog_content = "지는 하매 신풍호의 <color=#FFB400>승선권</color>도 사 놨다 아입니꺼!",
  ui_story_5038_50380101_30_dialog_content = "이번 편지는 해외 배송을 해야 캄미더.\n받는 사람 주소가 저 바다 건너 용주 대륙에 있거든예!",
  ui_story_5038_50380101_31_dialog_content = "그래가 때맞춰 배에 탈라꼬 다른 편지들은 싸게 배송을 끝내놨심더!",
  ui_story_5038_50380101_32_dialog_content = "나름대로 좋은 여행 기회가 되겠구나.",
  ui_story_5038_50380101_33_dialog_content = "헤헤, 억수로 기대되가 밤에 잠도 잘 못잤심더~",
  ui_story_5038_50380101_34_dialog_content = "확실히 최근 이틀간 사람들이 신풍호가 곧 용주로 떠난다고\n이런저런 이야기를 하는 것 같았어.",
  ui_story_5038_50380101_35_dialog_content = "으음, 사람들이 걱정하는 건 당연한 일이야.",
  ui_story_5038_50380101_36_dialog_content = "하지만 난 린 가문에서 왜 반년 동안 쌍사성에 배를 못 보냈는지,\n그 <color=#FFB400>내막</color>을 알고 있다구!",
  ui_story_5038_50380101_37_dialog_content = "그 저... 뉘십니꺼?",
  ui_story_5038_50380101_38_dialog_content = "아, 며칠 전에 휠체어 탄 아재를 도와준다 욕봤던 오빠야인갑네예!",
  ui_story_5038_50380101_39_dialog_content = "아하하! 딱히 도와드리거나 한 건 아니야.\n종서 형님은 내 친구이자, 내가 전담하는 환자거든.",
  ui_story_5038_50380101_40_dialog_content = "우린 지난번에 같이 린 가문의 배를 타고 여기 왔어.",
  ui_story_5038_50380101_41_dialog_content = "난 리청이라고 해.\n여기저기 돌아다니면서 아픈 사람들을 치료해 주는 「고양의 의사」야.",
  ui_story_5038_50380101_42_dialog_content = "야옹!",
  ui_story_5038_50380101_43_dialog_content = "히익?!",
  ui_story_5038_50380101_44_dialog_content = "사, 살찐이가... 와 여기 있심꺼?!",
  ui_story_5038_50380101_45_dialog_content = "어허... 작은꼬리, 말썽부리면 안 된다니까!\n미, 미안해. 일부러 그런 건 아니야!",
  ui_story_5038_50380101_46_dialog_content = "작은꼬리야, 자, 이리 오너라.",
  ui_story_5038_50380101_47_dialog_content = "역시 이 아이는 내 곁에 있는 것이 마음에 드는 모양이구나.",
  ui_story_5038_50380101_48_dialog_content = "그냥 형님 곁에 있는 고양이들을 좋아하는 거겠죠...",
  ui_story_5038_50380101_49_dialog_content = "잠깐 실례하겠습니다. 승선객 정보를 좀 확인할게요.",
  ui_story_5038_50380101_50_dialog_content = "세 분 모두 이번에 신풍호를 타고 용주로 가시는 게 맞나요?",
  ui_story_5038_50380101_51_dialog_content = "그렇심더!\n그렇소.\n맞아요.",
  ui_story_5038_50380101_52_dialog_content = "좋아요. 그럼 출발 전에 드릴 말씀이 몇 가지 있어요.",
  ui_story_5038_50380101_53_dialog_content = "용주 출신이신 두 분은 아마 린 가문에 전해지는 「항해의 법보」에\n대해 들어 보신 적이 있겠죠.",
  ui_story_5038_50380101_54_dialog_content = "린 가문이 그동안 별 탈 없이 원양 항해를 할 수 있었던 건\n확실히 그런 보물을 가지고 있었기 때문이 맞아요.",
  ui_story_5038_50380101_55_dialog_content = "하지만 하나밖에 없는 그 보물은 이미 사라졌고, 지금까지도 그걸 찾지 못했어요.",
  ui_story_5038_50380101_56_dialog_content = "그래서 이번 항해의 위험성을 숙지해 달라고 저번에도 말했던 거죠.",
  ui_story_5038_50380101_57_dialog_content = "법보가 사라졌다는 건, 기존의 경험에 의지할 수 없게 되었다는 뜻이고,\n이는 이번 항해가 일종의 탐색 과정이 될 수도 있다는 의미예요.",
  ui_story_5038_50380101_58_dialog_content = "여기까지 올 때는 마침 날씨가 좋아서 별문제 없이 도착할 수 있었죠.",
  ui_story_5038_50380101_59_dialog_content = "하지만 돌아갈 때도 똑같이 그러리라는 보장은 없어요.\n그래서 승선하시는 분들께 이 점을 확실히 알려드리는 거예요.",
  ui_story_5038_50380101_60_dialog_content = "만약 급한 사정이 있는 게 아니라면, 이번에는 탑승을 <color=#FFB400>삼가는 편</color>이 좋아요.",
  ui_story_5038_50380101_61_dialog_content = "(그게 바로 반년 전에 발생했다던 그 「변고」인 건가...)",
  ui_story_5038_50380101_62_dialog_content = "지, 지는 겁 하나도 안 남미더! 지는 월백 언니야의 실력을 믿십니더!",
  ui_story_5038_50380101_63_dialog_content = "후훗, 배짱이 아주 두둑하구나.",
  ui_story_5038_50380101_64_dialog_content = "우연이라고 해야 할지, 내가 가서 이런 사정을 설명했더니...",
  ui_story_5038_50380101_65_dialog_content = "승선권을 샀던 승객들은 하나도 빠짐없이 표를 환불해 갔거든.",
  ui_story_5038_50380101_66_dialog_content = "돌봐야 할 가족이 있다던 사람도 있었고, 갑자기 계획이 변경됐다는 사람도 있었어.",
  ui_story_5038_50380101_67_dialog_content = "그렇겠지. 목숨을 건 항해를 하고 싶은 사람은 아무래도 없을 테니까.",
  ui_story_5038_50380101_68_dialog_content = "바꿔 말하면 월백 언니야는 「목숨을 건 항해」를 하고 있다는 거 아입니꺼!",
  ui_story_5038_50380101_69_dialog_content = "...난 내가 이 상황을 잘 수습할 수 있을 거라고 믿거든.\n게다가 상황이 이렇게 된 데는 내 책임도 있고.",
  ui_story_5038_50380101_70_dialog_content = "허나 그렇게 말하는 것치고는 확신이 없는 것 같소만.",
  ui_story_5038_50380101_71_dialog_content = "<color=#FFB400>「나침반」</color>의 행방이 궁금하지 않소?",
  ui_story_5038_50380101_72_dialog_content = "?!",
  ui_story_5038_50380101_73_dialog_content = "린 가문 사람이신가요? 아니면...",
  ui_story_5038_50380101_74_dialog_content = "선장 누나, 긴장 안 해도 돼.\n우린 반년 전에 일어난 <color=#FFB400>그 사건</color>을 직접 겪은 사람들이거든.",
  ui_story_5038_50380101_75_dialog_content = "...뭐? 그럴 리가...\n그날 해적선의 공격에서 살아남은 이는 없었을 텐데...",
  ui_story_5038_50380101_76_dialog_content = "선장 누나도 몰랐을 정도라면, 그 해적들도 당연히 몰랐겠지~",
  ui_story_5038_50380101_77_dialog_content = "그리고 그날 바다에 가라앉지 않은 사람은 나랑 종서 형님뿐만이 아니야.",
  ui_story_5038_50380101_78_dialog_content = "그럼 당신이 종서 대인이신가요?",
  ui_story_5038_50380101_79_dialog_content = "그렇소.",
  ui_story_5038_50380101_80_dialog_content = "가주님께서 종 대인의 안위에 대해 무척 심려하고 계셔요.\n이렇게 살아 계시다는 것을 아시면 무척 기뻐하실 거예요.",
  ui_story_5038_50380101_81_dialog_content = "하하, 린 형도 몸을 피할 수 있었던 모양이군.",
  ui_story_5038_50380101_82_dialog_content = "운항을 재개할 용기를 낸 것을 보면 그대는 참으로 강단 있는 선장이오.",
  ui_story_5038_50380101_83_dialog_content = "게다가 그대가 쌍사성에 온 연유는 비단 무역 재개뿐만이 아니라,\n「나침반」의 행방을 찾기 위함이겠지.",
  ui_story_5038_50380101_84_dialog_content = "...말씀대로예요.",
  ui_story_5038_50380101_85_dialog_content = "꼭 이 배에 탑승하셔야겠다면, 제게 조금이나마 도움을 주셨으면 해요.",
  ui_story_5038_50380101_86_dialog_content = "물론이오. 자세한 이야기는 나중에 배에 오른 뒤에 하세.\n내륙에서 온 손님들을 계속 여기 세워 둘 수는 없으니 말이오.",
  ui_story_5038_50380101_87_dialog_content = "저, 저희 말씀하시는 건가요? 신경 안 써 주셔도 괜찮은데...",
  ui_story_5038_50380101_88_dialog_content = "아무튼 출항은 이틀 뒤이니 그때 항구에서 뵙도록 하죠.",
  ui_story_5038_50380101_89_dialog_content = "<color=#e8d9bb>이틀 뒤</color>",
  ui_story_5038_50380101_90_dialog_content = "오? PlayerName 아냐?",
  ui_story_5038_50380101_91_dialog_content = "배웅해 주러 온 거야?",
  ui_story_5038_50380101_92_dialog_content = "응, 카렌이랑 바이스는 벌써 북방이랑 일루미나로 돌아갔어.\n가면서 꼭 말을 좀 전해 달라고 하더라.",
  ui_story_5038_50380101_93_dialog_content = "항해가 순조롭길 바라고, 다음에 꼭 다시 아스트라 대륙에 방문해 달라고 말이야.",
  ui_story_5038_50380101_94_dialog_content = "사실 나도 똑같은 말을 하려고 했었어.",
  ui_story_5038_50380101_95_dialog_content = "서로 알게 된 지 며칠 안 됐지만, 작별을 해야 한다고 생각하니까 역시 좀 아쉽네.",
  ui_story_5038_50380101_96_dialog_content = "후훗, 아스트라 대륙 사람들의 표현 방식은 정말 솔직하구나.",
  ui_story_5038_50380101_97_dialog_content = "공주 전하께서도 한번 해 보시겠습니까?",
  ui_story_5038_50380101_98_dialog_content = "음... 그럼 나, 나도...",
  ui_story_5038_50380101_99_dialog_content = "PlayerName 공자를 기억할게.",
  ui_story_5038_50380101_100_dialog_content = "종서 형님이랑 이천간은 벌써 배에 타 있어. 이제 곧 출항할 거야.",
  ui_story_5038_50380101_101_dialog_content = "근데 그날 본 그 하얀 박새는 오늘 왜 안 보이지?",
  ui_story_5038_50380101_102_dialog_content = "...그러게. 트위티한테도 인사하려고 했었는데.",
  ui_story_5038_50380101_103_dialog_content = "<size=50>으아아아아!</size>",
  ui_story_5038_50380101_104_dialog_content = "<size=50>PlayerName 오빠야! 지 좀 살려주이소!</size>",
  ui_story_5038_50380101_105_dialog_content = "아! 트위티, 드디어 왔구나!",
  ui_story_5038_50380101_106_dialog_content = "편지랑 소포를 배송해야 카는디, 고마 끝이 안 보입니더!",
  ui_story_5038_50380101_107_dialog_content = "각중에 북방으로 보내는 긴급 우편 하나를 받았심더!\n근디 다른 사람들한테 쪼매 도와달라 카니까 다들 바빠서 안 댄다 카데예!",
  ui_story_5038_50380101_108_dialog_content = "북방은 날씨도 억수로 춥고, 길도 복잡해가 배송 경로를 잘 아는 게 지밖에 엄심더!",
  ui_story_5038_50380101_109_dialog_content = "그러니까... 설마 지금 나한테...",
  ui_story_5038_50380101_110_dialog_content = "그래가... PlayerName 오빠야한테 좀 도와 달라 카고 싶어가 찾아 왔심더.",
  ui_story_5038_50380101_111_dialog_content = "PlayerName 오빠야가 지 대신 용주에 함 다녀와 주이소.",
  ui_story_5038_50380101_112_dialog_content = "비용은 당연히 낼 깁니더! 다음 달에 월급을 받으면 마카 다 드리겠심더!",
  ui_story_5038_50380101_113_dialog_content = "(이 대화, 어째 좀 익숙한데...)",
  ui_story_5038_50380101_114_dialog_content = "나, 나야 물론 도와주고 싶긴 해. 중요한 건 의뢰비가 아니야!",
  ui_story_5038_50380101_115_dialog_content = "그것보다 내가 트위티 네 승선권을 써서 배에 타도 되는 거야?",
  ui_story_5038_50380101_116_dialog_content = "무슨 일이지?",
  ui_story_5038_50380101_117_dialog_content = "월백 언니야──! 그기 그라이까...",
  ui_story_5038_50380101_118_dialog_content = "아... 음... 그렇구나, 알겠어.",
  ui_story_5038_50380101_119_dialog_content = "원칙상 다른 사람의 승선권을 사용해 배에 탑승하는 건 허용하지 않아.",
  ui_story_5038_50380101_120_dialog_content = "히잉... 그라모 이를 우짭니꺼...",
  ui_story_5038_50380101_121_dialog_content = "하모 승선권이 있는 다른 사람을 찾아가 지 대신 용주에 편지 좀 가따 주라 캐야겠네예...",
  ui_story_5038_50380101_122_dialog_content = "그렇긴 하지만... PlayerName, 내가 신풍호의 선장으로서\n당신을 이 배에 초대할게. 우리와 동행해 줘.",
  ui_story_5038_50380101_123_dialog_content = "네?! 이렇게 갑자기요...?",
  ui_story_5038_50380101_124_dialog_content = "사실 이건 종 대인의 뜻이야.",
  ui_story_5038_50380101_125_dialog_content = "이틀 전에 난 종 대인과 대화를 나누고 난 뒤에서야,\n불현듯 「나침반」을 찾겠다는 결심이 섰어.",
  ui_story_5038_50380101_126_dialog_content = "그리고 대인께선 당신의 도움을 받는다면 일이 순조롭게 진행될 수도 있다고 하셨지.",
  ui_story_5038_50380101_127_dialog_content = "(순조롭게 진행돼...? 설마...\n내 감응 능력이 나도 모르는 새에 물건도 탐지할 수 있게 된 건가?)",
  ui_story_5038_50380101_128_dialog_content = "이번 귀환 여정에서 우린 처음 이곳에 오면서 쌓은 경험들을 가지고 있어.",
  ui_story_5038_50380101_129_dialog_content = "그리고 「나침반」이 사라졌을 당시 일을 직접 겪은 종 대인과 리청도 함께할 거야.",
  ui_story_5038_50380101_130_dialog_content = "공주 전하와 구, 그리고 이천간도 이 배를 보호하기 위해 각자 최선을 다할 거고.",
  ui_story_5038_50380101_131_dialog_content = "당신이 이 배의 선장인 날 믿을 수 있다면, 날 도와줬으면 해.",
  ui_story_5038_50380101_132_dialog_content = "(전에 린 가문 상회와 몇 번 교류가 있기도 했고,\n그쪽 친구들도 사귀기도 했으니까...)",
  ui_story_5038_50380101_133_dialog_content = "(이번 기회에 저 사람들에게 조금이나마 도움을 줄 수 있다면...)",
  ui_story_5038_50380101_134_option_content = "좋아요!",
  ui_story_5038_50380101_135_dialog_content = "흔쾌히 도와주겠다니 고마워. 그럼 배에서 기다리고 있을게, PlayerName.",
  ui_story_5038_50380101_136_dialog_content = "PlayerName 오빠야! 고, 고맙심더!",
  ui_story_5038_50380101_137_dialog_content = "그럼 지체하지 말고 어서 배에 올라오렴, PlayerName 공자!",
  ui_story_5038_50380101_138_dialog_content = "아, 알겠어요! 금방 갈게요!",
  ui_story_5038_50380101_139_dialog_content = "우냐앙──!",
  ui_story_5038_50380101_140_dialog_content = "어! 작은꼬리가 물고기를 봐 버렸어!",
  ui_story_5038_50380101_141_dialog_content = "그럼 못 써! 뛰어내리면 안 돼!",
  ui_story_5038_50380101_142_dialog_content = "냐앙...",
  ui_story_5038_50380101_143_dialog_content = "아스트라 대륙의 바닷바람은 용주보다 훨씬 매섭구나...",
  ui_story_5038_50380101_144_dialog_content = "출항하기 딱 좋은 날씨네.",
  ui_story_5038_50380101_145_dialog_content = "바람에 펄럭이는 신풍호의 깃발을 보면... 이건 남서풍이구나.",
  ui_story_5038_50380101_146_dialog_content = "좌우 갑판을 접어야 하니까 모두 자리에 앉아 주세요!",
  ui_story_5038_50380101_147_dialog_content = "신풍호, 출항!",
  ui_story_5038_50380201_1_dialog_content = "(린 가문의 상선은 규모가 진짜 놀라운 수준이네. 이렇게 큰 배는 처음 타 봐.)",
  ui_story_5038_50380201_2_dialog_content = "(게다가 갑판 쪽도 동방풍으로 화려하게 디자인돼 있어.)",
  ui_story_5038_50380201_3_dialog_content = "(갑판에서 내려다보니까 확실히 시야가 엄청나네...)",
  ui_story_5038_50380201_4_dialog_content = "(와~ 하늘도 푸르고, 파도 소리도 좋고, 바닷바람도 시원해...)",
  ui_story_5038_50380201_5_dialog_content = "어라?",
  ui_story_5038_50380201_6_dialog_content = "종서 님, 왜 혼자 여기서 물끄러미 바다만 보고 계세요?",
  ui_story_5038_50380201_7_dialog_content = "바닷물을 보고 있었소.",
  ui_story_5038_50380201_8_dialog_content = "바닷물에... 뭔가 이상한 점이라도 있는 건가요?",
  ui_story_5038_50380201_9_dialog_content = "바닷물이라는 것은 어느 곳에서 보아도 그 모습이 같아서,\n보고 있노라면 고향의 항구가 생각나오.",
  ui_story_5038_50380201_10_dialog_content = "고향을 그리워하고 계셨던 거군요.",
  ui_story_5038_50380201_11_dialog_content = "사실 출항하기 전까진 쌍사성의 그 많은 사람들이 저희랑 같이\n자기 고향에 돌아가려고 할 줄 알았어요.",
  ui_story_5038_50380201_12_dialog_content = "근데 마지막에 배에 탄 건 종서 님이랑 리청밖에 없었죠.",
  ui_story_5038_50380201_13_dialog_content = "무릇 사람이란 타지에서 떠도는 시간이 길어지면 항상 집이 그리워지기 마련이오.",
  ui_story_5038_50380201_14_dialog_content = "승선권을 물렀다 하여 저들이 용주를 그리워하지 않는 것은 아니오.\n다만 저들에게 있어 「고향」이라는 씨앗이 쌍사성에도 새싹을 틔운 것이겠지.",
  ui_story_5038_50380201_15_dialog_content = "저들에겐 새로운 가족과 새로운 친구가 생겼으니, 고향을 그리는 마음은\n마치 거울 속 꽃처럼 손에 닿지 않는 모호한 감정이 되었을 게요.",
  ui_story_5038_50380201_16_dialog_content = "이 종 모처럼 천지간에 아무도 없는 이나 미련 없이\n훌훌 털고 자유롭게 오갈 수 있는 법이오.",
  ui_story_5038_50380201_17_dialog_content = "왠지 무슨 말씀인지 알 것 같아요...",
  ui_story_5038_50380201_18_dialog_content = "하하, 젊은이가 이런 고리타분한 이야기에 흥미를 보일 줄은 몰랐소.",
  ui_story_5038_50380201_19_dialog_content = "이렇게 대화를 나누어 보니, 귀공과는 마음이 잘 통하는 듯하군.\n귀공도 날 「종서 님」이라고 부를 필요는 없소.",
  ui_story_5038_50380201_20_dialog_content = "종 모는 귀공과 벗이 되고 싶소. 벗 사이에 공대가 어인 말이오.",
  ui_story_5038_50380201_21_dialog_content = "리청 아우처럼 편히 불러 주게.",
  ui_story_5038_50380201_22_dialog_content = "네. 친구라면 저도 좋아요. 그래도 이름으로만 부르는 건 역시 좀...",
  ui_story_5038_50380201_23_dialog_content = "<color=#e8d9bb>촤악!</color>",
  ui_story_5038_50380201_24_dialog_content = "으앗?!",
  ui_story_5038_50380201_25_dialog_content = "뭐죠?! 갑자기 얼굴에 물벼락을 맞았어요!",
  ui_story_5038_50380201_26_dialog_content = "뭐긴 뭐야, 물고기 떼지.",
  ui_story_5038_50380201_27_dialog_content = "혹시 꼬리가 용처럼 생긴 물고기였다면, 그건 <color=#FFB400>교룡어</color>라고 해!",
  ui_story_5038_50380201_28_dialog_content = "까, 깜짝 놀랐어... 이렇게 높은 배 위에서도 얼굴에 물을 맞게 될 줄은 몰랐지!",
  ui_story_5038_50380201_29_dialog_content = "겨울은 녀석들이 왕성하게 활동하는 시기야. 번식기이기도 하고.",
  ui_story_5038_50380201_30_dialog_content = "교룡어들은 태어나자마자 무리를 지어 심해를 향해 이동해.",
  ui_story_5038_50380201_31_dialog_content = "아무리 멀리까지 이동했어도, 겨울만 되면 근처의 동료들과 무리를 이뤄.",
  ui_story_5038_50380201_32_dialog_content = "그리고 용주의 항구까지 돌아가서 수심이 얕은 곳에 알을 낳는 순환을 반복해.",
  ui_story_5038_50380201_33_dialog_content = "넌 저 물고기에 대해서 잘 아는 모양이구나?",
  ui_story_5038_50380201_34_dialog_content = "후후~ 린 가문 상회 쪽 사람한테 교룡어는 신앙의 대상이라고 할 수 있는 동물이거든.",
  ui_story_5038_50380201_35_dialog_content = "일종의 신물 같은 거라고나 할까?",
  ui_story_5038_50380201_36_dialog_content = "음, 왠지 알 것 같아. 아마 린 가문 사람들은 출항할 때마다\n그 교룡어들처럼 무사히 돌아올 수 있길 바라는 거겠지.",
  ui_story_5038_50380201_37_dialog_content = "복자께서 가라사대 「유자가교」라~ PlayerName 너 머리 좋구나~",
  ui_story_5038_50380201_38_dialog_content = "뭐야, 왜 어른이 애한테 말하는 것처럼 말하는 거야?!",
  ui_story_5038_50380201_39_dialog_content = "내가 겉보기엔 이래도, PlayerName 너보다 연상일 수도 있어.",
  ui_story_5038_50380201_40_dialog_content = "그러니까 PlayerName 너도 나한테 말할 때 예를 갖추는 편이 좋을걸...",
  ui_story_5038_50380201_41_dialog_content = "어랏? 킁킁... 킁킁킁... 이 고소한 냄새! 어디서 갑자기 생선 냄새가 나는 거지?!",
  ui_story_5038_50380201_42_dialog_content = "중식 시간이 됐거든.",
  ui_story_5038_50380201_43_dialog_content = "오늘은 출항 첫날이니 기운을 잘 보충해 두어야 해.",
  ui_story_5038_50380201_44_dialog_content = "PlayerName 공자도 한번 먹어 봐. 이건 용주의 특산 요리 <color=#FFB400>송서어</color>야!",
  ui_story_5038_50380201_45_dialog_content = "잡은 물고기의 뼈를 제거하고, 칼집을 내서 기름에 튀긴 다음에 새콤달콤한 양념을 뿌리고...",
  ui_story_5038_50380201_46_dialog_content = "자, 잠깐만! 그 요리에 무슨 물고기를 쓴 거야?!",
  ui_story_5038_50380201_47_dialog_content = "교룡어란다. 살이 아주 연하던걸.",
  ui_story_5038_50380201_48_dialog_content = "뭐어어어?!",
  ui_story_5038_50380201_49_dialog_content = "후훗, 농담이야. 화물창 안에 있던 판매용 물고기를 썼어.",
  ui_story_5038_50380201_50_dialog_content = "다른 이들은 이미 도착해 있을 테니 어서 선실로 들어가자.",
  ui_story_5038_50380201_51_dialog_content = "<color=#e8d9bb>신풍호, 선실</color>",
  ui_story_5038_50380201_52_dialog_content = "아아, 공주 전하의 요리 솜씨는 정말 대단하십니다!\n정통 송서어란 바로 이런 맛이 아니겠습니까!",
  ui_story_5038_50380201_53_dialog_content = "사기꾼이 하는 칭찬 같은 건 듣지 않겠어.",
  ui_story_5038_50380201_54_dialog_content = "게다가 모든 요리는 내가 아니라 구가 만든 거야.",
  ui_story_5038_50380201_55_dialog_content = "공주 전하께서도 요리 중에 도움을 주지 않으셨습니까.",
  ui_story_5038_50380201_56_dialog_content = "이토록 서로를 존중하는 주인과 하인이라니, 온 제나라를 뒤져봐도 또 있겠습니까?",
  ui_story_5038_50380201_57_dialog_content = "......",
  ui_story_5038_50380201_58_dialog_content = "미안하지만 전하께서는 제나라에 대한 이야기를 나누길 원치 않으십니다.",
  ui_story_5038_50380201_59_dialog_content = "그것보다 쌍사성에서 승선하신 린 가문 관련자 두 분께\n<color=#FFB400>그 사건 당시</color>의 상황을 듣고 싶습니다.",
  ui_story_5038_50380201_60_dialog_content = "암냠냠... 냠냠냠... 진짜 맛있네...",
  ui_story_5038_50380201_61_dialog_content = "작은꼬리야, 너도 먹어!",
  ui_story_5038_50380201_62_dialog_content = "야옹~",
  ui_story_5038_50380201_63_dialog_content = "이 꼬마 의원은 당분간은 고개를 들 생각이 없어 보이는걸.",
  ui_story_5038_50380201_64_dialog_content = "종 대인, 말씀해 주시죠.",
  ui_story_5038_50380201_65_dialog_content = "이 종 모를 믿겠다는 것인가.\n허나 이미 반년이 지난 일이고, 자세한 점은 차이가 있을지도 모르오.",
  ui_story_5038_50380201_66_dialog_content = "허면 내 그때의 전후곡절을 들려줄 터이니, 한 편의 이야기로 여기고 들어 보시오.",
  ui_story_5038_50380201_67_dialog_content = "여부가 있겠습니까! 소생이 각지를 떠돌아다니면서 가장 즐기는 것도\n바로 그런 기이한 이야기를 듣는 것이거든요.",
  ui_story_5038_50380201_68_dialog_content = "지금부터 하려는 이야기는 그리 가벼운 이야기는 못 될 것이오.",
  ui_story_5038_50380201_69_dialog_content = "엄밀히 말해 이 종 모와 리청 아우는 린 가문 사람이 아니오.\n여기 계신 선장이야말로 린 가문의 여식이지.",
  ui_story_5038_50380201_70_dialog_content = "종 대인, 편하게 말씀하세요.",
  ui_story_5038_50380201_71_dialog_content = "「목」 씨 성을 내걸고 있는 사람이 어딜 봐서 진짜 린 가문 사람이겠어요.",
  ui_story_5038_50380201_72_dialog_content = "미안하오, 종 모가 사려 깊지 못했소.\n내 선장의 성씨를 이야깃거리로 만들 생각은 아니었소.",
  ui_story_5038_50380201_73_dialog_content = "요컨대, 이 종 모는 린 가문과 오랜 교분이 있고, 리청 아우는 린 가문의 식객이오.",
  ui_story_5038_50380201_74_dialog_content = "또한 그 덕에 우리 두 사람은 그날의 변고에서 목숨을 부지할 수 있었소.",
  ui_story_5038_50380201_75_dialog_content = "반년 전, 린 가문에 대체 무슨 일이 있었던 거죠?",
  ui_story_5038_50380201_76_dialog_content = "그 사건의 시작과 끝은 모두 「나침반」과 관계가 있소.",
  ui_story_5038_50380201_77_dialog_content = "린 가문은 「나침반」의 힘을 통해 해상 무역을 장악했소.\n당연히 그 사실을 못마땅하게 여기는 자들이 있었지.",
  ui_story_5038_50380201_78_dialog_content = "이에 한 상회의 주도하에, 몇몇 작은 가문들이 연합하여 린 가문의 몰락을 꾀하려 하였소.",
  ui_story_5038_50380201_79_dialog_content = "물론 그들의 세력은 린 가문에 비하면 보잘것없었지만, 대신 수치를 모르는 이들이었지.",
  ui_story_5038_50380201_80_dialog_content = "그날, 우리 두 사람은 린 가문의 저택에서 열리는 연회에 참석했고,\n자리에는 린 가문의 측근들이 많이 와 있었소.",
  ui_story_5038_50380201_81_dialog_content = "그리고 연회가 무르익어 갈 때쯤,\n정체를 알 수 없는 무리가 난입하여 사람들을 해치기 시작했소...",
  ui_story_5038_50380202_1_dialog_content = "형님! 얼른 이쪽으로 오세요!",
  ui_story_5038_50380202_2_dialog_content = "다치진 않으셨죠?",
  ui_story_5038_50380202_3_dialog_content = "작은 상처다. 심려치 마라.",
  ui_story_5038_50380202_4_dialog_content = "린 형이라도 무사히 데리고 나올 수 있었다.",
  ui_story_5038_50380202_5_dialog_content = "가주님께서 무사하시다니 정말 다행이에요!",
  ui_story_5038_50380202_6_dialog_content = "허나 다른 이들은...",
  ui_story_5038_50380202_7_dialog_content = "오늘이 지나면 상인들의 천하에서 린 가문의 이름이 사라질지도 모른다.",
  ui_story_5038_50380202_8_dialog_content = "그럴 수가... 감히 린 가문의 안마당까지 들어와 이런 짓을 벌이다니...\n국법이 두렵지도 않은 걸까요?",
  ui_story_5038_50380202_9_dialog_content = "저들은 모두 생각 따위 없이 눈앞의 이익에 눈이 먼 자들이다.",
  ui_story_5038_50380202_10_dialog_content = "누군가 건넨 큰 사례를 받고, 목숨까지 걸어서 손을 더럽히러 온 것이겠지.",
  ui_story_5038_50380202_11_dialog_content = "내 짐작이 맞다면, 놈들의 목적은 「나침반」일 것이다.",
  ui_story_5038_50380202_12_dialog_content = "「나침반」요? 근데 「나침반」은 여기 없잖아요...",
  ui_story_5038_50380202_13_dialog_content = "저 무뢰배들은 그것을 아직 모른다.",
  ui_story_5038_50380202_14_dialog_content = "린 형은 이미 「나침반」을 지키기 위한 계획을 준비해 두었다.",
  ui_story_5038_50380202_15_dialog_content = "일이 어그러진다면... 린 가문에 화를 불러올 재액의 씨앗은 내 손으로 뿌리 뽑을 것이다.",
  ui_story_5038_50380202_16_dialog_content = "리청 아우, 따라오거라.",
  ui_story_5038_50380202_17_dialog_content = "그 후 우린 가까스로 전투에서 빠져나올 수 있었소.",
  ui_story_5038_50380202_18_dialog_content = "그리고 그제서야 그 무리의 목적은 린 가문의 가주가 아니었다는 것을 깨달았소.",
  ui_story_5038_50380202_19_dialog_content = "린 형은 그 즉시 「나침반」이 파괴되거나 탈취되지 않도록,\n친족에게 「나침반」의 호송을 맡기고 현장에서 떠나라 명했소.",
  ui_story_5038_50380202_20_dialog_content = "그리하여 「나침반」을 실은 옛 신풍호는 즉시 항구에서 머나번 바다를 향해 출항했지.",
  ui_story_5038_50380202_21_dialog_content = "나침반을 가지고 출항했단 말인가요? 이해가 조금 안 되는데요...\n바다로 나가면 뜻밖의 사고가 더 쉽게 일어나지 않나요?",
  ui_story_5038_50380202_22_dialog_content = "차라리 린 가문의 금고 같은 데 숨겨 놓는 편이 훨씬 더 나을 것 같은데...",
  ui_story_5038_50380202_23_dialog_content = "나무를 숨기려면 숲에, 바다의 산물을 숨기려면 바다에 숨겨야 제일 안전하거든.",
  ui_story_5038_50380202_24_dialog_content = "응? 그게 무슨 뜻이야...?",
  ui_story_5038_50380202_25_dialog_content = "「나침반」을 지닌 배는 바다에서도 방향을 잃지 않을 뿐만 아니라,\n절대로 뜻밖의 사고 없이 순조롭게 항해할 수 있게 돼.",
  ui_story_5038_50380202_26_dialog_content = "하지만...",
  ui_story_5038_50380202_27_dialog_content = "하지만 「나침반」이 결국엔 사라져 버렸다... 선장 누난 이걸 말하려는 거지?",
  ui_story_5038_50380202_28_dialog_content = "결국 「나침반」이 사라진 건 천재지변이 아니라 인재였어.",
  ui_story_5038_50380202_29_dialog_content = "......",
  ui_story_5038_50380202_30_dialog_content = "그 무뢰배들은 배를 타고 옛 신풍호를 뒤쫓아 왔소.",
  ui_story_5038_50380202_31_dialog_content = "그리고 그들의 난동 때문에 우리 두 사람은 바다에 떨어져 다시는 신풍호에 오를 수 없었소.",
  ui_story_5038_50380202_32_dialog_content = "선장도 알고 있겠지만, 그들은 끝내 「나침반」 탈취의 뜻을 이루지 못했소.\n그들이 성공했다면 항로가 이렇게 오랫동안 끊길 일도 없었겠지.",
  ui_story_5038_50380202_33_dialog_content = "허나 그 후 우리 두 사람과 해적선은 <color=#FFB400>거대한 폭풍</color>에 휘말려 버렸소.",
  ui_story_5038_50380202_34_dialog_content = "결국 종 모와 리청 아우를 제외한 모든 이가 목숨을 잃었소.",
  ui_story_5038_50380202_35_dialog_content = "이 두 다리도 그때 다치게 된 것이고 말이오.",
  ui_story_5038_50380202_36_dialog_content = "어느 해역에서 있었던 일인지 기억하고 계시나요?",
  ui_story_5038_50380202_37_dialog_content = "모르오. 내 항해를 업으로 삼은 이가 아닌 터라 방위를 판단할 수가 없었소.",
  ui_story_5038_50380202_38_dialog_content = "다행히 수요령이 선천적으로 지닌 영력 덕분인지, 리청 아우가 날 데리고\n아스트라 대륙으로 올 수 있었던 것이오.",
  ui_story_5038_50380202_39_dialog_content = "잠깐만요... <color=#FFB400>「수요령」</color>은 또 어떤 물건이죠?",
  ui_story_5038_50380202_40_dialog_content = "PlayerName, 너 정말 무례하구나. 수요령은 「물건」이 아니야.",
  ui_story_5038_50380202_41_dialog_content = "내가 가르쳐 줄게. 수요령은 쉽게 말하면 나처럼 꼬리나 귀가 달린 광령을 말하는 거야.",
  ui_story_5038_50380202_42_dialog_content = "참고로 말해주는 건데, 「작은꼬리」는 사실 우리 형이라구.",
  ui_story_5038_50380202_43_dialog_content = "하악──!",
  ui_story_5038_50380202_44_dialog_content = "아, 대충 알 것 같아.",
  ui_story_5038_50380202_45_dialog_content = "(광령은 오로리안이고... 수요령은 아인 혈통을 지닌 오로리안을 얘기하는 거겠지.\n용주에서는 아인족을 그렇게 부르는 모양이네.)",
  ui_story_5038_50380202_46_dialog_content = "린 가문의 기록에 따르면, 「나침반」은 지금껏 단 한 번도 사라졌던 선례가 없어요.",
  ui_story_5038_50380202_47_dialog_content = "비록 제 두 눈으로 직접 본 적은 없지만,\n「나침반」은 <color=#FFB400>「배와 운명을 함께 한다」</color>고 알려진 물건이니까요.",
  ui_story_5038_50380202_48_dialog_content = "여러분, 전 역시 옛 신풍호의 행방을 추적하고 싶어요.\n설령 배의 잔해만 찾게 된다 할지라도 말이에요.",
  ui_story_5038_50380202_49_dialog_content = "물론 여러분까지 종 대인께서 겪으셨던 그런 사고를 겪게 만들고 싶진 않아요.",
  ui_story_5038_50380202_50_dialog_content = "알겠어요. 이 자리의 모두를 위해서라도 벌써 희망을 포기해선 안 된다고 생각해요.",
  ui_story_5038_50380202_51_dialog_content = "선장 누나가 뭐라고 하든, 나도 꼭 「나침반」을 찾아낼 생각이야.",
  ui_story_5038_50380202_52_dialog_content = "좋아요, 곧 해가 저물겠네요. 오늘은 여기서 돛을 내리도록 하죠.",
  ui_story_5038_50380202_53_dialog_content = "이 배의 야간 경비는 저와 선원들이 맡을 테니, 모두 안심하고 쉬세요.",
  ui_story_5038_50380202_54_dialog_content = "나도 도울래!",
  ui_story_5038_50380202_55_dialog_content = "꼬마는 일찍 자야지.",
  ui_story_5038_50380202_56_dialog_content = "나 꼬마 아니라니까!",
  ui_story_5038_50380202_57_dialog_content = "그리고 나랑 작은꼬리는 원래 밤에 잠 잘 못 잔다구.",
  ui_story_5038_50380202_58_dialog_content = "리청 아우도 데리고 가 주게. 뜻대로 하게 두지 않으면 모두가 편히 잘 수 없을 터이니.",
  ui_story_5038_50380202_59_dialog_content = "형님! 저는 그런 짓 안 해요!",
  ui_story_5038_50380202_60_dialog_content = "알겠어요. 그럼 리청 너도 나와 함께 갑판으로 가자.",
  ui_story_5038_50380202_61_dialog_content = "침상은 객실 안에 있고, 모두 독립된 객실이에요.\n종 대인, 이쪽으로 오시죠. PlayerName, 당신도 따라와.",
  ui_story_5038_50380301_1_dialog_content = "<color=#e8d9bb>한밤중</color>",
  ui_story_5038_50380301_2_dialog_content = "휴...",
  ui_story_5038_50380301_3_dialog_content = "<color=#e8d9bb>우르릉...</color>",
  ui_story_5038_50380301_4_dialog_content = "(어? 천둥소린가...?)",
  ui_story_5038_50380301_5_dialog_content = "(왜 이렇게 흔들리지... 밖에 비라도 오나...?)",
  ui_story_5038_50380301_6_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5038_50380301_7_dialog_content = "뭐야?!",
  ui_story_5038_50380301_8_dialog_content = "방금 그 소린 뭐지?!",
  ui_story_5038_50380301_9_dialog_content = "<color=#e8d9bb>냐아앙──!</color>",
  ui_story_5038_50380301_10_dialog_content = "<color=#e8d9bb>우냐아아아──!</color>",
  ui_story_5038_50380301_11_dialog_content = "착하지... 일심, 무서워할 것 없다.",
  ui_story_5038_50380301_12_dialog_content = "단잠을 방해한 모양이군, 미안하오.",
  ui_story_5038_50380301_13_dialog_content = "이 세 고양이는 일심, 일몽, 일낙이라 하오.\n이 종 모와 생사고락을 함께했고, 옛 신풍호의 사고도 함께 겪었지...",
  ui_story_5038_50380301_14_dialog_content = "녀석들에게는 지금 이 광경이 그때의 악몽처럼 끔찍하게 느껴질 것이오.",
  ui_story_5038_50380301_15_dialog_content = "고양이 울음소리는 괜찮아요! 그것보다 조금 전에 난 그 소리 들으셨어요?!",
  ui_story_5038_50380301_16_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5038_50380301_17_dialog_content = "다들 일어나셨군요. 괜찮으십니까?",
  ui_story_5038_50380301_18_dialog_content = "구가 제일 먼저 이 소리를 듣고, 나와 함께 아직 잠들어 있는 승객들을\n깨우러 다니던 참이야.",
  ui_story_5038_50380301_19_dialog_content = "대체 무슨 일이죠?",
  ui_story_5038_50380301_20_dialog_content = "모르겠어. 다만 무언가가 신풍호의 선체와 충돌한 것 같구나!",
  ui_story_5038_50380301_21_dialog_content = "게다가... 그 무언가는 <color=#FFB400>하나</color>가 아닌 것 같습니다.",
  ui_story_5038_50380301_22_dialog_content = "(설마 한밤중에, 그것도 이런 바다 위에... 암귀가 나타나기라도 한 건가?)",
  ui_story_5038_50380301_23_dialog_content = "제가 갑판 쪽을 확인해 보고 올게요!",
  ui_story_5038_50380301_24_dialog_content = "소생도 PlayerName 공과 함께 다녀오겠습니다.",
  ui_story_5038_50380301_25_dialog_content = "종 대인께선 공주 전하와 저를 따라 피신하시지요.",
  ui_story_5038_50380301_26_dialog_content = "종 모의 기억이 맞다면, 아래층 선실에 도착하기 전에 내리막길이 하나 있을 것이오.",
  ui_story_5038_50380301_27_dialog_content = "예? 대인께서 그것을 어찌...",
  ui_story_5038_50380301_28_dialog_content = "새로운 신풍호라 하여도 내부 구조는 옛것과 판에 박은 듯 동일하오.",
  ui_story_5038_50380301_29_dialog_content = "자, 서두르세.",
  ui_story_5038_50380301_30_dialog_content = "젊은이, 한 가지만 당부하지.\n만약 리청 아우와 목 선장을 돕는 것이 버겁게 되거든...",
  ui_story_5038_50380301_31_dialog_content = "고집을 꺾고 지체 없이 둘을 데리고 아래로 몸을 피하게.",
  ui_story_5038_50380301_32_dialog_content = "네, 안심하고 맡겨 주세요.",
  ui_story_5038_50380301_33_dialog_content = "<color=#e8d9bb>신풍호, 갑판</color>",
  ui_story_5038_50380301_34_dialog_content = "빗줄기가 너무 세잖아...",
  ui_story_5038_50380301_35_dialog_content = "월백 씨! 리청!",
  ui_story_5038_50380301_36_dialog_content = "목 선장님! 야옹아!",
  ui_story_5038_50380301_37_dialog_content = "더는 무리입니다. 빗소리가 너무 커서 들리지도 않을 겁니다.",
  ui_story_5038_50380301_38_dialog_content = "아니면 그 감응인가 하는 것을 시도해 보는 건 어떻습니까?\n당신은 전설의 종족이라고 들었습니다만.",
  ui_story_5038_50380301_39_option_content = "(강제 감응!)",
  ui_story_5038_50380301_40_dialog_content = "음... 안 되겠어요. 미약한 힘들이 섞여 있어요.",
  ui_story_5038_50380301_41_dialog_content = "으음?!",
  ui_story_5038_50380301_42_dialog_content = "그리고 뭔가 느껴져요. 지금까지 느껴 본 적 없는 기운이에요...",
  ui_story_5038_50380301_43_dialog_content = "하나만 느껴지는 게 아니라, 단당 씨 경호원이 말했던 것처럼 여럿이 무리 지어 있어요!",
  ui_story_5038_50380301_44_dialog_content = "게다가 아주 강력한 에너지 하나가 느껴져요...",
  ui_story_5038_50380301_45_dialog_content = "조금 더 힘내봅시다, PlayerName 공!",
  ui_story_5038_50380301_46_dialog_content = "안 되겠어요, 이제 아무것도 안 느껴져요...",
  ui_story_5038_50380301_47_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5038_50380301_48_dialog_content = "<size=50><color=#e8d9bb>콰아앙!</color></size>",
  ui_story_5038_50380301_49_dialog_content = "으악! 조심해요!",
  ui_story_5038_50380301_50_dialog_content = "PlayerName 공, 소리가 들려오는 쪽으로 가 보도록 하죠!",
  ui_story_5038_50380301_51_dialog_content = "네...!",
  ui_story_5038_50380301_52_dialog_content = "이, 이게 무슨...",
  ui_story_5038_50380301_53_dialog_content = "작은꼬리! 버, 버둥대지 마!",
  ui_story_5038_50380301_54_dialog_content = "자꾸 그러면 떨어진다니까!",
  ui_story_5038_50380301_55_dialog_content = "선장 누나... 거긴 좀 괜찮아?!",
  ui_story_5038_50380301_56_dialog_content = "리청, 내 걱정은 말고 일단 떨어지지 않게 꽉 잡아!",
  ui_story_5038_50380301_57_dialog_content = "리청! 월백 씨!",
  ui_story_5038_50380301_58_dialog_content = "으앗?! PlayerName, 이천간?!",
  ui_story_5038_50380301_59_dialog_content = "두 사람이 여긴 왜 올라왔어?!",
  ui_story_5038_50380301_60_dialog_content = "어서 리청을 데리고 안전한 곳으로 피해!",
  ui_story_5038_50380301_61_dialog_content = "<size=50><color=#e8d9bb>콰아앙!</color></size>",
  ui_story_5038_50380301_62_dialog_content = "아... <color=#FFB400>교룡어</color>가!",
  ui_story_5038_50380301_63_dialog_content = "교룡어가 신풍호의 선복을 들이받고 있어! 선원!",
  ui_story_5038_50380301_64_dialog_content = "네! 갑니다!",
  ui_story_5038_50380301_65_dialog_content = "몇 명을 데리고 선창 맨 아래로 내려가서, 물이 들어오지 않게 수밀문을 닫아!",
  ui_story_5038_50380301_66_dialog_content = "알겠습니다!",
  ui_story_5038_50380301_67_dialog_content = "교룡어가...",
  ui_story_5038_50380301_68_dialog_content = "어째서... 왜 신풍호를 들이받는 거지?",
  ui_story_5038_50380301_69_dialog_content = "(리청이 말했던 교룡어가 바로 저 녀석들이었구나...)",
  ui_story_5038_50380301_70_dialog_content = "(여러 마리가 모여 있으니까 은색 고리 같아서 예쁘긴 한데... 힘이 무서울 정도로 세잖아!)",
  ui_story_5038_50380301_71_dialog_content = "<size=50><color=#e8d9bb>콰아앙!</color></size>",
  ui_story_5038_50380301_72_dialog_content = "야옹아! 거기 멍하게 서 있으면 안 돼요! 떨어지지 않게 난간에서 멀리 떨어지세요!",
  ui_story_5038_50380301_73_dialog_content = "리청, 어떻게 하면 교룡어들을 막을 수 있어?!",
  ui_story_5038_50380301_74_dialog_content = "모, 못 막아... 「나침반」이 없으면 아무것도 못 한다구...",
  ui_story_5038_50380301_75_dialog_content = "<size=50><color=#e8d9bb>쿵!</color></size>",
  ui_story_5038_50380301_76_dialog_content = "이런...",
  ui_story_5038_50380301_77_dialog_content = "내가 뱃머리를 안정시킬 테니까 어서 가! 조금은 시간을 벌 수 있을 거야!",
  ui_story_5038_50380301_78_dialog_content = "선체가 기울기 시작했어! 선원들과 함께 구명정에 타도록 해!",
  ui_story_5038_50380301_79_dialog_content = "잠깐만요!",
  ui_story_5038_50380301_80_dialog_content = "뭘 꾸물대고 있어?!",
  ui_story_5038_50380301_81_dialog_content = "느껴져요... 신풍호가 기울고 있는 건 교룡어 때문이 아니에요!",
  ui_story_5038_50380301_82_dialog_content = "...뭔가가 이 배에 탔어요... 그것도 아주 많이요...",
  ui_story_5038_50380301_83_dialog_content = "크오오...",
  ui_story_5038_50380301_84_dialog_content = "캬악!",
  ui_story_5038_50380301_85_dialog_content = "역시 이럴 때 가만히 있으면 암귀가 아니지!",
  ui_story_5038_50380301_86_dialog_content = "...PlayerName, 당신이 갑판 위로 올라와 준 게 신풍호에겐 행운이었던 모양이네.",
  ui_story_5038_50380301_87_dialog_content = "그럼 함께 녀석들을 처리하자!",
  ui_story_5038_50380302_1_dialog_content = "이제 다 해치웠어요!",
  ui_story_5038_50380302_2_dialog_content = "정말 큰 도움이 됐어, PlayerName.",
  ui_story_5038_50380302_3_dialog_content = "하지만 소생이 보기에는 배가 계속 기울고 있습니다만...",
  ui_story_5038_50380302_4_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5038_50380302_5_dialog_content = "일항사, 무거운 화물들을 선미로 옮겨서 선체의 균형을 맞추도록 해!",
  ui_story_5038_50380302_6_dialog_content = "예!",
  ui_story_5038_50380302_7_dialog_content = "물고기들이 뱃머리의 밧줄을 물고 있어서 암귀들이 쉽게 배에 오를 수 있었던 거야.",
  ui_story_5038_50380302_8_dialog_content = "PlayerName, 리청, 천간,\n괜찮다면 당신들도 선원들과 함께 선미 쪽으로 가 줬으면 좋겠어.",
  ui_story_5038_50380302_9_dialog_content = "알겠어요!",
  ui_story_5038_50380302_10_dialog_content = "자, 그럼 받으시죠, PlayerName 공!",
  ui_story_5038_50380302_11_dialog_content = "으앗?! 무거워! 이게 뭐예요?",
  ui_story_5038_50380302_12_dialog_content = "신풍호가 용주에서 운반해 온 철제 저울추입니다. 한 상자 가득 들어 있답니다.",
  ui_story_5038_50380302_13_dialog_content = "...그런 게 왜 한 상자나 있는 건데요!",
  ui_story_5038_50380302_14_dialog_content = "계산할 때든, 무게를 달 때든, 장사를 할 때든 꼭 쓰게 되는 물건이니까요!",
  ui_story_5038_50380302_15_dialog_content = "자, 보세요. 지금도 쓸모가 있잖아요?",
  ui_story_5038_50380302_16_dialog_content = "이 상자를 우리 둘이 하나씩 들고 선미 쪽에 갖다줘서,\n신풍호의 무게 중심을 「조절」해 줍시다!",
  ui_story_5038_50380302_17_dialog_content = "야옹이는 됐습니다. 그 덩치로는 못 들 테니 말이지요.",
  ui_story_5038_50380302_18_dialog_content = "아니, 난 여기 남을 거야.",
  ui_story_5038_50380302_19_dialog_content = "농담도 참, 착하지? 제 말 들으세요.",
  ui_story_5038_50380302_20_dialog_content = "말했잖아, 여기 남겠다고.",
  ui_story_5038_50380302_21_dialog_content = "(리청이 계속 바닷속을 보고 있어. 뭔가 찾는 중인가...?)",
  ui_story_5038_50380302_22_dialog_content = "리청, 너 혹시 교룡어들이 왜 저렇게 날뛰는지 알고 있는 거야? 뭐 아는 거 있어?",
  ui_story_5038_50380302_23_dialog_content = "아니, 이유는 나도 몰라...",
  ui_story_5038_50380302_24_dialog_content = "그치만 교룡어는 아무 이유 없이 먼저 공격해 오는 녀석들은 절대 아냐!",
  ui_story_5038_50380302_25_dialog_content = "분명히 저 무리 안에 있는 「우두머리」의 말을 듣고 있는 거겠지.",
  ui_story_5038_50380302_26_dialog_content = "「우두머리」가 대체 왜 이 배를 공격하라고 한 걸까? 녀석의 목적은 뭐지...?",
  ui_story_5038_50380302_27_dialog_content = "그러니까 일단 그 「우두머리」부터 찾으려는 거지?",
  ui_story_5038_50380302_28_dialog_content = "적어도... 녀석들이 어디서 왔는지 <color=#FFB400>방향</color>만이라도 알아내야 돼.",
  ui_story_5038_50380302_29_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5038_50380302_30_dialog_content = "(교룡어들이 날뛰는 기세가 갈수록 심해지고 있어. 계속 이렇게 내버려 뒀다간...)",
  ui_story_5038_50380302_31_option_content = "강제 감응!",
  ui_story_5038_50380302_32_dialog_content = "그런 것도 되는 겁니까?!",
  ui_story_5038_50380302_33_dialog_content = "모, 몰라요! 그래도 한 번 시도해 봐서 나쁠 건 없잖아요!",
  ui_story_5038_50380302_34_dialog_content = "(조금 전에 「본」 것처럼...)",
  ui_story_5038_50380302_35_dialog_content = "(동방에서 온 이 동물들을 감응해서... 다독여 보자...)",
  ui_story_5038_50380302_36_dialog_content = "(이런! 이번엔 별 소용이 없었나 봐!)",
  ui_story_5038_50380302_37_dialog_content = "교룡어들이 멈추고 있는 것 같아. PlayerName, 이거 봐!",
  ui_story_5038_50380302_38_dialog_content = "정말?! 내가 어쩌다 해낸 건가?!",
  ui_story_5038_50380302_39_dialog_content = "갑자기 헤엄치는 방향을 바꿔서, 고리 모양으로 모였는데...?",
  ui_story_5038_50380302_40_dialog_content = "...아니야! 뭔가 이상해!",
  ui_story_5038_50380302_41_dialog_content = "무, 무슨 뜻입니까?!",
  ui_story_5038_50380302_42_dialog_content = "다들! 얼른 난간을 잡고 엎드려!",
  ui_story_5038_50380302_43_dialog_content = "교룡어들이... 전부 덤벼들 거야!",
  ui_story_5038_50380302_44_dialog_content = "선장 누나! 얼른 신풍호의 방향을 돌려!",
  ui_story_5038_50380302_45_dialog_content = "(교룡어가 부딪히면서 받은 타격에 폭풍우까지...)",
  ui_story_5038_50380302_46_dialog_content = "(타륜이 전혀 제어가 안 돼...)",
  ui_story_5038_50380302_47_dialog_content = "모두 머리를 잘 감싸고, 떨어지지 않게 꽉 잡아!",
  ui_story_5038_50380302_48_dialog_content = "(바다여... 신풍호라는 이름을 또 부정하고 싶은 건가요...)",
  ui_story_5038_50380302_49_dialog_content = "<size=45><color=#e8d9bb>콰아앙!</color></size>",
  ui_story_5038_50380402_1_dialog_content = "으윽──!",
  ui_story_5038_50380402_2_dialog_content = "(온몸이 두들겨 맞은 것처럼 저려... 등도 엄청 아프고...)",
  ui_story_5038_50380402_3_dialog_content = "(나 아직 살아 있는 거... 맞지?)",
  ui_story_5038_50380402_4_dialog_content = "PlayerName, 괜찮아?",
  ui_story_5038_50380402_5_dialog_content = "워, 월백 씨! 살아 있었군요!",
  ui_story_5038_50380402_6_dialog_content = "다른... 사람들은요?",
  ui_story_5038_50380402_7_dialog_content = "해가 중천에 떴다구! 그만 자고 일어나, PlayerName!",
  ui_story_5038_50380402_8_dialog_content = "젊은이, 아마 크게 다친 곳은 없을 것이오.",
  ui_story_5038_50380402_9_dialog_content = "PlayerName 공자는 정말 걱정을 많이 끼치는구나.",
  ui_story_5038_50380402_10_dialog_content = "아직 머리가 지끈거리긴 하는데... 그래서 어젯밤엔 결국 어떻게 된 거죠?",
  ui_story_5038_50380402_11_dialog_content = "신풍호는 격한 충돌을 겪다가 제어 불능 상태가 됐었어.",
  ui_story_5038_50380402_12_dialog_content = "그러다 바다에 있던 암초와 부딪혀 버렸지.",
  ui_story_5038_50380402_13_dialog_content = "어젯밤에 날뛰던 교룡어 떼가 흩어지고 나니 비바람도 잠잠해졌어.",
  ui_story_5038_50380402_14_dialog_content = "선체가 격하게 흔들리던 와중에 당신과 이천간은 기절해 버렸고,\n선원들이 두 사람을 선실로 옮겨 준 거야.",
  ui_story_5038_50380402_15_dialog_content = "그래도 여기 꼬마 의원 리청이 약을 처방해 줘서, 두 사람에게 약을 먹여 두긴 했어.",
  ui_story_5038_50380402_16_dialog_content = "너한테 햇볕을 쬐어 주자고 한 것도 내가 낸 의견이었다구~",
  ui_story_5038_50380402_17_dialog_content = "몸이 뭔가 따뜻하고 노곤하네...",
  ui_story_5038_50380402_18_dialog_content = "읍?!",
  ui_story_5038_50380402_19_dialog_content = "으으, 내 입에 뭘 넣은 거야? 뭐가 이렇게 써!",
  ui_story_5038_50380402_20_dialog_content = "아! 그거 멀미약이야! 뱉으면 안 돼!",
  ui_story_5038_50380402_21_dialog_content = "동낭탕, 인동덩굴, 그리고 박하 조각이 들어 있어.",
  ui_story_5038_50380402_22_dialog_content = "몸에 좋은 약은 입에 쓴 법이니까 꾹 참아, PlayerName!",
  ui_story_5038_50380402_23_dialog_content = "아, 알겠어...",
  ui_story_5038_50380402_24_dialog_content = "그래도 이젠 서서 움직일 수 있을 정도로 회복됐으니까, 딱히 걱정할 필요는 없을 거야.",
  ui_story_5038_50380402_25_dialog_content = "그것보다 어제 그러고 나서 신풍호는 어떻게 됐는데요?",
  ui_story_5038_50380402_26_dialog_content = "썩 좋지 않아.",
  ui_story_5038_50380402_27_dialog_content = "돛대는 바람과 파도 때문에 부러졌고, 배의 하부도 침수된 상태야.",
  ui_story_5038_50380402_28_dialog_content = "굉장히 취약해진 상태라서, 풍랑이 다시 한번 거세진다면 아마 버텨낼 수 없겠지.",
  ui_story_5038_50380402_29_dialog_content = "그렇게 심각하다고요?!",
  ui_story_5038_50380402_30_dialog_content = "그 정도면 항해가 문제가 아니라 목숨이 위태롭단 거잖아요!",
  ui_story_5038_50380402_31_dialog_content = "...이 종 모가 그때 겪은 처지와 조금도 다름이 없군.",
  ui_story_5038_50380402_32_dialog_content = "난 지금까지 내 힘만으로도 항로를 다시 개통하고, 운항을 재개할 수 있으리라 생각했어.",
  ui_story_5038_50380402_33_dialog_content = "심지어는 이번에 「나침반」을 찾지 못한다 해도 무사할 수 있을 거라 여겼지.",
  ui_story_5038_50380402_34_dialog_content = "하지만 이제 보니... 린 가문은 역시 「나침반」의 가호가 필요했던 모양이네.",
  ui_story_5038_50380402_35_dialog_content = "어젯밤에 몰려왔던 교룡어들은 상태가 뭔가 이상했어.",
  ui_story_5038_50380402_36_dialog_content = "선장 누나도 린 가문 사람이니까 교룡어들의 습성을 잘 알 거잖아.",
  ui_story_5038_50380402_37_dialog_content = "원래 그 녀석들은 무리 지어 행동하는 걸 엄청 좋아하는 녀석들이라서,\n우두머리가 시킨 게 아니라면 그렇게 막무가내로 공격해 오지 않아.",
  ui_story_5038_50380402_38_dialog_content = "옛 기록 속의 교룡어들은 그랬었지.",
  ui_story_5038_50380402_39_dialog_content = "그런데 반년 전부턴 이 바닷속을 돌아다니는 교룡어들의 습성이 많이 바뀌었어.",
  ui_story_5038_50380402_40_dialog_content = "아무 이유 없이 바다를 오가는 배들을 공격하는 바람에 목숨을 잃은 뱃사람들도 있었지.",
  ui_story_5038_50380402_41_dialog_content = "난 목숨을 건 도박도 두렵지 않아.\n하지만 지금 여기엔 다른 이들의 목숨도 달려 있어.",
  ui_story_5038_50380402_42_dialog_content = "앞으로의 항해는 아무래도...",
  ui_story_5038_50380402_43_dialog_content = "무, 무슨 말이야?! 항해를 할 순 없다 해도, 그렇다고 여기서 계속 멈춰 있을 순 없어...",
  ui_story_5038_50380402_44_dialog_content = "이대로 가만히 있으면 영영 돌아갈 수가 없잖아!",
  ui_story_5038_50380402_45_dialog_content = "......",
  ui_story_5038_50380402_46_dialog_content = "선장 누나...",
  ui_story_5038_50380402_47_dialog_content = "어인 연유로 대낮부터 다들 울상이신지요?",
  ui_story_5038_50380402_48_dialog_content = "소생이 방금 점을 좀 쳐 봤습니다만, 어디 한 번 들어들 보시렵니까?",
  ui_story_5038_50380402_49_dialog_content = "지금 같은 상황에 또 무슨 요사스러운 농간을 부리려는 거야?",
  ui_story_5038_50380402_50_dialog_content = "요사스러운 농간이 아니옵니다.\n다른 사람은 몰라도, 목 선장님만큼은 반드시 제 말을 들어 보셔야 합니다.",
  ui_story_5038_50380402_51_dialog_content = "어째서?",
  ui_story_5038_50380402_52_dialog_content = "소생이 아까 굉장한 꿈을 꾸고 눈을 떴는데,\n이상하게도 갑자기 눈꺼풀이 몹시 떨리는 것이 아니겠습니까?",
  ui_story_5038_50380402_53_dialog_content = "그리고 어젯밤의 일을 떠올려 보니, 그 궁지 속에서 무언가 깨달음을 얻을 수 있었습니다.",
  ui_story_5038_50380402_54_dialog_content = "요점만 말해.",
  ui_story_5038_50380402_55_dialog_content = "예예, 그러지요, 여하튼 소생이 신풍호의 미래를 두고 점을 쳐 보았더니 괘가 세 개 나오더군요.",
  ui_story_5038_50380402_56_dialog_content = "소생의 만류천두괘는 겉으로는 음양과 십이지로 괘상을 보여주나,\n사실 그 안에는 거대한 천지 만물의 도리가 담겨 있답니다.",
  ui_story_5038_50380402_57_dialog_content = "애석한 것은 소생이 점만 볼 줄 알지, 신풍호에 대해서는 아는 것이 없다는 점이지요.",
  ui_story_5038_50380402_58_dialog_content = "그러니 소생이 그 세 가지 괘의 진정한 의미를 풀어낼 수 있도록\n목 선장님께서 도움을 주셨으면 합니다.",
  ui_story_5038_50380402_59_dialog_content = "뜸 들이지 말고 바로 말해 봐.",
  ui_story_5038_50380402_60_dialog_content = "지금 신풍호는 지푸라기라도 잡아야 할 상황이니까.",
  ui_story_5038_50380402_61_dialog_content = "그 괘라는 것이 얼마나 기이한지, 각각 갈팡질팡하는 쥐를 뜻하는 「수서양단」,\n분수를 모르고 날뛰다 물에 빠진 원숭이를 뜻하는 「원후취월」,\n꾀가 많아 굴을 세 개 파 놓는 토끼를 뜻하는 「교토삼굴」이었지 뭡니까.",
  ui_story_5038_50380402_62_dialog_content = "소생이 살면서 이렇게 풀이하기 어려운 점괘는 일찍이 만나 본 적이 없었습니다.",
  ui_story_5038_50380402_63_dialog_content = "세 가지 괘의 음양은 완전히 동일하니, 분명 한 가지 일을 가리키는 것일 텐데 말이지요.",
  ui_story_5038_50380402_64_dialog_content = "쥐, 원숭이, 토끼...?",
  ui_story_5038_50380402_65_dialog_content = "천간, 당신은 어떻게 생각하는데?",
  ui_story_5038_50380402_66_dialog_content = "뱃일에는 문외한인 소생의 추측이라도 말씀드리자면,\n이 점괘들은 「이물역물」, 즉 맞바꿈을 뜻하지 않나 싶습니다.",
  ui_story_5038_50380402_67_dialog_content = "이른바 가짜를 진짜라 여기는 순간, 진짜는 가짜가 되는 것 아니겠습니까.\n그러니 적당한 <color=#FFB400>대체품</color>을 찾아야 한다는 것이지요.",
  ui_story_5038_50380402_68_dialog_content = "「적당한 대체품」이라...",
  ui_story_5038_50380402_69_dialog_content = "점괘가 뜻하는 바를 알 것 같아.",
  ui_story_5038_50380402_70_dialog_content = "용주에는 선체 중요 부위의 이름을 지을 때, 십이지 속 동물들의 이름을 쓰는 풍습이 있어.",
  ui_story_5038_50380402_71_dialog_content = "그렇게 하면 길한 의미를 담을 뿐만 아니라,\n그 동물들처럼 항해가 순탄하길 기원하는 거지.",
  ui_story_5038_50380402_72_dialog_content = "하지만 어젯밤의 풍랑 때문에 선체의 여러 부분이 피해를 입었어.",
  ui_story_5038_50380402_73_dialog_content = "신풍호 선미의 「쥐 꼬리」는 없어져 버렸고, 선두의 「원숭이 머리」는 파괴됐지...",
  ui_story_5038_50380402_74_dialog_content = "대신 「토끼 귀」에는 별문제가 없어.",
  ui_story_5038_50380402_75_dialog_content = "「토끼 귀」는 소생이 조금 더 생각을 해 보겠습니다.",
  ui_story_5038_50380402_76_dialog_content = "헌데 배의 꼬리와 머리 부분을 대체할 부품들만 찾는다면,\n신풍호는 정상적으로 운행할 수 있는 것입니까?",
  ui_story_5038_50380402_77_dialog_content = "선체 복구에는 어느 정도 도움이 되겠지. 하지만 그걸로 해결될 일이 아니야.",
  ui_story_5038_50380402_78_dialog_content = "선체에 파손된 부분이 너무 많아.\n요령을 피울 여지도 없이 하나하나 고칠 수밖에 없어.",
  ui_story_5038_50380402_79_dialog_content = "게다가 교체할 부품들을 어디서 구할 수 있겠어?",
  ui_story_5038_50380402_80_dialog_content = "그런 사정이라면 종 모가 보기엔 가망이 있소.",
  ui_story_5038_50380402_81_dialog_content = "우리 발아래의 이 대양은 드넓은 「보물 창고」와 다름없지 않은가.",
  ui_story_5038_50380501_1_dialog_content = "(종서 씨랑 월백 씨 제안대로, 우린 구명정에 타는 대신 신풍호를 계속 쓰기로 했다.)",
  ui_story_5038_50380501_2_dialog_content = "(선원들은 벌써 돛을 펼친 뒤다.)",
  ui_story_5038_50380501_3_dialog_content = "(정말 이대로 항해를 다시 시작할 수... 있는 걸까?)",
  ui_story_5038_50380501_4_dialog_content = "이는 무척 불확실하고도 위험한 결정이오.",
  ui_story_5038_50380501_5_dialog_content = "이 바다에는 셀 수 없이 많은 배들이 가라앉아 있소.\n만약 신풍호가 종 모와 리청 아우가 변을 당했던 그곳에 당도할 수만 있다면...",
  ui_story_5038_50380501_6_dialog_content = "대체품으로 쓸 만한 부품을 건질 수 있을 것이오.",
  ui_story_5038_50380501_7_dialog_content = "물론 이는 바다에 떨어진 바늘을 찾는 격임은 종 모도 잘 알고 있소.",
  ui_story_5038_50380501_8_dialog_content = "허나 모든 졸책 중에서 가장 나은 방법은 이것뿐이오.",
  ui_story_5038_50380501_9_dialog_content = "종 대인 말씀이 맞아요.",
  ui_story_5038_50380501_10_dialog_content = "신풍호가 갖추고 있는 구명정으로는 큰 파도나 바람을 막을 수 없어요.",
  ui_story_5038_50380501_11_dialog_content = "저희도 바다에서 오래 버틸 수 없을 테고요.",
  ui_story_5038_50380501_12_dialog_content = "그러니 파도와 바람이 잔잔해졌을 때, 노를 저어 천천히 이동하는 편이\n여기 가만히 있는 것보단 나을 거예요.",
  ui_story_5038_50380501_13_dialog_content = "선원들, 힘들겠지만 파괴된 돛을 접고 노를 잡아 줘.",
  ui_story_5038_50380501_14_dialog_content = "이제부터 우린 해도에 나와 있는 표식을 따라 노를 저어\n반년 전의 사건이 발생했던 곳까지 이동할 거야.",
  ui_story_5038_50380501_15_dialog_content = "선장님 명령이라 따르긴 하겠지만, 너무 무모한 결정 아닌가요...",
  ui_story_5038_50380501_16_dialog_content = "배에 있을 땐 괜히 밉보일 소리 하지 말자고.",
  ui_story_5038_50380501_17_dialog_content = "어차피 바다에서 사고가 나면, 우리 목숨이 어디 우리 마음대로 될 일인가.",
  ui_story_5038_50380501_18_dialog_content = "어찌 선원이라는 자들이 선장을 두고 등 뒤에서 왈가왈부하느냐?",
  ui_story_5038_50380501_19_dialog_content = "고, 공주 전하...",
  ui_story_5038_50380501_20_dialog_content = "불만이 있다면 당당히 의견을 밝히고 모두와 함께 해결할 방법을 모색해야 마땅하거늘.",
  ui_story_5038_50380501_21_dialog_content = "한 치 앞도 모르는 바다에서 목숨도 건 사람들이면서, 고작 밉보이는 게 무섭느냐?",
  ui_story_5038_50380501_22_dialog_content = "무슨 소란이죠?",
  ui_story_5038_50380501_23_dialog_content = "월백, 이자들이 그대에게 할 말이 있다고 하는구나.",
  ui_story_5038_50380501_24_dialog_content = "아, 아니에요. 그런 적 없습니다...",
  ui_story_5038_50380501_25_dialog_content = "저도 마찬가지입니다. 공주 전하, 이러지 마십시오...",
  ui_story_5038_50380501_26_dialog_content = "......",
  ui_story_5038_50380501_27_dialog_content = "<color=#e8d9bb>스륵──!</color>",
  ui_story_5038_50380501_28_dialog_content = "서, 선장님! 용서해 주십시오! 제가...",
  ui_story_5038_50380501_29_dialog_content = "뒤를 봐.",
  ui_story_5038_50380501_30_dialog_content = "예...?",
  ui_story_5038_50380501_31_dialog_content = "그어억...",
  ui_story_5038_50380501_32_dialog_content = "백주대낮에 배에 올라 몹쓸 짓을 하려 하다니! 정말 채신머리도 없구나!",
  ui_story_5038_50380501_33_dialog_content = "저런 것들에게 무슨 처신이 있겠어요.",
  ui_story_5038_50380501_34_dialog_content = "두 사람, 내 뒤로 피해 있어.",
  ui_story_5038_50380501_35_dialog_content = "선장으로서 내 선원들이 멋대로 당하게 두진 않을 거니까.",
  ui_story_5038_50380501_36_dialog_content = "네... 알겠습니다! 선장님!",
  ui_story_5038_50380602_1_dialog_content = "「쥐 꼬리」, 「원숭이 머리」, 「토끼 귀」...",
  ui_story_5038_50380602_2_dialog_content = "직업이 다르면 서로 다른 세계라더니, 진짜 이름만 봐서는 뭔지 전혀 모르겠네.",
  ui_story_5038_50380602_3_dialog_content = "간단히 설명하면 각각 풍향계, 도르래, 나무판을 말하는 거야.",
  ui_story_5038_50380602_4_dialog_content = "<color=#FFB400>풍향계</color>는 돛대 가장 높은 곳에 고정돼 있어야 해.",
  ui_story_5038_50380602_5_dialog_content = "끝부분에 끈이 묶여 있는 게 꼭 쥐의 꼬리를 닮았거든. 그래서 「쥐 꼬리」라고 불러.",
  ui_story_5038_50380602_6_dialog_content = "「쥐 꼬리」는 무척 가벼워서 물에 빠져도 금방 수면으로 떠오를 거야.",
  ui_story_5038_50380602_7_dialog_content = "<color=#FFB400>도르래</color>는 흔히 보이는 그 도르래가 맞아. 돛을 올릴 때 쓰는 거고.",
  ui_story_5038_50380602_8_dialog_content = "동그랗게 생기기도 했고, 크기도 마침 원숭이 머리 정도라서\n「원숭이 머리」라고 부르는 거야.",
  ui_story_5038_50380602_9_dialog_content = "이 두 개의 대체품만 찾으면 신풍호를 다시 운항할 수 있어.",
  ui_story_5038_50380602_10_dialog_content = "와, 생각했던 것보다 간단할 것 같은데?",
  ui_story_5038_50380602_11_dialog_content = "근데 마지막으로 말한 「토끼 귀」는 뭐야?",
  ui_story_5038_50380602_12_dialog_content = "...그건 조금 특별해. 쉽게 다른 대체품으로 교환할 수 있는 게 아냐.",
  ui_story_5038_50380602_13_dialog_content = "다행히 「토끼 귀」는 파손되지 않았으니까,\n일단은 「쥐 꼬리」와 「원숭이 머리」부터 찾자.",
  ui_story_5038_50380602_14_dialog_content = "좋아, 알겠어!",
  ui_story_5038_50380602_15_dialog_content = "PlayerName, 단당 공주님, 도와줄 거지?",
  ui_story_5038_50380602_16_dialog_content = "그거야 당연하지!",
  ui_story_5038_50380602_17_dialog_content = "(저, 전부 무슨 말인지 하나도 이해가 안 돼...!)",
  ui_story_5038_50380602_18_dialog_content = "공주 전하, 무리하지 마십시오.\n전하께서는 제나라에 계실 적에도 궁 밖으로 나가신 적이 거의 없지 않으십니까.",
  ui_story_5038_50380602_19_dialog_content = "이해가 잘 되지 않으시는 것 또한 당연한 일입니다.",
  ui_story_5038_50380602_20_dialog_content = "...그래도 나 역시 모두를 위해 무언가 하고 싶어.",
  ui_story_5038_50380602_21_dialog_content = "내가 무리하지 않아도 된다고 생각한다면, 너도 날 애써 쫓아다닐 필요는 없어.",
  ui_story_5038_50380602_22_dialog_content = "고, 공주 전하...",
  ui_story_5038_50380602_23_dialog_content = "정말 제멋대로네~",
  ui_story_5038_50380602_24_dialog_content = "공주 전하를 그렇게 무례하게 평하지 마세요.",
  ui_story_5038_50380602_25_dialog_content = "네, 네~ 그럼 이제 슬슬 움직이자, PlayerName.",
  ui_story_5038_50380602_26_dialog_content = "근데... 어디 가서 뭘 해야 대체품을 찾을 수 있을까? 우린 단서도 없잖아.",
  ui_story_5038_50380602_27_dialog_content = "음, 내 생각엔...",
  ui_story_5038_50380602_28_dialog_content = "일단은 나랑 작은꼬리의 후각으로 찾아보자. 반대편 갑판 쪽 냄새부터 맡아 보는 거야!",
  ui_story_5038_50380602_29_dialog_content = "우리 리화묘는 쥐 꼬리 냄새는 기가 막히게 잘 알아차리거든!",
  ui_story_5038_50380602_30_dialog_content = "...지금 찾는 게 진짜 쥐 꼬리는 아니잖아!",
  ui_story_5038_50380602_31_dialog_content = "<color=#e8d9bb>신풍호, 선실</color>",
  ui_story_5038_50380602_32_dialog_content = "에잇...",
  ui_story_5038_50380602_33_dialog_content = "(여기도 한 번 찾아보자...)",
  ui_story_5038_50380602_34_dialog_content = "공주 전하, 뭘 그리 찾고 계십니까?",
  ui_story_5038_50380602_35_dialog_content = "그대와는 상관없다.",
  ui_story_5038_50380602_36_dialog_content = "그리 말씀하시면 섭섭하지요. 이렇게 대책 없이 찾기만 하느니,\n차라리 소생이 점을 쳐 드리겠습니다.",
  ui_story_5038_50380602_37_dialog_content = "...그대는 협잡을 하는 데에도 정말 고집이 세구나.",
  ui_story_5038_50380602_38_dialog_content = "협잡이 아니라는 것은 조금 전에 소생이 증명해 보이지 않았습니까?",
  ui_story_5038_50380602_39_dialog_content = "멋대로 해라... 되는대로 늘어놓는 것도 그 정도면 재능이니.",
  ui_story_5038_50380602_40_dialog_content = "내가 찾는 물건은 선장이 말했던 「쥐 꼬리」라는 물건이야.",
  ui_story_5038_50380602_41_dialog_content = "그걸 배에서 찾고 계신 겁니까?",
  ui_story_5038_50380602_42_dialog_content = "맞아. 내가 이해한 바를 토대로 일단 난 이렇게 판단했어.",
  ui_story_5038_50380602_43_dialog_content = "선장은 「쥐 꼬리」라는 것은 물에 빠지더라도 이내 떠오를 정도로 무척 가볍다고 했어.",
  ui_story_5038_50380602_44_dialog_content = "게다가 선원들은 어젯밤 사건 이후부터 지금까지 끊임없이 오가며 순찰을 하고 있어.",
  ui_story_5038_50380602_45_dialog_content = "린 가문 상회의 선원들은 바다에 바늘 하나가 빠졌다 해도\n찾아낼 수 있을 정도로 노련한 이들이야.",
  ui_story_5038_50380602_46_dialog_content = "그런 그들의 눈에 발견되지 않았다는 것은 필경 바다가 아닌 배에 있다는 것이겠지.",
  ui_story_5038_50380602_47_dialog_content = "역시 공주 전하께서는 참으로 총명하십니다~\n소생 역시 전하의 판단이 옳다 생각합니다.",
  ui_story_5038_50380602_48_dialog_content = "그렇다면 소생과 함께 배를 수색해 봄이 어떠신지요?",
  ui_story_5038_50380602_49_dialog_content = "다언, 다어!",
  ui_story_5038_50380602_50_dialog_content = "알겠다, 알겠다.",
  ui_story_5038_50380602_51_dialog_content = "그만 닦달해, 그만 닦달해.",
  ui_story_5038_50380602_52_dialog_content = "팔가조가 사람 말을 해?!",
  ui_story_5038_50380602_53_dialog_content = "소생이 훈련을 시켜, 사람의 말을 흉내 내는 것만큼은 무척 잘합니다.",
  ui_story_5038_50380602_54_dialog_content = "자, 다언, 다어, 가서 「쥐 꼬리」가 묶여 있는 풍향계를 찾아보세요.",
  ui_story_5038_50380602_55_dialog_content = "찾아내면 상을 줄 테니까요.",
  ui_story_5038_50380602_56_dialog_content = "<color=#e8d9bb>푸드덕... 푸드덕...</color>",
  ui_story_5038_50380602_57_dialog_content = "왜 이번에는 「점」을 치지 않는 거지?",
  ui_story_5038_50380602_58_dialog_content = "양금택목이란 말이 있지 않습니까?\n이럴 때는 높이 나는 새의 눈이 점보다 더 용하지요.",
  ui_story_5038_50380602_59_dialog_content = "가시지요, 공주 전하. 어서 녀석들을 따라가야 합니다.",
  ui_story_5038_50380602_60_dialog_content = "곧 쥐 꼬리를 찾아내 버릴 테니까요.",
  ui_story_5038_50380602_61_dialog_content = "<color=#e8d9bb>까아악── 까아악──</color>",
  ui_story_5038_50380602_62_dialog_content = "천년 고목에 열린 대추 줘!",
  ui_story_5038_50380602_63_dialog_content = "노릇노릇 향긋향긋 호박씨 줘!",
  ui_story_5038_50380602_64_dialog_content = "그래요, 알겠어요. 상은 잊지 않고 줄 테니까요. 그래서 찾았나요?",
  ui_story_5038_50380602_65_dialog_content = "이건...",
  ui_story_5038_50380602_66_dialog_content = "짐승의 꼬리처럼 생긴 걸 보면, 선장이 말했던 「쥐 꼬리」라는 게 분명해!",
  ui_story_5038_50380602_67_dialog_content = "오오! 소생이 보기에도 그렇습니다!",
  ui_story_5038_50380602_68_dialog_content = "미처 못 치운 진흙더미 속에 파묻혀 있던 걸 용케도 찾아냈군요.",
  ui_story_5038_50380602_69_dialog_content = "곧 상으로 맛 좋은 대추, 용안, 호박씨를 주도록 하죠.",
  ui_story_5038_50380602_70_dialog_content = "받으시지요, 공주 전하.",
  ui_story_5038_50380602_71_dialog_content = "어서 이 「쥐 꼬리」를 목 선장님께 주세요.",
  ui_story_5038_50380701_1_dialog_content = "(단당 씨가 월백 씨한테 「쥐 꼬리」를 건네주고 나서...)",
  ui_story_5038_50380701_2_dialog_content = "(배의 수리 상황에는 많은 진전이 있었고, 돛대도 어느 정도 수리가 끝났다.)",
  ui_story_5038_50380701_3_dialog_content = "(덕분에 신풍호의 항해 효율은 사고 전과 별 차이가 없을 정도로 많이 향상됐다.)",
  ui_story_5038_50380701_4_dialog_content = "(하지만...)",
  ui_story_5038_50380701_5_dialog_content = "풍향이 바뀌었다! 즉시 노를 멈추고 닻을 내려라!",
  ui_story_5038_50380701_6_dialog_content = "네!",
  ui_story_5038_50380701_7_dialog_content = "(걸핏하면 이렇게 긴급 정지를 해야 한다는 점은 여전했다.)",
  ui_story_5038_50380701_8_dialog_content = "젊은이, 걱정이 많아 보이는군.",
  ui_story_5038_50380701_9_dialog_content = "아니에요... 전 월백 씨의 판단력을 믿으니까요.",
  ui_story_5038_50380701_10_dialog_content = "감정을 숨기기 위해 그리 애쓸 필요 없소. 종 모 또한 귀공과 같은 생각이니 말이오.",
  ui_story_5038_50380701_11_dialog_content = "(다 들켜버렸네...)",
  ui_story_5038_50380701_12_dialog_content = "비록 린 가문의 해도를 따라 「나침반」이 사라졌던 곳으로 향하고 있기는 하나...",
  ui_story_5038_50380701_13_dialog_content = "배의 상태가 좋지 않고, 수리를 했다 한들 이는 임시방편에 불과하오.",
  ui_story_5038_50380701_14_dialog_content = "항해라는 것은 사소한 것 하나도 소홀히 해서는 아니 될 매우 세심한 일이오.",
  ui_story_5038_50380701_15_dialog_content = "막연한 바람만으로는 일을 순조롭게 이룰 수 없는 법이지.",
  ui_story_5038_50380701_16_dialog_content = "...말은 이렇게 하였으나, 이 또한 종 모의 기우에 불과할 것이오.",
  ui_story_5038_50380701_17_dialog_content = "그러니 젊은이는 개의치 말게.",
  ui_story_5038_50380701_18_dialog_content = "네, 저도 제 마음을 다스려 볼게요. 종서 씨도 너무 걱정하진 마세요.",
  ui_story_5038_50380701_19_dialog_content = "죽음의 문턱을 넘나들며 아스트라에 도착했던 신풍호잖아요.\n그러니 절대로 저희 모두를 쉽게 바다에서 죽게 만들진 않을 거예요.",
  ui_story_5038_50380701_20_dialog_content = "어허! 금기를!",
  ui_story_5038_50380701_21_dialog_content = "왜, 왜 그러세요?!",
  ui_story_5038_50380701_22_dialog_content = "...추태를 보였군, 미안하네.",
  ui_story_5038_50380701_23_dialog_content = "종 모의 고향에서는 새해가 다가올 무렵에는 불길한 언사를 삼가는 풍습이 있소.",
  ui_story_5038_50380701_24_dialog_content = "대수롭지 않은 풍습이기는 하나, 부디 젊은이가 이 점을 헤아려 주었으면 좋겠군.",
  ui_story_5038_50380701_25_dialog_content = "먼저 실례하지.",
  ui_story_5038_50380701_26_dialog_content = "(불길한 언사라는 건... 「죽음」 얘기구나.)",
  ui_story_5038_50380701_27_dialog_content = "종서 형님이 저렇게 격한 반응을 하시는 건 엄청 드문 일인데 말이지.",
  ui_story_5038_50380701_28_dialog_content = "역시 반년 전의 일이 되풀이되진 않을까 걱정되시는 모양이야.",
  ui_story_5038_50380701_29_dialog_content = "PlayerName, 뭐 하나 부탁해도 될까?",
  ui_story_5038_50380701_30_dialog_content = "신풍호에 있는 이 작은 나무 구명정을 조용히 배의 가장자리 쪽으로 옮겨야 하거든.",
  ui_story_5038_50380701_31_dialog_content = "뭐? 잠깐만, 그거 그냥 구명정을 <color=#FFB400>훔치겠다</color>는 소리 아냐?!",
  ui_story_5038_50380701_32_dialog_content = "아이, 참. 무슨 말을 그렇게 안 예쁘게 하고 그래?",
  ui_story_5038_50380701_33_dialog_content = "저기 봐. 선장 누나랑 종서 형님은 지금 배에 물이 안 들어오게 만들 방법을 궁리하고 있어.",
  ui_story_5038_50380701_34_dialog_content = "그것만으로도 엄청 머리 아플 거야.\n그래서 난 저 두 사람을 더 번거롭게 만들고 싶진 않아.",
  ui_story_5038_50380701_35_dialog_content = "그건 알겠는데, 혼자서 구명정 가지고 뭘 하려고?",
  ui_story_5038_50380701_36_dialog_content = "바다에 나가서 「원숭이 머리」를 낚아 올 거야.",
  ui_story_5038_50380701_37_dialog_content = "그, 그건 절대 안 돼! 너무 위험하잖아!",
  ui_story_5038_50380701_38_dialog_content = "내 말 잘 들어, PlayerName. 신풍호는 지금 사람으로 치면 「병에 걸린 상태」야.",
  ui_story_5038_50380701_39_dialog_content = "병을 고치려면 증상에 맞는 약을 써야 하는데, 어떤 약초는 쉽게 손에 넣을 수 있어.",
  ui_story_5038_50380701_40_dialog_content = "하지만 어떤 약초는 험난하고 극한적인 환경에서 자라서, 쉽게 채집할 수 없기도 해.",
  ui_story_5038_50380701_41_dialog_content = "「원숭이 머리」는 이미 부서졌고, 이 배엔 그걸 대신할 물건이 없어.",
  ui_story_5038_50380701_42_dialog_content = "그러니까 신풍호의 병을 고치려면, 바닷속으로 들어가야 한단 얘기지.",
  ui_story_5038_50380701_43_dialog_content = "바다로 들어가? 배에도 없는 게 물에 들어간다고 있을 리가 없잖아!",
  ui_story_5038_50380701_44_dialog_content = "네가 봤을진 모르겠는데, 근처 해수면을 잘 보면 이런저런 잔해들이 흩어져 있어.",
  ui_story_5038_50380701_45_dialog_content = "전부 언제인가 여기서 사고를 당한 배들이 남긴 흔적이야.",
  ui_story_5038_50380701_46_dialog_content = "그 안에서 다른 배의 도르래를 찾아낼 수 있다면,\n그걸로 신풍호의 「원숭이 머리」를 대체할 수 있어.",
  ui_story_5038_50380701_47_dialog_content = "돛을 펼칠 수 있게 되면 항해하기 더 쉬워질 거야!\n「토끼 귀」는 그다음에 다시 생각하면 돼!",
  ui_story_5038_50380701_48_dialog_content = "맞는 말이긴 한데... 진짜 일이 그렇게 잘 풀릴까?",
  ui_story_5038_50380701_49_dialog_content = "바다에 빠진 바늘 찾기 수준일 것 같은데.",
  ui_story_5038_50380701_50_dialog_content = "PlayerName, 내가 된다면 되는 거야. 난 「수요령」이라구.",
  ui_story_5038_50380701_51_dialog_content = "<color=#FFB400>바닷속 「친구」</color>들이 나한테 어디로 가야 할지, 뭘 해야 할지 알려줄 거야.",
  ui_story_5038_50380701_52_dialog_content = "그런 게 가능하다고?",
  ui_story_5038_50380701_53_dialog_content = "당연하지! 난 배를 탈 때마다 걔들이랑 자주 얘기도 하고 그런다니까.",
  ui_story_5038_50380701_54_dialog_content = "내가 도와달라고 하면, 어떻게든 꼭 날 도와준다구.",
  ui_story_5038_50380701_55_dialog_content = "그럼 다른 배의 「원숭이 머리」 찾는 것도 도와달라고 할 거야?",
  ui_story_5038_50380701_56_dialog_content = "근데... 걔들이 우리가 찾는 「원숭이 머리」가 어떻게 생겼는지 알아?",
  ui_story_5038_50380701_57_dialog_content = "내가 설명해 주면 되니까 전혀 문제없어.",
  ui_story_5038_50380701_58_dialog_content = "아무튼 도와준다고 수고 많았어, PlayerName! 이제부턴 나 혼자서 할게!",
  ui_story_5038_50380701_59_dialog_content = "솔직히 그래도 걱정이 좀 되긴 하지만, 대신 계속 네 위치를 감응하고 있을게.",
  ui_story_5038_50380701_60_dialog_content = "혹시라도 뭔가 이상하면 너도 꼭 감응으로 곧장 나한테 말해줘!",
  ui_story_5038_50380701_61_dialog_content = "알겠어, 알았다니까. 그럼 좋은 소식을 가져다줄 테니까 기대하고 있어!",
  ui_story_5038_50380701_62_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5038_50380701_63_dialog_content = "으아아아악!",
  ui_story_5038_50380701_64_dialog_content = "리청! 왜 그래? 무슨 일이야?!",
  ui_story_5038_50380701_65_option_content = "(강제 감응!)",
  ui_story_5038_50380701_66_dialog_content = "(물이야! 사방이 물투성이야! 여기도 물! 저기도 물... 다 물이라구!)",
  ui_story_5038_50380701_67_dialog_content = "으아앙... PlayerName! 주변이 다 물이야!",
  ui_story_5038_50380701_68_dialog_content = "그게 무슨 소리야... 바다 한복판에 있으니까 당연히 주변이 다 물이지!",
  ui_story_5038_50380701_69_dialog_content = "잠깐만, 너 설마 물 무서워해?!",
  ui_story_5038_50380701_70_dialog_content = "다, 당연하잖아아아! 리화묘가 물을 무서워하는 건 당연한 거 아냐?!",
  ui_story_5038_50380701_71_dialog_content = "(아, 리청이 엄청난 기세로 떨고 있어. 반년 전에 있었던 사고가 트라우마가 된 모양이네...)",
  ui_story_5038_50380701_72_dialog_content = "그, 그럼 빨리 올라와! 내가 구명정이랑 같이 끌어 올려 줄 테니까, 얌전히 있어...",
  ui_story_5038_50380701_73_dialog_content = "에잇... 끄응...",
  ui_story_5038_50380701_74_dialog_content = "훌쩍...",
  ui_story_5038_50380701_75_dialog_content = "너무 무모한 거 아냐? 물도 무서워하면서 다짜고짜 왜 그랬어?",
  ui_story_5038_50380701_76_dialog_content = "나 혼자서도 할 수 있을 줄 알았단 말이야...",
  ui_story_5038_50380701_77_dialog_content = "크흠, 어차피 이렇게 된 이상... PlayerName 너한테 부탁 하나만 더 할게.",
  ui_story_5038_50380701_78_dialog_content = "말 안 해도 다 알아. 너랑 같이 구명정을 타고 내려가자는 거 맞지? 그거면 되겠어?",
  ui_story_5038_50380701_79_dialog_content = "다른 사람들은 아직 배를 수리하느라 정신없으니까, 그 틈에 얼른 갔다 오자.",
  ui_story_5038_50380701_80_dialog_content = "응!",
  ui_story_5038_50380701_81_dialog_content = "(그럼 출발하기 전에 다시 한번 배에 있는 안전장치들을 확인해 보자...)",
  ui_story_5038_50380701_82_dialog_content = "크오오!",
  ui_story_5038_50380701_83_dialog_content = "진짜 해도 해도 너무하네...",
  ui_story_5038_50380701_84_dialog_content = "줄 내린 지 얼마나 됐다고 이걸 기어 올라오냐고!",
  ui_story_5038_50380702_1_dialog_content = "얘들아, 잘 들어 봐. 내가 원숭이 머리랑 비슷하게 생긴 걸 찾고 있어.",
  ui_story_5038_50380702_2_dialog_content = "크기는 이 정도고, 동그랗고 딱딱해.",
  ui_story_5038_50380702_3_dialog_content = "끈으로 묶여 있을 수도 있고, 아닐 수도 있어...",
  ui_story_5038_50380702_X3_dialog_content = "친구라고 했던게... 이 물고기들이었어?",
  ui_story_5038_50380702_4_dialog_content = "으으... 콜록...",
  ui_story_5038_50380702_5_dialog_content = "왜 그래? 아직도 속이 울렁거려?",
  ui_story_5038_50380702_6_dialog_content = "복자께서 가라사대 「의자, 불능자의」라...\n의원이 자기 병은 못 고친다더니, 딱 내 지금 꼴이잖아.",
  ui_story_5038_50380702_7_dialog_content = "내가 뭐라도 좀 도와줄까?",
  ui_story_5038_50380702_8_dialog_content = "그럼 내 턱을 좀 긁어주면 괜찮아질 것 같기도 한데...",
  ui_story_5038_50380702_9_dialog_content = "아, 아니야! 크흠, 턱 긁어주는 건 작은꼬리나 좋아하는 거야!",
  ui_story_5038_50380702_10_dialog_content = "둔갑도 못 하는 리화묘도 아니고, 내가 그런 걸 좋아할 리가 없잖아!",
  ui_story_5038_50380702_11_dialog_content = "(참 귀엽다니까...)",
  ui_story_5038_50380702_12_dialog_content = "근데 PlayerName 너네 고향엔 「수요령」 같은 건 없지?",
  ui_story_5038_50380702_13_dialog_content = "음, 아인족 혈통을 가진 오로리안 친구들은 비슷한 느낌이긴 해.",
  ui_story_5038_50380702_14_dialog_content = "대부분 아인과 오로리안 사이의 후손들인데, 아스트라 대륙에서는 비교적 소수인 종족이야.",
  ui_story_5038_50380702_15_dialog_content = "그렇구나. 근데 네 말대로면 그래도 「수요령」이랑은 좀 다른 것 같아.",
  ui_story_5038_50380702_16_dialog_content = "내가 저번에 말했잖아? 작은꼬리는 사실 우리 형이라구.",
  ui_story_5038_50380702_17_dialog_content = "혀, 형?!",
  ui_story_5038_50380702_18_dialog_content = "그럼 천간 씨가 자꾸 널 「야옹이」라고 불렀던 것도,\n리청 네가 진짜로 고양이라서 그랬던 거였어?",
  ui_story_5038_50380702_19_dialog_content = "이, 이천간 그 사람은 진짜 예의라곤 조금도 없다니까.",
  ui_story_5038_50380702_20_dialog_content = "근데 틀린 말은 아니야.\n용주의 「수요령」은 수련을 통해 광령이 된 동물들을 말하는 거거든.",
  ui_story_5038_50380702_21_dialog_content = "화합을 중요하게 생각하는 용주의 유명 가문들은\n「수요령」을 손님으로 받아줄 때도 있어.",
  ui_story_5038_50380702_22_dialog_content = "그런 손님들을 보고 「식객」이라고 해.",
  ui_story_5038_50380702_23_dialog_content = "내가 린 가문 가주님과 알게 된 것도 그래서야.",
  ui_story_5038_50380702_24_dialog_content = "린 가문의 가주님은 정을 중시하는 분인 모양이네.",
  ui_story_5038_50380702_25_dialog_content = "솔직히 난 어른들이 대화하면서 얘기하는 거래니, 무역이니 그런 건 하나도 몰라.",
  ui_story_5038_50380702_26_dialog_content = "린 가문이 날 초대한 건 <color=#FFB400>물고기 돌보는 일</color>을 부탁하기 위해서였어.",
  ui_story_5038_50380702_27_dialog_content = "사람들은 고양이가 물고기를 먹는다고 생각하지만,\n바다의 물고기들은 사실 모두 내 친구야.",
  ui_story_5038_50380702_28_dialog_content = "그러니까 리청 넌 교룡어랑도 대화할 수 있다는 거야?",
  ui_story_5038_50380702_29_dialog_content = "어느 정도는. 하지만 그날 밤 돌발 상황이 벌어졌을 땐, 아무런 도움도 못 됐어...",
  ui_story_5038_50380702_30_dialog_content = "아, 바닷속 친구들이 바로 여기래.",
  ui_story_5038_50380702_31_dialog_content = "PlayerName, 「원숭이 머리」가 우리 바로 아래에 있어.",
  ui_story_5038_50380702_32_dialog_content = "진짜?",
  ui_story_5038_50380702_33_dialog_content = "응, 아마 해초랑 엉켜 있는 모양이야.",
  ui_story_5038_50380702_34_dialog_content = "잠깐만, 그물을 던져서 위로 살짝 당기면...",
  ui_story_5038_50380702_35_dialog_content = "읏챠!",
  ui_story_5038_50380702_36_dialog_content = "PlayerName, 짜잔!",
  ui_story_5038_50380702_37_dialog_content = "대, 대단하네!",
  ui_story_5038_50380702_38_dialog_content = "무슨 마술 같아!",
  ui_story_5038_50380702_39_dialog_content = "말했잖아. 바닷속 친구들이 도와줄 거라고~",
  ui_story_5038_50380702_40_dialog_content = "새로운 「원숭이 머리」를 찾았으니까, 이제 배 수리하는 데도 도움이 되겠지!",
  ui_story_5038_50380702_41_dialog_content = "응, 그럼 얼른 돌아가자!",
  ui_story_5038_50380702_42_dialog_content = "배에 있는 사람들도 좋아할 거야!",
  ui_story_5038_50380702_43_dialog_content = "그래!",
  ui_story_5038_50380702_44_dialog_content = "(그 녀석 상태는 어떨지 모르겠네...)",
  ui_story_5038_50380702_45_dialog_content = "<color=#e8d9bb>신풍호, 갑판</color>",
  ui_story_5038_50380702_46_dialog_content = "아... 리청과 PlayerName 공자가 돌아왔어!",
  ui_story_5038_50380702_47_dialog_content = "내 두 사람에게 아무 일 없을 것이라 하지 않았소.",
  ui_story_5038_50380702_48_dialog_content = "크흠, 그리 말씀하시는 종 공도 조금 전까지 수저를 들지도 않으셨잖아요.",
  ui_story_5038_50380702_49_dialog_content = "PlayerName, 리청! 다짜고짜 가버리면 어떡해!",
  ui_story_5038_50380702_50_dialog_content = "출발 전에 무슨 일이 생길지 생각해 보긴 했어?",
  ui_story_5038_50380702_51_dialog_content = "선장 누나, 이거 봐!",
  ui_story_5038_50380702_52_dialog_content = "......!",
  ui_story_5038_50380702_53_dialog_content = "「원숭이 머리」?!",
  ui_story_5038_50380702_54_dialog_content = "딱 봐도 물에 계속 잠겨 있던 것 같지만, 손질만 조금 해 주면 더 쓸 수 있겠어.",
  ui_story_5038_50380702_55_dialog_content = "이걸 어디서 찾았어?",
  ui_story_5038_50380702_56_dialog_content = "바닷속에서!",
  ui_story_5038_50380702_57_dialog_content = "그러니까 당신들이 멋대로 몰래 구명정을 내렸다는 거야?",
  ui_story_5038_50380702_58_dialog_content = "그게 얼마나 위험한 행동이었는지 알아? 지금처럼 다들 바쁜 상황에선\n두 사람한테 문제가 생겨도 아무도 몰랐을 거라고.",
  ui_story_5038_50380702_59_dialog_content = "그래도 이렇게 멀쩡하게 돌아왔잖아! 아무 일도 없었고!",
  ui_story_5038_50380702_60_dialog_content = "하하, 막무가내로 저지르긴 했지만 결과는 좋았잖아요.",
  ui_story_5038_50380702_61_dialog_content = "월백 씨도 이번 항해는 일종의 모험이 될 거라고 했었고 말이죠.",
  ui_story_5038_50380702_62_dialog_content = "그리고 리청 덕분에 새 「원숭이 머리」를 찾았으니까,\n그 점은 제대로 칭찬해 줘야 한다고 생각해요!",
  ui_story_5038_50380702_63_dialog_content = "당신들 정말...",
  ui_story_5038_50380702_64_dialog_content = "좋아. 새 「원숭이 머리」를 찾아서 배 수리에 큰 도움이 된 건 사실이니까. 둘 다 고마워.",
  ui_story_5038_50380702_65_dialog_content = "하지만 앞으로 다시는, 멋대로 배에서 내리는 위험한 짓 같은 건 하지 마.",
  ui_story_5038_50380702_66_dialog_content = "얼른 가 봐. 이제 식사해야지.",
  ui_story_5038_50380702_67_dialog_content = "그래. 어서 가자~",
  ui_story_5038_50380702_68_dialog_content = "방금 다들 수리에 여념이 없을 동안, 구가 용주의 음식을 준비해 뒀거든.",
  ui_story_5038_50380702_69_dialog_content = "우와! 마침 배고팠어요!",
  ui_story_5038_50380702_70_dialog_content = "향이 좋네! 설마 오늘 홍소육 먹는 거야?",
  ui_story_5038_50380702_71_dialog_content = "코가 좋구나. 맞아, 오늘 주요리는 <color=#FFB400>홍소육</color>이야!",
  ui_story_5038_50380702_72_dialog_content = "품질이 좋은 고기를 네모반듯하게 썰어 실로 묶고,\n갖가지 향신료와 함께 냄비에 넣어 약한 불로 오래 익혔어...",
  ui_story_5038_50380702_73_dialog_content = "배에서 구할 수 있는 재료에 한계가 있긴 했지만,\n그래도 맛은 용주 본토의 홍소육보다 못하지는 않을 거야.",
  ui_story_5038_50380702_74_dialog_content = "여러분 먼저 드세요. 저는 아직 수리할 게 남아서요.",
  ui_story_5038_50380702_75_dialog_content = "새 「원숭이 머리」를 찾았으니, 돛대 쪽 수리는 금방 마무리될 거예요.",
  ui_story_5038_50380702_76_dialog_content = "그러고 나면 신풍호의 속도도 원래대로 돌아오겠죠.",
  ui_story_5038_50380702_77_dialog_content = "저도 도울게요!",
  ui_story_5038_50380702_78_dialog_content = "<color=#e8d9bb>꼬르륵...</color>",
  ui_story_5038_50380702_79_dialog_content = "후훗, 다른 사람들과 같이 식사부터 하도록 해.",
  ui_story_5038_50380702_80_dialog_content = "배불리 대접하지 않은 손님에게 도움을 받는 건 린 가문의 법도가 아니니까.",
  ui_story_5038_50380801_1_dialog_content = "(항해 속도는 원래대로 돌아왔지만, 선체 쪽 상황은 아직 안심할 수 없었다.)",
  ui_story_5038_50380801_2_dialog_content = "(마치 조금이라도 쉬면 신풍호가 침몰할 것처럼 모두 쉬지 않고 일하고 있었다.)",
  ui_story_5038_50380801_3_dialog_content = "(어쩌면 우리가 더 힘들게 일하는 건 불안함을 지우기 위해서였는지도 모른다.)",
  ui_story_5038_50380801_4_dialog_content = "풍향이 바뀌었어. 돛을 조금 더 좌측으로.",
  ui_story_5038_50380801_5_dialog_content = "네!",
  ui_story_5038_50380801_6_dialog_content = "화물창 쪽 상황은?",
  ui_story_5038_50380801_7_dialog_content = "아직도 물이 새어 들어오고 있어서 선원들이 계속 밖으로 퍼내는 중입니다.",
  ui_story_5038_50380801_8_dialog_content = "다행히 상태가 더 악화되고 있진 않아서 아직은 더 버틸 수 있습니다.",
  ui_story_5038_50380801_9_dialog_content = "알겠어. 그러면 모두가 돌아가면서 쉴 수 있게 교대 순번을 정해 줘.",
  ui_story_5038_50380801_10_dialog_content = "지금 상황이 얼마나 더 지속될진 알 수 없으니까, 반드시 체력을 비축해 놔야 해.",
  ui_story_5038_50380801_11_dialog_content = "네!",
  ui_story_5038_50380801_12_dialog_content = "항로에서 벗어난 게 아니면 좋겠는데... 뱃머리에 가서 확인해 봐야겠어.",
  ui_story_5038_50380801_13_dialog_content = "(월백 씨는 여기저기를 쉼 없이 돌아다니고 있었다.\n심지어 말을 할 때도 걸음을 멈추지 않았다.)",
  ui_story_5038_50380801_14_dialog_content = "(선장이니 우리 중 누구보다도 고민이 많고,\n그래서 스트레스도 가장 많이 받고 있을 것이다.)",
  ui_story_5038_50380801_15_dialog_content = "(마치 월백 씨의 발소리가 신풍호 곳곳에 난 구멍들을 메우고 있는 것만 같았다.)",
  ui_story_5038_50380801_16_dialog_content = "또 보여...",
  ui_story_5038_50380801_17_dialog_content = "구, 지금까지 몇 개였지?",
  ui_story_5038_50380801_18_dialog_content = "42개입니다, 전하.",
  ui_story_5038_50380801_19_dialog_content = "그렇게 많다니.",
  ui_story_5038_50380801_20_dialog_content = "가는 방향 쪽에서 계속 보이니까... 불안하네.",
  ui_story_5038_50380801_21_dialog_content = "(오늘 아침부터 배의 잔해로 보이는 나무 조각들이 보이기 시작했다.)",
  ui_story_5038_50380801_22_dialog_content = "(어제 찾은 원숭이 머리는 빙산의 일각에 불과하다는 듯이,\n이곳에서 조난당한 배의 잔해가 끝없이 떠다니고 있었다.)",
  ui_story_5038_50380801_23_dialog_content = "(단당 씨는 쉬는 시간에 난간에서 바다를 보며 그 잔해들을 일일이 세는 중이었다.)",
  ui_story_5038_50380801_24_dialog_content = "(바다에 버려진 저 잔해들에겐 아마 그것이 유일하게 받을 수 있는 관심이었을 것이다.)",
  ui_story_5038_50380801_25_dialog_content = "불안해할 게 뭐 있어? 오히려 좋은 일이잖아.",
  ui_story_5038_50380801_26_dialog_content = "여기 조난당한 배들이 있다는 건 우리가 지금 맞게 가고 있다는 뜻이야.",
  ui_story_5038_50380801_27_dialog_content = "오히려 바다가 텅 비어 있으면 그게 더 무섭지 않겠어?",
  ui_story_5038_50380801_28_dialog_content = "(리청은 물고기를 문 채 지나갔다.)",
  ui_story_5038_50380801_29_dialog_content = "(줄곧 사람들을 돕고 있었지만, 한편으로는 이 상황에도 아랑곳하지 않는 것처럼 보였다.)",
  ui_story_5038_50380801_30_dialog_content = "(어쩌면 심심풀이로 일을 하고 있는 것일지도 모른다.)",
  ui_story_5038_50380801_31_dialog_content = "아이고, 이거 원 힘들어서 황천이 보일 지경이네.",
  ui_story_5038_50380801_32_dialog_content = "물을 퍼내도 퍼내도 끝이 없으니 원.",
  ui_story_5038_50380801_33_dialog_content = "PlayerName 공, 당신도 올라온 겁니까?",
  ui_story_5038_50380801_34_dialog_content = "네, 선원들이 조금 쉬라고 해서요.",
  ui_story_5038_50380801_35_dialog_content = "(천간 씨는 처음부터 지금까지 이 배에서 가장 말을 잘하는 사람이다.)",
  ui_story_5038_50380801_36_dialog_content = "그래야지요. 피로로 몸을 해치는 건 좋지 않습니다.",
  ui_story_5038_50380801_37_dialog_content = "오늘 이렇게 물을 퍼낸다 한들, 내일이면 또 차 있을 테고 말이지요.",
  ui_story_5038_50380801_38_dialog_content = "항해라는 건 모름지기 바다보다도 너른 인내심이 필요합니다.",
  ui_story_5038_50380801_39_dialog_content = "천간 씨는 정말 어떤 상황에서든지 뭔가 그럴싸한 말을 잘하는 것 같아요.",
  ui_story_5038_50380801_40_dialog_content = "당연한 일 아니겠습니까? 아직 가야 할 길이 머니,\n어떻게 해서든 평정심을 유지하라고 자신을 다독여야지요.",
  ui_story_5038_50380801_41_dialog_content = "그래도 아직 이륜거에 탄 분까지 일을 시켜야 할 정도는 아니니,\n최악의 상황은 아니라 할 수 있겠습니다.",
  ui_story_5038_50380801_42_dialog_content = "이 종 모가 하는 일 없이 빈둥거린다고 언짢은 이가 있는 모양이구려.",
  ui_story_5038_50380801_43_dialog_content = "아이고오오! 종서 대인, 오셨습니까!",
  ui_story_5038_50380801_44_dialog_content = "어인 일로 갑판에 바람을 다 쐬러 나오셨는지요?",
  ui_story_5038_50380801_45_dialog_content = "그렇게 나리 모시듯 대할 것 없소.\n땅 위에서도 내 그런 권세는 없거늘, 바다 위라고 생기겠는가.",
  ui_story_5038_50380801_46_dialog_content = "어찌 그런 말씀을 하십니까. 호랑이가 발톱을 잃어도 그 위세가 남는데,\n하물며 평야대장군은 어떻겠습니까.",
  ui_story_5038_50380801_47_dialog_content = "그만하면 되었네. 참으로 달변이로군.",
  ui_story_5038_50380801_48_dialog_content = "실은 이 종 모에게 지금의 난국을 타개할 수 있을지도 모르는 방도가 하나 있소.",
  ui_story_5038_50380801_49_dialog_content = "허나 이를 실행하려면 그대들의 도움이 필요하오.",
  ui_story_5038_50380801_50_dialog_content = "정말요?! 어떤 방법이죠?",
  ui_story_5038_50380801_51_dialog_content = "제가 도와드릴게요!",
  ui_story_5038_50380801_52_dialog_content = "웅재대략의 종 대인께서 마련하신 계책이라면, 소생 전력을 다해 돕겠습니다!",
  ui_story_5038_50380801_53_dialog_content = "그리 어려운 일은 아니오.\n내 대신 바다에 떠 있는 저 나무판자들을 건져 주시오.",
  ui_story_5038_50380801_54_dialog_content = "저것들을 건져 올리기만 하면 되는 건가요?",
  ui_story_5038_50380801_55_dialog_content = "그물만 있으면 되니까 어렵진 않을 것 같네요.",
  ui_story_5038_50380801_56_dialog_content = "그러게 말입니다. 마침 눈앞의 바다에 널린 것이 나무판자 아닙니까.",
  ui_story_5038_50380801_57_dialog_content = "보이는 판자들을 전부 건져 올릴 필요는 없소.\n종 모가 몇 개를 정해 줄 터이니 그것들만 부탁하오.",
  ui_story_5038_50380801_58_dialog_content = "네? 무슨 차이라도 있는 건가요?",
  ui_story_5038_50380801_59_dialog_content = "그런 질문은 나중에 해도 늦지 않습니다.\n종 대인 말씀대로만 하면 틀리는 법이 없거든요.",
  ui_story_5038_50380801_60_dialog_content = "자, 그럼 가서 선원들에게 그물을 달라고 합시다.",
  ui_story_5038_50380801_61_dialog_content = "영차... 영차...",
  ui_story_5038_50380801_62_dialog_content = "어서 당기세요! 한 번 더요!",
  ui_story_5038_50380801_63_dialog_content = "으라차차!",
  ui_story_5038_50380801_64_dialog_content = "<color=#e8d9bb>후두두둑──</color>",
  ui_story_5038_50380801_65_dialog_content = "휴우... 해냈다!",
  ui_story_5038_50380801_66_dialog_content = "해내? 뭘?",
  ui_story_5038_50380801_67_dialog_content = "그물에 물고기는 하나도 없고, 있는 거라곤 부서진 나무판자 하나뿐인데, 뭘 해냈다는 거야?",
  ui_story_5038_50380801_68_dialog_content = "리청? 아니, 이건 물고기를 잡으려던 게 아니라...",
  ui_story_5038_50380801_69_dialog_content = "내가 그리 부탁한 것이다.",
  ui_story_5038_50380801_70_dialog_content = "네? 그래도 이상해요. 나무판자를 낚아서 뭘 하시려고요?",
  ui_story_5038_50380801_71_dialog_content = "그냥 나무판자가 아니다. 두 사람이 끌어올려 준 저 판자를 잘 살펴보아라.",
  ui_story_5038_50380801_72_dialog_content = "선체에서는 그것을 「토끼 귀」라고 칭하더군.",
  ui_story_5038_50380801_73_dialog_content = "호오! 듣고 보니 생김새가 실로 토끼의 귀를 닮았네요.",
  ui_story_5038_50380801_74_dialog_content = "역시! 종 대인과 소생의 마음이 통했던 것이로군요!",
  ui_story_5038_50380801_75_dialog_content = "「토끼 귀」는 제 점괘에 나왔던 세 가지 물건 중 마지막 하나 아닙니까!",
  ui_story_5038_50380801_76_dialog_content = "무엇에 쓰는 물건인가요?",
  ui_story_5038_50380801_77_dialog_content = "이것은 배의 양옆에 달린 피수판이라는 것으로, 보통 배마다 한 쌍이 달려 있소.",
  ui_story_5038_50380801_78_dialog_content = "배에 쓰인 다른 목재에 비해 만듦새가 훨씬 정교하고, 방수 능력 또한 뛰어나오.",
  ui_story_5038_50380801_79_dialog_content = "하여 두 사람에게 건져 달라고 했던 것이오.",
  ui_story_5038_50380801_80_dialog_content = "대인께서는... 이 판자들의 방수 능력을 눈여겨보신 겁니까?",
  ui_story_5038_50380801_81_dialog_content = "그렇소.",
  ui_story_5038_50380801_82_dialog_content = "「방수」라는 것이 무엇인가, 물이 없어야 할 곳에 물이 차지 않도록 막는 것 아니겠나.",
  ui_story_5038_50380801_83_dialog_content = "물이 없어야 할 곳...",
  ui_story_5038_50380801_84_dialog_content = "아! 알겠어요! 화물창 말씀하시는 거죠?",
  ui_story_5038_50380801_85_dialog_content = "이 판자들로 누수 문제를 해결할 수 있겠네요!",
  ui_story_5038_50380801_86_dialog_content = "역시 젊은이는 영민하군.",
  ui_story_5038_50380801_87_dialog_content = "「토끼 귀」로 누수가 일어나는 부분을 덮고, 못으로 단단히 고정하는 것이오.",
  ui_story_5038_50380801_88_dialog_content = "일시의 미봉책에 불과하겠으나, 선원들의 근심을 다소나마 덜어 줄 수는 있겠지.",
  ui_story_5038_50380801_89_dialog_content = "아주 좋군요! 「토끼 귀」로 결손된 부위를 대체해 위기를 해결한다니,\n이것이 바로 치대신계 아니겠습니까.",
  ui_story_5038_50380801_90_dialog_content = "마지막 괘가 이런 의미였을 줄이야!",
  ui_story_5038_50380801_91_dialog_content = "좋은 방법 같네요!",
  ui_story_5038_50380801_92_dialog_content = "누수 문제만 해결된다면, 이제 사람들이 다른 일도 할 수 있게 될 테니까요.",
  ui_story_5038_50380801_93_dialog_content = "그럼 가서 몇 개 더 건져 오자구요!",
  ui_story_5038_50380801_94_dialog_content = "제가 잘 보고 있었습니다, PlayerName 공.",
  ui_story_5038_50380801_95_dialog_content = "저쪽을 보세요. 저기 「토끼 귀」가 하나 더 있습니다.",
  ui_story_5038_50380801_96_dialog_content = "자, 어서 그물을 내립시다!",
  ui_story_5038_50380801_97_dialog_content = "물이 또 차는 건가요?",
  ui_story_5038_50380801_98_dialog_content = "그래, 정말 숨 돌릴 틈도 없다니까.",
  ui_story_5038_50380801_99_dialog_content = "멍하니 있지 말고 물 퍼내는 거 좀 도와줘.",
  ui_story_5038_50380801_100_dialog_content = "아, 알겠어요...",
  ui_story_5038_50380801_101_dialog_content = "저기, 누가 나 좀 도와줄래?",
  ui_story_5038_50380801_102_dialog_content = "응? 리청 목소리잖아.",
  ui_story_5038_50380801_103_dialog_content = "빨리 좀 받아 봐! 못 버티겠으니까!",
  ui_story_5038_50380801_104_dialog_content = "갈게, 갈게! 근데 뭘 받으라는...",
  ui_story_5038_50380801_105_dialog_content = "<color=#e8d9bb>후두두둑──</color>",
  ui_story_5038_50380801_106_dialog_content = "응?!",
  ui_story_5038_50380801_107_dialog_content = "어휴, 무거워 죽는 줄 알았잖아.",
  ui_story_5038_50380801_108_dialog_content = "그래도 일단 여기 가져다줬으니까 임무는 끝난 거네.",
  ui_story_5038_50380801_109_dialog_content = "왜 나무판자를 여기까지 가져온 거야?",
  ui_story_5038_50380801_110_dialog_content = "종서 형님이 시킨 거야.",
  ui_story_5038_50380801_111_dialog_content = "형님 말씀으론 이 나무판자로 물이 새어 들어오는 곳을 막을 수 있대.",
  ui_story_5038_50380801_112_dialog_content = "나무판자? 바다에서 건져 올린 거냐?",
  ui_story_5038_50380801_113_dialog_content = "물에서 다 불어 터졌을 텐데 그런 걸 어떻게 쓰라고.",
  ui_story_5038_50380801_114_dialog_content = "불어 터지진 않았는데, 엄청 무거워.",
  ui_story_5038_50380801_115_dialog_content = "들어 볼래?",
  ui_story_5038_50380801_116_dialog_content = "네가 힘이 약한 거겠지. 나무판자 하나 드는 것도 힘들어서야 원.",
  ui_story_5038_50380801_117_dialog_content = "어디 줘 봐...",
  ui_story_5038_50380801_118_dialog_content = "뭐야?! 이거 「토끼 귀」잖아?",
  ui_story_5038_50380801_119_dialog_content = "어때? 다시 보니 선녀 같지?",
  ui_story_5038_50380801_120_dialog_content = "「토끼 귀」... 그래, 「토끼 귀」라면 효과가 있을지도 몰라.",
  ui_story_5038_50380801_121_dialog_content = "망치 어디 있어? 빨리 가서 망치 갖고 와!",
  ui_story_5038_50380801_122_dialog_content = "하나, 둘, 셋!",
  ui_story_5038_50380801_123_dialog_content = "<color=#e8d9bb>후두두둑──</color>",
  ui_story_5038_50380801_124_dialog_content = "오오! 또 하나 건져 올렸구나!",
  ui_story_5038_50380801_125_dialog_content = "하하, 별거 아닙니다.",
  ui_story_5038_50380801_126_dialog_content = "벼, 별거 아니라고요? 전 잠깐 숨 좀 돌릴게요...",
  ui_story_5038_50380801_127_dialog_content = "다들 뭐 하고 있어?",
  ui_story_5038_50380801_128_dialog_content = "선장님! 보시다시피 바다에서 나무판자를 끌어 올리고 있었답니다.",
  ui_story_5038_50380801_129_dialog_content = "종 대인께서 침몰선의 「토끼 귀」로 물이 새는 곳을\n임시로 보수할 수 있다고 하셔서 말이지요.",
  ui_story_5038_50380801_130_dialog_content = "「토끼 귀」...",
  ui_story_5038_50380801_131_dialog_content = "성공이야! 진짜 「토끼 귀」로 누수를 막았어!",
  ui_story_5038_50380801_132_dialog_content = "다녀왔구나, 리청! 성공했어?",
  ui_story_5038_50380801_133_dialog_content = "응! 「토끼 귀」를 화물창에 갖다줘서, 누수가 나는 곳을 막았어.",
  ui_story_5038_50380801_134_dialog_content = "근데 선원 말로는 물이 새는 데가 아직 많아서 「토끼 귀」가 더 많이 필요하대.",
  ui_story_5038_50380801_135_dialog_content = "그러니까 쉬지 말고 빨리 더 건져 봐!",
  ui_story_5038_50380801_136_dialog_content = "그래, 알겠어. 그럼 지금 바로...",
  ui_story_5038_50380801_137_dialog_content = "다들 그만하면 됐어. 가서 좀 쉬어.",
  ui_story_5038_50380801_138_dialog_content = "효과가 있다는 걸 알았으니까, 선원들에게 「토끼 귀」를 건져달라고 할게.",
  ui_story_5038_50380801_139_dialog_content = "신풍호의 손님에게 계속 고된 일을 시키는 것도 예의가 아니니까.",
  ui_story_5038_50380801_140_dialog_content = "자! 당겨!",
  ui_story_5038_50380801_141_dialog_content = "영차! 영차!",
  ui_story_5038_50380801_142_dialog_content = "<color=#e8d9bb>후두두둑──</color>",
  ui_story_5038_50380801_143_dialog_content = "여기도 하나 있어요!",
  ui_story_5038_50380801_144_dialog_content = "<color=#e8d9bb>후두두둑──</color>",
  ui_story_5038_50380801_145_dialog_content = "이 조각들을 얼른 밑에 갖다줘!",
  ui_story_5038_50380801_146_dialog_content = "못이 부족해! 좀 더 가져와!",
  ui_story_5038_50380801_147_dialog_content = "서두르지 말고 한 명씩 움직여! 한 명씩!",
  ui_story_5038_50380801_148_dialog_content = "모두가 도와주기 시작하니까 효율이 엄청 좋아졌네요.",
  ui_story_5038_50380801_149_dialog_content = "「토끼 귀」를 벌써 몇 개나 건져 올렸는지 다 세지도 못하겠어요.",
  ui_story_5038_50380801_150_dialog_content = "이 기세라면 오늘 안에 바닥 보수를 끝마칠 수 있을 것 같군요!",
  ui_story_5038_50380801_151_dialog_content = "어라? 이 「토끼 귀」...",
  ui_story_5038_50380801_152_dialog_content = "일항사님, 와서 이것 좀 보세요.",
  ui_story_5038_50380801_153_dialog_content = "왜 그래? 무슨 문제 있어?",
  ui_story_5038_50380801_154_dialog_content = "그게 아니라, 이거 뭔가 익숙하지 않아요?",
  ui_story_5038_50380801_155_dialog_content = "어! 진짜 어디서 많이 본 것 같이 생겼네!",
  ui_story_5038_50380801_156_dialog_content = "이거... 육 씨네 어선에 있던 거잖아!",
  ui_story_5038_50380801_157_dialog_content = "음... 올봄에 먼 바다에 고기를 잡으러 간다고 나갔다가\n소식이 끊겼던 걸로 기억해요.",
  ui_story_5038_50380801_158_dialog_content = "그 배를 여기서 만나게 될 줄은...",
  ui_story_5038_50380801_159_dialog_content = "어라? 선원들이... 조난당한 배가 누구 배인지 알아본 거예요?",
  ui_story_5038_50380801_160_dialog_content = "그렇소.",
  ui_story_5038_50380801_161_dialog_content = "나무판자만으로도 배를 구분할 수 있다니...",
  ui_story_5038_50380801_162_dialog_content = "「토끼 귀」는 아주 특별한 부품이기 때문이오.",
  ui_story_5038_50380801_163_dialog_content = "배마다 단 두 개만 있는 데다가, 그 위치도 무척 눈에 띄는 편이오.",
  ui_story_5038_50380801_164_dialog_content = "그래서 선주들은 자신이 선호하는 무늬를 새겨 넣어 선박의 개성을 드러내곤 하지.",
  ui_story_5038_50380801_165_dialog_content = "어떻게 알아본 건가 했더니, 무늬를 보고 안 거였군요!",
  ui_story_5038_50380801_166_dialog_content = "자주 바다로 나가는 용주 사람들에게는 평범한 습관일 뿐이오.",
  ui_story_5038_50380801_167_dialog_content = "목 선장도 한참 전부터 저 「토끼 귀」들을 유심히 보고 있더군.",
  ui_story_5038_50380801_168_dialog_content = "아마 선원들보다 훨씬 더 많은 배들의 정체를 파악했을 것이오.",
  ui_story_5038_50380801_169_dialog_content = "네...",
  ui_story_5038_50380801_170_dialog_content = "몇 척은 여름에 출항했다 태풍에 휘말려 돌아오지 못했던 여객선들이에요.",
  ui_story_5038_50380801_171_dialog_content = "「토끼 귀」를 무척 화려하게 만들어 놓았던 배들이라 첫눈에 알 수 있겠더군요.",
  ui_story_5038_50380801_172_dialog_content = "어선은 몇 척 없었어요. 어민들은 먼바다가 얼마나 위험한지 잘 알고 있기 때문이겠죠.",
  ui_story_5038_50380801_173_dialog_content = "하지만 올해는 연안과 근해의 사정이 좋지 않다 보니,\n알면서도 위험한 길을 선택할 수밖에 없었던 모양이에요.",
  ui_story_5038_50380801_174_dialog_content = "수가 가장 많았던 건 상선이었어요.",
  ui_story_5038_50380801_175_dialog_content = "저들은 멀리 떨어져 있는 다른 대륙과 거래해 큰돈을 벌길 바라며,\n신풍호의 항로를 따라 바다에 나섰죠.",
  ui_story_5038_50380801_176_dialog_content = "하지만 예로부터 지금까지, 두 대륙을 무사히 오고 간 배는 신풍호 하나뿐이었어요.",
  ui_story_5038_50380801_177_dialog_content = "그런...",
  ui_story_5038_50380801_178_dialog_content = "「토끼 귀」를 건져 올린다는 게 얼마나 마음이 무거워지는 일인지...\n이제 알 것 같아요.",
  ui_story_5038_50380801_179_dialog_content = "말했듯이 「토끼 귀」는 배에 단 두 개만 있소.",
  ui_story_5038_50380801_180_dialog_content = "그러니 바다에서 「토끼 귀」 한 쌍을 건져 올렸다는 것은,\n바꿔 말하면 배 한 척이 침몰했다는 것을 의미하오.",
  ui_story_5038_50380801_181_dialog_content = "식별이 가능한 배는 적어도 누군가의 기억에는 남게 되겠지.",
  ui_story_5038_50380801_182_dialog_content = "허나 아무도 알아봐 주지 않는 배들은 그저 묵묵히 쌓여가는 숫자로만 남을 뿐이오.",
  ui_story_5038_50380801_183_dialog_content = "그렇네요. 지금까지 저렇게 많은 「토끼 귀」를 건져 올렸는데...",
  ui_story_5038_50380801_184_dialog_content = "그게 바로 항해의 본질이야.",
  ui_story_5038_50380801_185_dialog_content = "바다에서 의지할 수 있는 건, 앞서 지나간 이들의 흔적뿐이지.",
  ui_story_5038_50380801_186_dialog_content = "이제 신풍호의 바닥 수리도 거의 다 마무리됐어.",
  ui_story_5038_50380801_187_dialog_content = "이것은 상선이고, 옆의 것은 어선이로구나. 그리고 이것 역시 상선이야.",
  ui_story_5038_50380801_188_dialog_content = "이것도 상선, 저것도 상선이고...",
  ui_story_5038_50380801_189_dialog_content = "단당 씨, 뭘 적고 있어요?",
  ui_story_5038_50380801_190_dialog_content = "아, 나 말이야? 이 「토끼 귀」들로 선박의 종류를 식별하고 있었어.",
  ui_story_5038_50380801_191_dialog_content = "용주에 돌아가면 적어도 관계자들에게 알려주는 게 좋지 않겠냐고 선장이 그러더구나.",
  ui_story_5038_50380801_192_dialog_content = "그랬군요...",
  ui_story_5038_50380801_193_dialog_content = "화물창으로 옮긴 것들은 이미 정리를 마쳤는데, 새로 건져 올린 「토끼 귀」가 있니?",
  ui_story_5038_50380801_194_dialog_content = "더는 없어요. 저흰 나무판자들이 가득 떠 있던 해역에서 이제 막 벗어났어요.",
  ui_story_5038_50380801_195_dialog_content = "그리고 판자는 이 정도로 충분하대요.",
  ui_story_5038_50380801_196_dialog_content = "배의 바닥도 거의 다 고쳤고, 다들 한창 막바지 작업 중이고요.",
  ui_story_5038_50380801_197_dialog_content = "그렇구나. 잘됐네. 나도 이제 마무리를 지어도 되겠어.",
  ui_story_5038_50380801_198_dialog_content = "하지만 단서를 찾아내지 못한 것은 못내 아쉽구나.",
  ui_story_5038_50380801_199_dialog_content = "단서요?",
  ui_story_5038_50380801_200_dialog_content = "그래. 실은 「나침반」의 행방에 관련된 단서를 찾아볼까 했거든.",
  ui_story_5038_50380801_201_dialog_content = "침몰선 대부분은 그해 신풍호와 함께 떠났던 상선이었어.",
  ui_story_5038_50380801_202_dialog_content = "만약 저 배들이 모두 난파당한 거라면...\n저 잔해들 중에 옛 신풍호의 「토끼 귀」도 있을 줄 알았어.",
  ui_story_5038_50380801_203_dialog_content = "지금 보니 내가 너무 쉽게 생각했던 것 같아.",
  ui_story_5038_50380801_204_dialog_content = "아니에요, 일리 있는 말이에요.\n옛 신풍호의 단서가 저 안에 있을지도 모르는 거잖아요.",
  ui_story_5038_50380801_205_dialog_content = "「나침반」이 그렇게 중요한 물건인 이상, 좀 더 찾아보는 게 좋지 않을까요?",
  ui_story_5038_50380801_206_dialog_content = "아니면 선장과 이야기해 보는 건 어떨까?",
  ui_story_5038_50380801_207_dialog_content = "그런데... 지금 생각해 보니까 종서 씨는 저 「토끼 귀」들의\n출처에 대해 별로 신경 안 쓰시는 것 같았어요.",
  ui_story_5038_50380801_208_dialog_content = "아마 저 안에 옛 신풍호는 없다는 사실을 알고 계셨던 건 아닐까요?",
  ui_story_5038_50380801_209_dialog_content = "그 안에 없다고? 그걸 알 방법이 있어?",
  ui_story_5038_50380801_210_dialog_content = "예를 들면 옛 신풍호의 「토끼 귀」가 특이하게 생겨서,\n멀리서 봐도 한 번에 알아볼 수 있다든지 말이에요.",
  ui_story_5038_50380801_211_dialog_content = "그건 아닌 듯싶어.",
  ui_story_5038_50380801_212_dialog_content = "망망대해에서 족히 백 리는 떨어져 있는 물체를 그리 선명히 볼 수 있는 이는 없을 테니까.",
  ui_story_5038_50380801_213_dialog_content = "아니면 옛 신풍호엔 처음부터 「토끼 귀」가 없었을 수도 있지 않을까요?",
  ui_story_5038_50380801_214_dialog_content = "음... 그것도 아니겠네요. 만에 하나 옛 신풍호는 진짜로 「토끼 귀」가 없었다면,\n적어도 다른 부위의 잔해라도 찾아보려고 했을 거잖아요.",
  ui_story_5038_50380801_215_dialog_content = "근데 종서 씨는 잔해에는 전혀 관심도 없는 것 같았거든요...",
  ui_story_5038_50380801_216_dialog_content = "설마...",
  ui_story_5038_50380801_217_dialog_content = "저 안에서 옛 신풍호의 흔적을 찾을 수 없는 건 당연한 거야.",
  ui_story_5038_50380801_218_dialog_content = "왜냐면 아직 잔해가 되지 않았으니까.",
  ui_story_5038_50380801_219_dialog_content = "으앗?! 리청 너 어디서 갑자기 튀어나온 거야?!",
  ui_story_5038_50380801_220_dialog_content = "아직 잔해가 되지 않았다니...?",
  ui_story_5038_50380801_221_dialog_content = "조난을 당했다고 해서 꼭 침몰하는 건 아니야.",
  ui_story_5038_50380801_222_dialog_content = "생각해 봐. 옛 신풍호는 선박의 평안을 수호해 주는 보물 「나침반」이 있어.\n그런 배가 침몰할 리가 없잖아.",
  ui_story_5038_50380801_223_dialog_content = "「나침반」에 그런 힘이 있어?",
  ui_story_5038_50380801_224_dialog_content = "당연하지. 그러니까 저 많은 사람들이 골머리를 앓아 가면서 계속 찾고 있는 거야.",
  ui_story_5038_50380801_225_dialog_content = "자, 자, 지금 이런 얘기를 하고 있을 때가 아냐.",
  ui_story_5038_50380801_226_dialog_content = "이제 곧 식사 시간이야. 배의 사람들이 다 모여서 기다리고 있다구.",
  ui_story_5038_50380801_227_dialog_content = "얼른 가자.",
  ui_story_5038_50380801_228_dialog_content = "다들?! 다 같이 식사하는 거니?",
  ui_story_5038_50380801_229_dialog_content = "맞아. 수리 작업도 다 끝나서 간만에 다들 한숨 돌릴 수 있게 됐잖아.",
  ui_story_5038_50380801_230_dialog_content = "종서 형님도 참여하는 자리니까, 절대 빠지면 안 돼.",
  ui_story_5038_50380801_231_dialog_content = "얼른 가자~",
  ui_story_5038_50380801_232_dialog_content = "아이고, 드디어 오셨습니까!",
  ui_story_5038_50380801_233_dialog_content = "요리가 다 나오니까 냄새가 끝내주지 않습니까?",
  ui_story_5038_50380801_234_dialog_content = "자, 이쪽으로 오세요!",
  ui_story_5038_50380801_235_dialog_content = "우와! 시끌벅적하네!",
  ui_story_5038_50380801_236_dialog_content = "음, 향이 좋구나!",
  ui_story_5038_50380801_237_dialog_content = "당연하죠. 주방장이 혼신의 힘을 다했으니 말입니다.",
  ui_story_5038_50380801_238_dialog_content = "이 정도는 해야 「축하연」 아니겠습니까.",
  ui_story_5038_50380801_239_dialog_content = "축하연이요?",
  ui_story_5038_50380801_240_dialog_content = "그럼요! 이제 신풍호가 온전히 수리되어 운항이 정상으로 돌아온 걸 축하해야지요.",
  ui_story_5038_50380801_241_dialog_content = "아니지, 축사는 제가 아니라 선장님이 하셔야 하지 않겠습니까!\n선장님, 한 말씀해 주시지요!",
  ui_story_5038_50380801_242_dialog_content = "나? 난...",
  ui_story_5038_50380801_243_dialog_content = "미안, 난 그런 말은 잘 못해.",
  ui_story_5038_50380801_244_dialog_content = "아무튼... 다들 즐거운 식사가 되길 바랄게.",
  ui_story_5038_50380801_245_dialog_content = "오늘 이 배에 있는 건 뭐든 다 먹어도 돼.",
  ui_story_5038_50380801_246_dialog_content = "정말이십니까? 그럼 전 창고의 훈제 고기를 좀 먹고 싶습니다!",
  ui_story_5038_50380801_247_dialog_content = "매일 생선만 먹었더니 지겨워 죽겠습니다!",
  ui_story_5038_50380801_248_dialog_content = "에이, 생선이 어디가 어때서?",
  ui_story_5038_50380801_249_dialog_content = "먹기 싫으면 전부 나 줘!",
  ui_story_5038_50380801_250_dialog_content = "종 대인, 어찌 이렇게 멀리 떨어져 계십니까.",
  ui_story_5038_50380801_251_dialog_content = "제가 요리들을 좀 가져다드리겠습니다.",
  ui_story_5038_50380801_252_dialog_content = "되었소. 이쪽이 조용하니 좋군.",
  ui_story_5038_50380801_253_dialog_content = "연회의 떠들썩함을 좋아하지 않으시는 모양이군요.",
  ui_story_5038_50380801_254_dialog_content = "그렇지는 않소. 오히려 좋아하는 편이오.",
  ui_story_5038_50380801_255_dialog_content = "조정의 녹을 받던 무렵에는 지금 같은 연회에 많이 참석했었지.",
  ui_story_5038_50380801_256_dialog_content = "허나 자리에서 물러나고 나서야 알게 되었소.\n그런 떠들썩함은 멀리 있어야 잘 와닿더이다.",
  ui_story_5038_50380801_257_dialog_content = "멀찍이 앉아 연회를 즐기고 있는 저들을 보고 있노라면,\n오히려 이 종 모가 더 즐거운 마음이오.",
  ui_story_5038_50380801_258_dialog_content = "그렇습니까? 역시 대인의 뜻은 헤아리기가 쉽지 않군요...",
  ui_story_5038_50380801_259_dialog_content = "구! 여기 있었구나!",
  ui_story_5038_50380801_260_dialog_content = "저, 전하! 깜짝 놀랐습니다...",
  ui_story_5038_50380801_261_dialog_content = "선원들이 함께 춤을 추자고 하는데, 같이 가겠니?",
  ui_story_5038_50380801_262_dialog_content = "네 춤 실력은 천하제일이니까!",
  ui_story_5038_50380801_263_dialog_content = "과찬이십니다. 아직 남 앞에 설 정도는 아닌지라...",
  ui_story_5038_50380801_264_dialog_content = "그럼 일단 같이 식사부터 하자! 요리를 내오는 중이야!",
  ui_story_5038_50380801_265_dialog_content = "늦었다간 빈 접시만 보게 될 거야!",
  ui_story_5038_50380801_266_dialog_content = "하하, 단당 씨 지금 엄청 신나 보이네요.",
  ui_story_5038_50380801_267_dialog_content = "응! 난 지금 무척 즐겁거든!",
  ui_story_5038_50380801_268_dialog_content = "저 우뚝 솟은 돛대를 우리가 세웠고, 타고 있는 이 배를 우리 손으로 수리했어.",
  ui_story_5038_50380801_269_dialog_content = "당연히 기쁘지 않겠니?",
  ui_story_5038_50380801_270_dialog_content = "이번 항해로 우린 모두 이 배의 일원이 된 거야!",
  ui_story_5038_50380801_271_dialog_content = "맞아요. 저도 왠지 신풍호에 소속감 같은 게 생긴 것 같거든요.",
  ui_story_5038_50380801_272_dialog_content = "그래! 그건 이 배에 타고 있는 이들만이 느낄 수 있는 감정이야.",
  ui_story_5038_50380801_273_dialog_content = "물론, 또 다른 즐거움은 아마 배의 모두가 잘 알고 있을 거야.",
  ui_story_5038_50380801_274_dialog_content = "모두를 봐.",
  ui_story_5038_50380801_275_dialog_content = "정말 이렇게 오랫동안 바쁠 줄은 몰랐네요.",
  ui_story_5038_50380801_276_dialog_content = "이제야 잠 좀 잘 수 있겠어요.",
  ui_story_5038_50380801_277_dialog_content = "그러게 말이야. 내일부턴 돛대 수리나 물 퍼내는 건 안 해도 되니 말이야.",
  ui_story_5038_50380801_278_dialog_content = "이제 드디어 용주로 돌아갈 수 있게 된 거야.",
  ui_story_5038_50380901_1_dialog_content = "<color=#e8d9bb>5일 후</color>",
  ui_story_5038_50380901_2_dialog_content = "선장님, 배의 각 부위를 살펴본 결과 큰 문제는 없었습니다.",
  ui_story_5038_50380901_3_dialog_content = "화물창 쪽은 여전히 경미한 누수 부위가 있습니다만, 어제보다 악화되지는 않았습니다.",
  ui_story_5038_50380901_4_dialog_content = "알겠어. 큰 문제가 없다면 그걸로 괜찮겠지.",
  ui_story_5038_50380901_5_dialog_content = "침수된 화물들은 처리했나?",
  ui_story_5038_50380901_6_dialog_content = "예. 완전히 못 쓰게 된 것들은 바다로 던져 버렸고,\n상태가 양호한 것들은 현재 갑판에서 말리는 중입니다.",
  ui_story_5038_50380901_7_dialog_content = "다만... 처리를 끝내고 나니 남은 식량이 많지 않습니다.",
  ui_story_5038_50380901_8_dialog_content = "식량...",
  ui_story_5038_50380901_9_dialog_content = "담수는 얼마나 남았지?",
  ui_story_5038_50380901_10_dialog_content = "담수 쪽은 식량보다 사정이 나아, 보름치 분량이 남아 있습니다.",
  ui_story_5038_50380901_11_dialog_content = "선장님, 육지에 닿으려면 얼마나 더 걸리겠습니까?",
  ui_story_5038_50380901_12_dialog_content = "미안하지만 지금은 아직 판단할 수 없어.",
  ui_story_5038_50380901_13_dialog_content = "원해 쪽은 해도가 완전하지 못해. 게다가 우린 도중에 습격을 받았어.",
  ui_story_5038_50380901_14_dialog_content = "그래서 지금은 해도상에 없는 지역에 들어와 버렸어.\n방향과 거리 모두 어림잡아 헤아릴 수밖에 없어.",
  ui_story_5038_50380901_15_dialog_content = "모두에게 며칠간은 최대한 식량 비축분을 아낄 수 있게 고기잡이를 시켜둬.",
  ui_story_5038_50380901_16_dialog_content = "담수도 마찬가지야. 식수 이외엔 최대한 사용을 줄이도록 해.",
  ui_story_5038_50380901_17_dialog_content = "가 봐.",
  ui_story_5038_50380901_18_dialog_content = "...예, 선장님.",
  ui_story_5038_50380901_19_dialog_content = "<color=#e8d9bb>다시 5일 후</color>",
  ui_story_5038_50380901_20_dialog_content = "점심 식사 양이 또 줄었잖아.",
  ui_story_5038_50380901_21_dialog_content = "맞아. 하지만 어쩔 수 없어.",
  ui_story_5038_50380901_22_dialog_content = "많이 부족하니?",
  ui_story_5038_50380901_23_dialog_content = "부족한 정도가 아니라 한 입도 못 먹었다구.",
  ui_story_5038_50380901_24_dialog_content = "내 몫은 작은꼬리한테 줬으니까.",
  ui_story_5038_50380901_25_dialog_content = "어머, 그러면 안 돼. 식사를 거르면 키가 안 클 거야.",
  ui_story_5038_50380901_26_dialog_content = "무, 무슨 고리타분한 소릴 하는 거야! 꼭 키가 커야 좋은 것만은 아니거든!",
  ui_story_5038_50380901_27_dialog_content = "난 갑판 쪽에 가 볼게.",
  ui_story_5038_50380901_28_dialog_content = "운이 좋으면 저녁엔 너랑 작은꼬리 둘 다 생선을 먹을 수 있을 거야.",
  ui_story_5038_50380901_29_dialog_content = "진짜? 내 몫도 있어?!",
  ui_story_5038_50380901_30_dialog_content = "응! 운이 좋다면 말이야...",
  ui_story_5038_50380901_31_dialog_content = "그, 그게... 난 낚시를 잘 못하거든.",
  ui_story_5038_50380901_32_dialog_content = "그래도... 내가...",
  ui_story_5038_50380901_33_dialog_content = "왜 그래? 몸이 불편해 보이는데?",
  ui_story_5038_50380901_34_dialog_content = "응? 아니야, 괜찮아...",
  ui_story_5038_50380901_35_dialog_content = "맥 짚게 손 이리 줘 봐.",
  ui_story_5038_50380901_36_dialog_content = "아니, 난...",
  ui_story_5038_50380901_37_dialog_content = "이거 병 난 거야.",
  ui_story_5038_50380901_38_dialog_content = "<color=#e8d9bb>또다시 5일 후</color>",
  ui_story_5038_50380901_39_dialog_content = "작은꼬리! 마음대로 뛰어다니면 안 된다니까!",
  ui_story_5038_50380901_40_dialog_content = "배에서 떨어지면 어쩌려고 그래!",
  ui_story_5038_50380901_41_dialog_content = "야옹.",
  ui_story_5038_50380901_42_dialog_content = "잔소리한다고 싫어하면 안 돼. 너도 좀 봐, 바람이 이렇게 세잖아.",
  ui_story_5038_50380901_43_dialog_content = "이러다 갑자기 바람이 훅 불어서 네가 바다로 날아가 버릴 수도 있어.",
  ui_story_5038_50380901_44_dialog_content = "그러니까 얼른 선실로 돌아가자.",
  ui_story_5038_50380901_45_dialog_content = "우냐앙──",
  ui_story_5038_50380901_46_dialog_content = "헉, 헉... 잘도 도망치네. 따라가질 못하겠어.",
  ui_story_5038_50380901_47_dialog_content = "별걱정 안 해도 될 거야. 동물의 위기 감지 능력은 사람보다 민감하거든.",
  ui_story_5038_50380901_48_dialog_content = "진짜 위험이 닥치면 오히려 사람이 동물들에게 의지해야 하는 경우가 많아.",
  ui_story_5038_50380901_49_dialog_content = "어라? 월백 씨도 여기 있었어요?",
  ui_story_5038_50380901_50_dialog_content = "혹시 리청 보셨어요? 오늘 통 안 보이더라고요.",
  ui_story_5038_50380901_51_dialog_content = "리청이 있었으면 작은꼬리가 마음대로 뛰어다녀도 그러려니 했을 텐데 말이에요.",
  ui_story_5038_50380901_52_dialog_content = "지금 환자 돌보는 중이야.",
  ui_story_5038_50380901_53_dialog_content = "어제도 선원 두 명이 쓰러졌거든. 다들 열병에 걸린 모양이야.",
  ui_story_5038_50380901_54_dialog_content = "환자들을 돌본다고 고생이 많아.",
  ui_story_5038_50380901_55_dialog_content = "또 환자라니...",
  ui_story_5038_50380901_56_dialog_content = "월백 씨, 앞으로 얼마나 더 가야 용주에 도착할 수 있을까요?",
  ui_story_5038_50380901_57_dialog_content = "......",
  ui_story_5038_50380901_58_dialog_content = "나도... 모르겠어...",
  ui_story_5038_50380901_59_dialog_content = "(갑자기 월백 씨에게서 참담함이 느껴졌다.)",
  ui_story_5038_50380901_60_dialog_content = "(어쩌면 애초부터 이 질문에는 대답할 말이 없었을지도 모른다.)",
  ui_story_5038_50380901_61_dialog_content = "(우리는 월백 씨에게 물어보면 된다. 하지만 월백 씨는 누구에게 물을 수 있을까.)",
  ui_story_5038_50380901_62_dialog_content = "바다는 드넓어서, 용주처럼 먼 곳은 육안으론 보이지 않아.",
  ui_story_5038_50380901_63_dialog_content = "난 그저 가까이에 있는 것들만 볼 수 있을 뿐이야.",
  ui_story_5038_50380901_64_dialog_content = "안으로 돌아가자. 폭풍이 올 거야.",
  ui_story_5038_50380901_65_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5038_50380901_66_dialog_content = "선장님, 갑판에 두었던 물건들은 모두 정리가 끝났습니다.\n선원들도 모두 건강을 회복했습니다.",
  ui_story_5038_50380901_67_dialog_content = "바닥짐도 확인해 봤어?",
  ui_story_5038_50380901_68_dialog_content = "예, 무게에는 문제가 없었으니, 풍랑을 견딜 수 있을 겁니다.",
  ui_story_5038_50380901_69_dialog_content = "좋아, 준비 작업은 이 정도면 되겠지.",
  ui_story_5038_50380901_70_dialog_content = "선미로 가서 명령을 기다리도록 해.",
  ui_story_5038_50380901_71_dialog_content = "아... 선장님, 돛을 접어야 하지 않겠습니까?",
  ui_story_5038_50380901_72_dialog_content = "그럴 필요 없어. 돛을 최대로 펼쳐.",
  ui_story_5038_50380901_73_dialog_content = "이 폭풍 속에서 돛을 활짝 펴고 항해하시겠다는 겁니까?!",
  ui_story_5038_50380901_74_dialog_content = "너, 너무 위험합니다! 선체를 제어할 수 없게 될 겁니다!",
  ui_story_5038_50380901_75_dialog_content = "게다가... 저번처럼 파도를 타고 암귀가 배를 습격할 수도 있지 않습니까!",
  ui_story_5038_50380901_76_dialog_content = "알고 있어. 하지만 더는 못 기다려.",
  ui_story_5038_50380901_77_dialog_content = "우릴 재촉하는 건 이 바다뿐만이 아니야. 시간도 우리 편이 아냐.",
  ui_story_5038_50380901_78_dialog_content = "신풍호가 멈춰 버리면 뭍에 닿을 기회를 영영 잃을지도 몰라.",
  ui_story_5038_50380901_79_dialog_content = "......",
  ui_story_5038_50380901_80_dialog_content = "그러니까 우린 모든 바람을 타는 수밖에 없어. 그게 설령 폭풍이라 해도 말이야.",
  ui_story_5038_50380901_81_dialog_content = "이 틈에 갑판에 오르는 암귀들이 있더라도, 무서워해야 할 건 우리가 아니라 녀석들이야.",
  ui_story_5038_50380901_82_dialog_content = "몸을 풀 기회만 기다리는 승객들이 한둘이 아니니까.",
  ui_story_5038_50380901_83_dialog_content = "선장님께서 그렇게 말씀하신다면야...",
  ui_story_5038_50380901_84_dialog_content = "휴, 됐습니다! 전 선원이니, 선장님 말씀을 따라야지요!",
  ui_story_5038_50380901_85_dialog_content = "좋아. 그럼 즉시 선미에 가서 대기하도록 해.",
  ui_story_5038_50380901_86_dialog_content = "곧 파도가 일기 시작할 거야. 수시로 내 명령을 확인해.",
  ui_story_5038_50380901_87_dialog_content = "예!",
  ui_story_5038_50381001_1_dialog_content = "(신풍호는 폭풍 속에서 꼬박 하루를 요동쳤다.)",
  ui_story_5038_50381001_2_dialog_content = "(그동안 우리는 멀미와 충돌, 그리고 암귀에 시달렸다.)",
  ui_story_5038_50381001_3_dialog_content = "(그러나 조금 전부터 광풍이 돛을 찢던 무서운 소리가 점점 작아지고 있다.)",
  ui_story_5038_50381001_4_dialog_content = "(우리 모두 알 수 있었다. 신풍호는 버텨낸 것이었다.)",
  ui_story_5038_50381001_5_dialog_content = "이제 갑판에 위험은 사라진 것 같구나.",
  ui_story_5038_50381001_6_dialog_content = "그런 것 같네요. 이걸로 폭풍을 벗어난 건가요?",
  ui_story_5038_50381001_7_dialog_content = "응, 가장 힘겨운 구간은 어떻게든 버텨냈어.",
  ui_story_5038_50381001_8_dialog_content = "아직 바람과 파도가 조금 더 있긴 하겠지만, 방심하지만 않으면 돼.",
  ui_story_5038_50381001_9_dialog_content = "아이고, 천지신명님, 감사합니다. 큰 고비를 넘겼군요.",
  ui_story_5038_50381001_10_dialog_content = "더 흔들었다간 소생의 오장육부가 남아나질 않았을 겁니다.",
  ui_story_5038_50381001_11_dialog_content = "천간 씨, 괜찮아요? 안색이 엄청 안 좋은데요.",
  ui_story_5038_50381001_12_dialog_content = "별일 아닙니다. 갑판에서 바람을 좀 쐬면 괜찮아질 겁니다.",
  ui_story_5038_50381001_13_dialog_content = "목 선장님, 이제 배를 좀 채워야 하지 않겠습니까?",
  ui_story_5038_50381001_14_dialog_content = "하루 종일 폭풍 속을 나뒹굴면서 아무것도 못 먹었습니다.\n이대로는 몸이 버티질 못해요.",
  ui_story_5038_50381001_15_dialog_content = "응, 맞아.",
  ui_story_5038_50381001_16_dialog_content = "일항사, 주방에 가서 저녁 식사 준비를 하라고 해줘.",
  ui_story_5038_50381001_17_dialog_content = "예.",
  ui_story_5038_50381001_18_dialog_content = "헌데 선장님... 남은 식량이 부족해서 하루 분량을 정해 둬야 합니다.",
  ui_story_5038_50381001_19_dialog_content = "앞으로 얼마나 더 바다 위에서 지내야 하는지 알려 주셔야...",
  ui_story_5038_50381001_20_dialog_content = "...지금도 확실한 답은 없어.",
  ui_story_5038_50381001_21_dialog_content = "그래도 오늘은 다들 배불리 먹게 해 줘.",
  ui_story_5038_50381001_22_dialog_content = "...아니, 칠 할 정도만.",
  ui_story_5038_50381001_23_dialog_content = "일항사님, 우리 식량은 얼마나 남았죠?",
  ui_story_5038_50381001_24_dialog_content = "......",
  ui_story_5038_50381001_25_dialog_content = "일항사님이 모를 리가 없잖아요. 좀 말해줘요.",
  ui_story_5038_50381001_26_dialog_content = "상황이 안 좋다는 건 저도 알아요. 그냥 마음의 준비 정도는 해 두고 싶어서 그래요.",
  ui_story_5038_50381001_27_dialog_content = "이대로는 안 되겠어.",
  ui_story_5038_50381001_28_dialog_content = "네?",
  ui_story_5038_50381001_29_dialog_content = "가서 다들 오라고 해. 고기를 더 잡아 둬야겠어.",
  ui_story_5038_50381001_30_dialog_content = "지금요? 아직 하던 일도 못 끝냈는데...",
  ui_story_5038_50381001_31_dialog_content = "중요한 게 아니면 나중으로 미뤄 둬.",
  ui_story_5038_50381001_32_dialog_content = "이제부턴 고기잡이 시간을 더 많이 배정할 거니까.",
  ui_story_5038_50381001_33_dialog_content = "안 그랬다간 며칠 뒤면 배가 덜 차는 정도론 안 끝날 거야.",
  ui_story_5038_50381001_34_dialog_content = "그렇게 심각한 건가요...",
  ui_story_5038_50381001_35_dialog_content = "알겠어요. 가서 다른 선원들도 불러올게요.",
  ui_story_5038_50381001_36_dialog_content = "자! 이쪽 그물을 올린다!",
  ui_story_5038_50381001_37_dialog_content = "다들 같이 당겨!",
  ui_story_5038_50381001_38_dialog_content = "이영차!",
  ui_story_5038_50381001_39_dialog_content = "왜 선원들이 전부 갑판에 모여서 물고기를 잡고 있죠?",
  ui_story_5038_50381001_40_dialog_content = "식량... 때문인가요?",
  ui_story_5038_50381001_41_dialog_content = "분명히 그렇겠죠. 굶주림은 가장 원초적인 문제니까요.",
  ui_story_5038_50381001_42_dialog_content = "배는 모두의 힘으로 고쳤지만, 사람이 버틸 수 있느냐 없냐는 별개의 문제입니다.",
  ui_story_5038_50381001_43_dialog_content = "휴...",
  ui_story_5038_50381001_44_dialog_content = "그래도 바다에선 적어도 먹을 물고기가 부족할 일은 없는 걸\n그나마 다행이라고 생각해야 하는 걸까요...",
  ui_story_5038_50381001_45_dialog_content = "문제는 그게 다가 아닙니다.",
  ui_story_5038_50381001_46_dialog_content = "다들 매일 물고기를 먹으며 버틴다고 해도, 담수는 하루하루 줄어들고 있거든요.",
  ui_story_5038_50381001_47_dialog_content = "담수까지 다 떨어지고 나면, 이번 항해에 희망은 없다고 봐도 좋습니다.",
  ui_story_5038_50381001_48_dialog_content = "사람은 말이지요. 결국에는 육지에서 생활해야 하는 동물이니까요.",
  ui_story_5038_50381001_49_dialog_content = "바다에 발을 들인 그 순간부터 삶의 끝을 향한 초읽기가 시작되는 것입니다.",
  ui_story_5038_50381001_50_dialog_content = "초읽기...",
  ui_story_5038_50381001_51_dialog_content = "우리한테 남은 시간은 얼마나 있는 걸까요.",
  ui_story_5038_50381001_52_dialog_content = "한 마리 더 잡았어! 이놈 이거 힘이 장사네!",
  ui_story_5038_50381001_53_dialog_content = "다들 와서 좀 당겨!",
  ui_story_5038_50381001_54_dialog_content = "하나, 둘, 셋!",
  ui_story_5038_50381001_55_dialog_content = "<color=#e8d9bb>촤아악──</color>",
  ui_story_5038_50381001_56_dialog_content = "이야! 월척이네! 대어야, 대어!",
  ui_story_5038_50381001_57_dialog_content = "하하하하! 됐어! 됐다고!",
  ui_story_5038_50381001_58_dialog_content = "이 정도 크기면 대여섯 명은 먹을 수 있겠어!",
  ui_story_5038_50381001_59_dialog_content = "우와! 진짜 크네요!",
  ui_story_5038_50381001_60_dialog_content = "오오! 소생도 이렇게 커다란 물고기는 처음 봅니다!",
  ui_story_5038_50381001_61_dialog_content = "자, 얼른 주방에 갖다줘.",
  ui_story_5038_50381001_62_dialog_content = "오늘 저녁도 부족했을 텐데, 이걸로 배를 채워 보자고!",
  ui_story_5038_50381001_63_dialog_content = "<size=50>좋습니다!</size>",
  ui_story_5038_50381001_64_dialog_content = "녀석을 놓아주시오.",
  ui_story_5038_50381001_65_dialog_content = "뭐? 누구야?!",
  ui_story_5038_50381001_66_dialog_content = "종 모올시다. 그 물고기를 놓아주라 하였소.",
  ui_story_5038_50381001_67_dialog_content = "아, 종 대인이셨군요... 헌데 어찌 그러시는지...",
  ui_story_5038_50381001_68_dialog_content = "형님 말씀이 맞아. 얼른 그 녀석을 놔 줘.",
  ui_story_5038_50381001_69_dialog_content = "잘 봐! 걘 교룡어잖아!",
  ui_story_5038_50381001_70_dialog_content = "교룡어?!",
  ui_story_5038_50381001_X70_dialog_content = "이런, 지금까지 전혀 주의를 못 했잖아... 이 녀석, 전에 우릴 공격했던 그...",
  ui_story_5038_50381001_71_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5038_50381001_72_dialog_content = "으아아앗!",
  ui_story_5038_50381001_73_dialog_content = "으악!",
  ui_story_5038_50381001_74_dialog_content = "뭐지? 배가 뭐에 부딪힌 건가?!",
  ui_story_5038_50381001_75_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5038_50381001_76_dialog_content = "또, 또 시작이군요!",
  ui_story_5038_50381001_77_dialog_content = "다들 아래를 봐!",
  ui_story_5038_50381001_78_dialog_content = "물고기 떼가 배를 들이받고 있어!",
  ui_story_5038_50381001_79_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5038_50381001_80_dialog_content = "조심해! 갑판 위로 뛰어오른다!",
  ui_story_5038_50381002_1_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5038_50381002_2_dialog_content = "으아아아아!",
  ui_story_5038_50381002_3_dialog_content = "어떡하지? 녀석들이 계속 우릴 들이받고 있어!",
  ui_story_5038_50381002_4_dialog_content = "배 바닥은 판자를 덧대 수리한 건데, 녀석들 때문에 부서지기라도 했다간...",
  ui_story_5038_50381002_5_dialog_content = "빨리 그 물고기 이리 줘!",
  ui_story_5038_50381002_6_dialog_content = "뭐?",
  ui_story_5038_50381002_7_dialog_content = "자, 자, 우리 귀하신 교룡어 나리, 얼른 돌아가세요!",
  ui_story_5038_50381002_8_dialog_content = "에잇!",
  ui_story_5038_50381002_9_dialog_content = "<color=#e8d9bb>풍덩!</color>",
  ui_story_5038_50381002_10_dialog_content = "자, 이제 괜찮을 거야.",
  ui_story_5038_50381002_11_dialog_content = "저 녀석 때문에 물고기 떼가 우릴 공격했던 거야?",
  ui_story_5038_50381002_12_dialog_content = "응, 교룡어는 집단의식이 아주 강하거든.",
  ui_story_5038_50381002_13_dialog_content = "그래서 한 마리가 위험에 빠지면, 무리 전체가 그 한 마리를 구하러 와.",
  ui_story_5038_50381002_14_dialog_content = "바다에서 교룡어랑 엮이는 건 엄청 무서운 일이라구.",
  ui_story_5038_50381002_15_dialog_content = "집단의식이라니... 굉장히 특이한 습성이네.",
  ui_story_5038_50381002_16_dialog_content = "종 대인, 정말 감사합니다. 리청, 너도 정말 고맙구나.",
  ui_story_5038_50381002_17_dialog_content = "저희가 경솔해서 하마터면 큰일이 날 뻔했습니다.",
  ui_story_5038_50381002_18_dialog_content = "천만에, 괜찮아! 다들 한배를 탄 식구들이잖아. 그럴 거 없어~",
  ui_story_5038_50381002_19_dialog_content = "별일 없이 끝났으니까, 그걸로 됐지 뭐.",
  ui_story_5038_50381002_20_dialog_content = "근처에 교룡어가 있을 줄이야... 설마 또 우리 배를 공격하진 않겠지?",
  ui_story_5038_50381002_21_dialog_content = "한 번 더 아까처럼 당했다간 배가 못 버틸 거라고...",
  ui_story_5038_50381002_22_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5038_50381002_23_dialog_content = "또 교룡어잖아! 빨리 풀어 줘!",
  ui_story_5038_50381002_24_dialog_content = "알고 있다고. 이번이 처음도 아니고.",
  ui_story_5038_50381002_25_dialog_content = "휴... 그냥 물고기나 잡게 교룡어는 좀 그만 걸렸으면 좋겠는데.",
  ui_story_5038_50381002_26_dialog_content = "일곱 마리째...",
  ui_story_5038_50381002_27_dialog_content = "월백 씨! 여기 있었군요!",
  ui_story_5038_50381002_28_dialog_content = "점심 준비 끝났어요. 다들 월백 씨 좀 불러 달라고 해서요.",
  ui_story_5038_50381002_29_dialog_content = "오늘 점심은 꽤 풍성해요. 전부 생선 요리긴 하지만요. 아하하...",
  ui_story_5038_50381002_30_dialog_content = "다들 먼저 먹어. 난 됐어.",
  ui_story_5038_50381002_31_dialog_content = "네? 식사 안 하세요?",
  ui_story_5038_50381002_32_dialog_content = "무슨... 고민이라도 있으세요?",
  ui_story_5038_50381002_33_dialog_content = "걸리는 일이 있어. 우선 그 이유부터 파악해야 마음이 조금 편해질 것 같아.",
  ui_story_5038_50381002_34_dialog_content = "네? 마음에 걸리는 일이라는 게...",
  ui_story_5038_50381002_35_dialog_content = "이 교룡어들의 행동은 뭔가 이상해.",
  ui_story_5038_50381002_36_dialog_content = "교룡어들은 무리를 지어 먼바다를 오가는 습성이 있어.\n그렇게 항상 용주와 아스트라 대륙 사이를 오가고 있었지.",
  ui_story_5038_50381002_37_dialog_content = "간혹 육지와 가까운 곳에서 잠시 머무는 일은 있어도,\n어느 한곳에 계속 머문 적은 없었어.",
  ui_story_5038_50381002_38_dialog_content = "하지만 그런 습성을 지닌 교룡어들이 이 해역에선 무리를 지어 주변을 배회하고 있어.",
  ui_story_5038_50381002_39_dialog_content = "그러게요. 오늘도 선원들이 고기를 잡을 때 계속 교룡어가 그물에 걸리더라구요.",
  ui_story_5038_50381002_40_dialog_content = "설마 교룡어들이 또 우릴 공격하진 않겠죠?",
  ui_story_5038_50381002_41_dialog_content = "아직까지 그런 기미는 없었어.",
  ui_story_5038_50381002_42_dialog_content = "저번 같은 일이 다시 없도록 최대한 물고기 떼는 피해서 운항하고 있어.",
  ui_story_5038_50381002_43_dialog_content = "어쨌든 교룡어의 행적이 이상한 것만 봐도,\n이 해역에 뭔가 심상치 않은 점이 있는 건 분명해.",
  ui_story_5038_50381002_44_dialog_content = "교룡어들이 용주보다 이 해역에 이끌리는 이유가 분명히 있을 거야.",
  ui_story_5038_50381002_45_dialog_content = "음...",
  ui_story_5038_50381002_46_dialog_content = "당신은 식사하러 가. 난 해도를 좀 봐야겠어.",
  ui_story_5038_50381002_47_dialog_content = "신풍호의 지금 위치는...",
  ui_story_5038_50381002_48_dialog_content = "어제의 운항 방향과 풍속을 고려하면...",
  ui_story_5038_50381002_49_dialog_content = "아니야, 이것보다 조금 더 북쪽에 가까워...",
  ui_story_5038_50381002_50_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5038_50381002_51_dialog_content = "누구?",
  ui_story_5038_50381002_52_dialog_content = "종 모가 선장을 만나러 왔소.",
  ui_story_5038_50381002_53_dialog_content = "종 대인? 무슨 일로 절...",
  ui_story_5038_50381002_54_dialog_content = "배에서 지낸 날도 이제 꽤 되었는데, 나로서는 방향을 알 수가 없어 찾아와 보았소.",
  ui_story_5038_50381002_55_dialog_content = "예가 아님은 알고 있으나 차마 묻지 않을 수가 없구려.\n지금 신풍호는 어디쯤 온 것이오?",
  ui_story_5038_50381002_56_dialog_content = "어디쯤이라...",
  ui_story_5038_50381002_57_dialog_content = "해도가 아직 불완전해 정확한 위치는 저도 말씀드릴 수가 없어요.",
  ui_story_5038_50381002_58_dialog_content = "조금 더 분석을 해 봐야 대략적인 위치를 알려드릴 수 있을 것 같네요.",
  ui_story_5038_50381002_59_dialog_content = "알겠소. 내 항해에는 문외한인 터라, 그저 물어나 보았을 뿐이오.",
  ui_story_5038_50381002_60_dialog_content = "이 배의 선장은 그대이니, 앞으로의 계획이 있다면 그것으로 되었소.",
  ui_story_5038_50381002_61_dialog_content = "......",
  ui_story_5038_50381002_62_dialog_content = "그대 역시 혹여 이 사람처럼 마음에 정한 바가 없는 것은 아닐까 염려되었을 뿐이오.",
  ui_story_5038_50381002_63_dialog_content = "휴...",
  ui_story_5038_50381002_64_dialog_content = "종 대인, 전 감히 이 바다를 두고 단언할 정도의 배포는 없어요.",
  ui_story_5038_50381002_65_dialog_content = "제가 답해 드릴 수 있는 건 그저 제가 최선을 다하고 있다는 것뿐이에요.",
  ui_story_5038_50381002_66_dialog_content = "아득한 길을 헤쳐 나갈 뿐, 앞길은 묻지 않는다는 것인가...",
  ui_story_5038_50381002_67_dialog_content = "선장의 굳은 결의에 탄복하는 바이오.",
  ui_story_5038_50381002_68_dialog_content = "허나 이 바다에 단언하지 못할 것들만이 있는 것은 아니오.",
  ui_story_5038_50381002_69_dialog_content = "......",
  ui_story_5038_50381002_70_dialog_content = "「나침반」 말씀이시군요. 그렇죠?",
  ui_story_5038_50381002_71_dialog_content = "그렇소. 목 선장이 이번 항해의 완수를 가장 중시하고 있음은 알고 있소.",
  ui_story_5038_50381002_72_dialog_content = "허나 지금의 신풍호는 위치도 정확히 헤아릴 수 없을뿐더러, 물자도 고갈되고 있소.\n이 난관을 타개할 방법은 오직 「나침반」을 찾아내는 것뿐이오.",
  ui_story_5038_50381002_73_dialog_content = "「나침반」을 찾는다고요...?",
  ui_story_5038_50381002_74_dialog_content = "대인의 말씀처럼 나침반에 신통하고 강력한 힘이 있다고 한들...",
  ui_story_5038_50381002_75_dialog_content = "지금 상황에선 바다를 돌아다니며 나침반을 찾을 만한 여력이 없어요...",
  ui_story_5038_50381002_76_dialog_content = "혹여 바다를 돌아다닐 필요가 없다고 한다면 어떠한가.",
  ui_story_5038_50381002_77_dialog_content = "린 가문의 가보 「나침반」은, 바로 눈앞의 해역에 있소.",
  ui_story_5038_50381002_78_dialog_content = "네?!",
  ui_story_5038_50381002_79_dialog_content = "휴...",
  ui_story_5038_50381002_80_dialog_content = "이 상자에 든 식량도 상해버렸군...",
  ui_story_5038_50381002_81_dialog_content = "이걸 버려야 하나...",
  ui_story_5038_50381002_82_dialog_content = "굶는 것보다는 상한 거라도 먹는 게 낫나...",
  ui_story_5038_50381002_83_dialog_content = "담수는 또 얼마나 남았나...",
  ui_story_5038_50381002_84_dialog_content = "<color=#e8d9bb>덜커덩──</color>",
  ui_story_5038_50381002_85_dialog_content = "이건 텅 비었군.",
  ui_story_5038_50381002_86_dialog_content = "비나이다, 비나이다. 빗물이라도 받게 제발 비 좀 내려 주십쇼...",
  ui_story_5038_50381002_87_dialog_content = "하나, 둘, 셋... 남은 건 이게 다인가...",
  ui_story_5038_50381002_88_dialog_content = "어휴, 드디어 찾았네! 일항사님, 여기 계셨어요?",
  ui_story_5038_50381002_89_dialog_content = "뭐야? 왜 그래?",
  ui_story_5038_50381002_90_dialog_content = "빨리 저랑 가요. 선장님이 급히 찾으셔요!",
  ui_story_5038_50381101_1_dialog_content = "자, 물고기는 그만들 잡고, 저 먼 곳의 해수면을 잘 봐!",
  ui_story_5038_50381101_2_dialog_content = "선장님께서 이 바다를 샅샅이 뒤지라고 하신다!",
  ui_story_5038_50381101_3_dialog_content = "뭔가 발견하면 바로 나한테 보고해!",
  ui_story_5038_50381101_4_dialog_content = "예!",
  ui_story_5038_50381101_5_dialog_content = "우리 지금 「나침반」 찾고 있는 거 맞지?",
  ui_story_5038_50381101_6_dialog_content = "응. 아니면 왜 선원들한테 텅 빈 바다를 잘 지켜보라고 했겠어.",
  ui_story_5038_50381101_7_dialog_content = "그럼 「나침반」은 린 가문의 옛 신풍호에 있을 거란 얘기인데...",
  ui_story_5038_50381101_8_dialog_content = "참, 네가 저번에 나한테 옛 신풍호는 침몰한 게 아니라고 그랬잖아.",
  ui_story_5038_50381101_9_dialog_content = "응, 적어도 나랑 형님이 떠날 때까진 가라앉지 않았으니까.",
  ui_story_5038_50381101_10_dialog_content = "그럼 그 배가 계속 이 바다에서 혼자 둥둥 떠다니고 있을 거란 얘기야?",
  ui_story_5038_50381101_11_dialog_content = "그렇게 생각하면 뭔가 좀 무서운데...",
  ui_story_5038_50381101_12_dialog_content = "찾기 편할 테니까 그편이 낫지 않아?",
  ui_story_5038_50381101_13_dialog_content = "근데... 시간이 꽤 지났으니까 폭풍이나 큰 파도를 만났을지도 몰라.",
  ui_story_5038_50381101_14_dialog_content = "배에 아무도 없다면 쉽게 가라앉지 않았을까?",
  ui_story_5038_50381101_15_dialog_content = "아니, 안 가라앉았을걸.",
  ui_story_5038_50381101_16_dialog_content = "말했잖아. 우리가 찾고 있는 보물 「나침반」이 그 위에 있다고.",
  ui_story_5038_50381101_17_dialog_content = "이런, 날이 어두워졌군...",
  ui_story_5038_50381101_18_dialog_content = "아니면 오늘은 여기까지 할까요?",
  ui_story_5038_50381101_19_dialog_content = "해가 지면 다들 아무것도 안 보이잖아요.",
  ui_story_5038_50381101_20_dialog_content = "하지만 이래서야 오늘은 아무 수확도 없잖아...",
  ui_story_5038_50381101_21_dialog_content = "이제 우린 남은 날도 얼마 없다고.",
  ui_story_5038_50381101_22_dialog_content = "저기 뭔가 있어!",
  ui_story_5038_50381101_23_dialog_content = "뭐?!",
  ui_story_5038_50381101_24_dialog_content = "저기! 저쪽! 내가 가리키고 있는 델 봐!",
  ui_story_5038_50381101_25_dialog_content = "진짜 뭔가 떠 있잖아! 이쪽으로 떠내려온다!",
  ui_story_5038_50381101_26_dialog_content = "저건... 나무판자인가?",
  ui_story_5038_50381101_27_dialog_content = "조금만 더... 더 가까이...",
  ui_story_5038_50381101_28_dialog_content = "보, 보인다!",
  ui_story_5038_50381101_29_dialog_content = "팻말 같아! 위에 뭐라고 적혀 있는 것 같은데...",
  ui_story_5038_50381101_30_dialog_content = "「린」이야!",
  ui_story_5038_50381101_31_dialog_content = "린 가문의 현판이라구!",
  ui_story_5038_50381101_32_dialog_content = "린 가문의 현판?! 그럼 설마 옛 신풍호가...",
  ui_story_5038_50381101_33_dialog_content = "물에 빠진 지 얼마 안 된 것 같아!",
  ui_story_5038_50381101_34_dialog_content = "옛 신풍호는 분명히 이 근처에 있을 거야!",
  ui_story_5038_50381101_35_dialog_content = "조각배는 어디 있어? 내가 조각배를 타고 내려가 볼게!",
  ui_story_5038_50381101_36_dialog_content = "지금?!",
  ui_story_5038_50381101_37_dialog_content = "잠깐 기다렸다가 월백 씨랑 상의한 다음에 결정하는 게 나을 것 같은데...",
  ui_story_5038_50381101_38_dialog_content = "그럴 필요 없어.",
  ui_story_5038_50381101_39_dialog_content = "어라? 월백 씨...?",
  ui_story_5038_50381101_40_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_5038_50381101_41_dialog_content = "월백 씨?! 월백 씨가 물에 뛰어들어 버렸는데?!",
  ui_story_5038_50381101_42_dialog_content = "물을 안 무서워하다니... 정말 부럽네!",
  ui_story_5038_50381101_43_dialog_content = "안 돼... 나도 뒤처질 수 없어!",
  ui_story_5038_50381101_44_dialog_content = "빨리! 배를 아래로 내려 줘!",
  ui_story_5038_50381101_45_dialog_content = "(물에서 나무 냄새가 나.)",
  ui_story_5038_50381101_46_dialog_content = "(저 아래, 더 깊은 곳에서 올라오고 있어.)",
  ui_story_5038_50381101_47_dialog_content = "(옛 신풍호는 여기 가라앉아 있는 걸까.)",
  ui_story_5038_50381101_48_dialog_content = "(「나침반」은... 고장 나진 않았겠지?)",
  ui_story_5038_50381101_49_dialog_content = "(휴... 결국 내가 아닌 다른 것의 힘을 빌리게 되는 거구나.)",
  ui_story_5038_50381101_50_dialog_content = "(계속 내려가 보자.)",
  ui_story_5038_50381101_51_dialog_content = "(더 깊은 곳까지 잠수해야 할 것 같아.)",
  ui_story_5038_50381101_52_dialog_content = "(바닥까지...)",
  ui_story_5038_50381101_53_dialog_content = "(응? 저건...?)",
  ui_story_5038_50381101_54_dialog_content = "(!!!)",
  ui_story_5038_50381101_55_dialog_content = "(침몰선이잖아... 게다가 여러 척...)",
  ui_story_5038_50381101_56_dialog_content = "(그렇게나 봐 왔던 배들이지만, 바다 밑에서 볼 때는 이런 느낌이었다니.)",
  ui_story_5038_50381101_57_dialog_content = "(너무나도 고요해. 이상할 정도로.)",
  ui_story_5038_50381101_58_dialog_content = "(사고를 당했을 때 얼마나 큰 파도에 휘말렸든,\n바다로 가라앉고 나면 고요함밖에 남지 않는구나.)",
  ui_story_5038_50381101_59_dialog_content = "(너무 고요해서 무서워질 정도네.)",
  ui_story_5038_50381101_60_dialog_content = "(바다가 집어삼킨 건 배뿐만이 아냐. 사람들의 감정과 비명도 모두 이 안에 있어.)",
  ui_story_5038_50381101_61_dialog_content = "(바다는 모든 걸 똑같은 꼴로 만들어 버려. 수면에 이는 물결까지 일치하도록.)",
  ui_story_5038_50381101_62_dialog_content = "(여긴 침몰선들의 무덤이자, 항구 같은 곳이구나.)",
  ui_story_5038_50381101_63_dialog_content = "(한 번 정박하면, 다시는 출발할 수 없는 항구.)",
  ui_story_5038_50381101_64_dialog_content = "(저쪽으로 가서 좀 살펴볼까.)",
  ui_story_5038_50381101_65_dialog_content = "(그런데... 왜 린 가문의 배는 보이지 않는 걸까...)",
  ui_story_5038_50381101_66_dialog_content = "<color=#e8d9bb>툭──</color>",
  ui_story_5038_50381101_67_dialog_content = "자, 조각배는 준비됐어.",
  ui_story_5038_50381101_68_dialog_content = "지금 바로 출발할 거야?",
  ui_story_5038_50381101_69_dialog_content = "응! 지금 당장!",
  ui_story_5038_50381101_70_dialog_content = "리청, 나도 같이 갈게.",
  ui_story_5038_50381101_71_dialog_content = "너 혼자 보내려니까 아무래도 좀...",
  ui_story_5038_50381101_72_dialog_content = "너... 물 무서워하잖아.",
  ui_story_5038_50381101_73_dialog_content = "음...",
  ui_story_5038_50381101_74_dialog_content = "그래, 그럼 너도 타.",
  ui_story_5038_50381101_75_dialog_content = "노가 너무 길어서 혼자서 저으려면 힘들거든.",
  ui_story_5038_50381101_76_dialog_content = "응! 그럼 같이 가자!",
  ui_story_5038_50381101_77_dialog_content = "이제 배를...",
  ui_story_5038_50381101_78_dialog_content = "그어어...",
  ui_story_5038_50381101_79_dialog_content = "으악! 무슨 소리야?!",
  ui_story_5038_50381101_80_dialog_content = "뭐, 뭔가가 조각배를 잡아당기고 있어!",
  ui_story_5038_50381101_81_dialog_content = "뭐?!",
  ui_story_5038_50381101_82_dialog_content = "감히 어떤 녀석이 겁도 없이...",
  ui_story_5038_50381101_83_dialog_content = "크오오──!",
  ui_story_5038_50381101_84_dialog_content = "으앗! 으아악! 깜짝이야!",
  ui_story_5038_50381101_85_dialog_content = "이 더러운 녀석은 또 어디서 튀어나온 거야?!",
  ui_story_5038_50381101_86_dialog_content = "아, 아래를 봐! 놈들이 배 내리는 밧줄을 타고 올라온다!",
  ui_story_5038_50381101_87_dialog_content = "엄청나게 많다고!",
  ui_story_5038_50381102_1_dialog_content = "크어어...",
  ui_story_5038_50381102_2_dialog_content = "운도 지지리 없네 진짜! 손이 다 더러워졌잖아.",
  ui_story_5038_50381102_3_dialog_content = "아직 더 남았어?",
  ui_story_5038_50381102_4_dialog_content = "아니, 다 해치웠어.",
  ui_story_5038_50381102_5_dialog_content = "그럼 됐어. 자, 얼른 가자.",
  ui_story_5038_50381102_6_dialog_content = "둘 다... 정말 내려갈 거야?",
  ui_story_5038_50381102_7_dialog_content = "갑판에 있는 데도 암귀한테 습격당했는데, 바닷속은 더 위험하다고.",
  ui_story_5038_50381102_8_dialog_content = "우린 배라도 타고 내려가지만, 선장님은 맨몸으로 그냥 바다에 뛰어들었잖아.",
  ui_story_5038_50381102_9_dialog_content = "우리 걱정은 말고, 선장님 걱정부터 해.",
  ui_story_5038_50381102_10_dialog_content = "가자, PlayerName.",
  ui_story_5038_50381102_11_dialog_content = "응!",
  ui_story_5038_50381102_12_dialog_content = "작은꼬리, 넌 따라오지 말고 여기 있어.",
  ui_story_5038_50381102_13_dialog_content = "야오옹?",
  ui_story_5038_50381102_14_dialog_content = "작은 배에 있으니까 새삼스럽게 바다가 엄청 넓게 느껴지네.",
  ui_story_5038_50381102_15_dialog_content = "리청, 우리가 정말 옛 신풍호를 찾아낼 수 있을까?",
  ui_story_5038_50381102_16_dialog_content = "겨우 단서를 찾았잖아. 멀리 있진 않을 거야.",
  ui_story_5038_50381102_17_dialog_content = "하지만...",
  ui_story_5038_50381102_18_dialog_content = "이미 바다에 가라앉았을까 봐 그래?",
  ui_story_5038_50381102_19_dialog_content = "맞아...",
  ui_story_5038_50381102_20_dialog_content = "아까 그 현판도 우리가 전에 봤던 잔해들처럼 떠다니고 있었잖아.",
  ui_story_5038_50381102_21_dialog_content = "그냥 바람이 불어서 떨어진 걸 수도 있지.",
  ui_story_5038_50381102_22_dialog_content = "아니면 암귀가 배에 기어오르다가 현판을 떨어트린 걸 수도 있고.",
  ui_story_5038_50381102_23_dialog_content = "아무튼 중요한 건 그게 아니라, 그 배가 이 근처에 있다는 거야.",
  ui_story_5038_50381102_24_dialog_content = "반드시 그 배를 찾아야 돼.",
  ui_story_5038_50381102_25_dialog_content = "리청 넌 생각보다 그 배를 많이 믿고 있구나?",
  ui_story_5038_50381102_26_dialog_content = "당연하지. 그 배엔 「나침반」이 있으니까.",
  ui_story_5038_50381102_27_dialog_content = "(왠지 리청은 「나침반」을 찾는 일엔 이상할 정도로 서두르는 것 같다.)",
  ui_story_5038_50381102_28_dialog_content = "(하지만 월백 씨가 다급해하는 것과는 조금 다른 느낌이다.)",
  ui_story_5038_50381102_29_dialog_content = "(월백 씨가 조급해하는 건 이해할 수 있다.\n하지만 리청이 이 일에 왜 이렇게 진지한 건지는 잘 모르겠다.)",
  ui_story_5038_50381102_30_dialog_content = "(어쩌면 리청이 평소엔 심드렁하게 있는 것을 자주 봐서 그런 것일지도 모른다.)",
  ui_story_5038_50381102_31_dialog_content = "갑자기 뭐지? 이건...",
  ui_story_5038_50381102_32_dialog_content = "안개가 끼고 있잖아?",
  ui_story_5038_50381102_33_dialog_content = "그런 것 같아. 점점 앞이 잘 안 보여.",
  ui_story_5038_50381102_34_dialog_content = "성가시게 됐잖아. 얼른 바람이나 좀 불었으면 좋겠는데.",
  ui_story_5038_50381102_35_dialog_content = "이러면 뭘 어떻게 찾으라는 거야!",
  ui_story_5038_50381102_36_dialog_content = "잠깐만, 갑자기 옛 신풍호를 찾는 것보다 더 걱정되는 게 있는데...",
  ui_story_5038_50381102_37_dialog_content = "안개 때문에 주변이 잘 안 보이면... 우린 신풍호로 어떻게 돌아가지?",
  ui_story_5038_50381102_38_dialog_content = "너 우리가 어느 쪽에서 왔는지 기억나?",
  ui_story_5038_50381102_39_dialog_content = "음, 아마 이쪽일걸.",
  ui_story_5038_50381102_40_dialog_content = "아닌가? 왼쪽인가?",
  ui_story_5038_50381102_41_dialog_content = "그럼 기억 안 난다는 거잖아!",
  ui_story_5038_50381102_42_dialog_content = "이렇게 넓은 바다에서 신풍호랑 멀리 떨어져 버리기라도 하면...",
  ui_story_5038_50381102_43_dialog_content = "에이~ 너무 걱정할 거 없어~",
  ui_story_5038_50381102_44_dialog_content = "여기 낚싯대도 있으니까, 고기를 잡아서 먹으면 며칠은 거뜬히 버틸 수 있다구.",
  ui_story_5038_50381102_45_dialog_content = "「며칠」만 살고 말 생각이냐고...",
  ui_story_5038_50381102_46_dialog_content = "우린 옛 신풍호랑 「나침반」만 찾아내면 돼.",
  ui_story_5038_50381102_47_dialog_content = "그럼 신풍호보다 우리가 먼저 용주에 도착할 수도 있어.",
  ui_story_5038_50381102_48_dialog_content = "안개가 이렇게 짙어서야 뭘 찾을 수도 없잖아.",
  ui_story_5038_50381102_49_dialog_content = "일단 여기 좀 있다가, 안개가 좀 걷히고 나면 다시 움직이는 건 어때?",
  ui_story_5038_50381102_50_dialog_content = "음, 그게 나을 것 같기도 하고...",
  ui_story_5038_50381102_51_dialog_content = "<color=#e8d9bb>촤악──</color>",
  ui_story_5038_50381102_52_dialog_content = "으아아아아악!",
  ui_story_5038_50381102_53_dialog_content = "뭐, 뭐지?!",
  ui_story_5038_50381102_54_dialog_content = "온몸이 다 젖었잖아아아!",
  ui_story_5038_50381102_55_dialog_content = "일단 내 뒤로 숨어!",
  ui_story_5038_50381102_56_dialog_content = "나야. 소리 지르지 마.",
  ui_story_5038_50381102_57_dialog_content = "어라... 월백 씨?",
  ui_story_5038_50381102_58_dialog_content = "바닷속에서 나온 거예요?",
  ui_story_5038_50381102_59_dialog_content = "그럼 여기 바다 말고 뭐가 있어?",
  ui_story_5038_50381102_60_dialog_content = "조, 좀 다른 방법으로 올라올 순 없었어?",
  ui_story_5038_50381102_61_dialog_content = "히잉... 축축해서 기분 나빠...",
  ui_story_5038_50381102_62_dialog_content = "미안, 난 바다에서 물 무서워하는 사람 돌보는 건 익숙하지가 않아서.",
  ui_story_5038_50381102_63_dialog_content = "으으, 진짜...",
  ui_story_5038_50381102_64_dialog_content = "그것보단 요점부터 말할게.",
  ui_story_5038_50381102_65_dialog_content = "아까 잠수했을 때 바다 밑바닥에서 침몰선들의 무덤을 발견했어.",
  ui_story_5038_50381102_66_dialog_content = "으으, 역시 가라앉은 배들이 있었군요...",
  ui_story_5038_50381102_67_dialog_content = "잠깐만요, 월백 씨 바다 밑바닥까지 잠수도 할 수 있어요?!",
  ui_story_5038_50381102_68_dialog_content = "물에 익숙하지 않았다면 덜컥 바다에 뛰어들 리가 없잖아.",
  ui_story_5038_50381102_69_dialog_content = "아무튼, 아래엔 꽤 많은 배들이 있었고, 대부분 상선이었어.",
  ui_story_5038_50381102_70_dialog_content = "하지만 거기에 옛 신풍호의 흔적은 없었어.",
  ui_story_5038_50381102_71_dialog_content = "역시나...",
  ui_story_5038_50381102_72_dialog_content = "수면 위는 어땠어?",
  ui_story_5038_50381102_73_dialog_content = "못 봤어요.",
  ui_story_5038_50381102_74_dialog_content = "애초에 밤이라 잘 안 보였는데, 나중엔 안개까지 껴 버렸거든요.",
  ui_story_5038_50381102_75_dialog_content = "옛 신풍호가 문제가 아니라, 지금 신풍호도 못 찾게 생겼어요.",
  ui_story_5038_50381102_76_dialog_content = "그랬구나.",
  ui_story_5038_50381102_77_dialog_content = "안개가 이렇게 심하다면 오늘은 별 수확이 없겠어.",
  ui_story_5038_50381102_78_dialog_content = "돌아가자. 노는 나한테 줘.",
  ui_story_5038_50381102_79_dialog_content = "네! 근데 신풍호가 어디 있는지 아세요?",
  ui_story_5038_50381102_80_dialog_content = "당연하지. 선장이 자기 배를 잃어버리면 안 되잖아.",
  ui_story_5038_50381102_81_dialog_content = "살았다! 그럼 이제 안심해도 되겠네요!",
  ui_story_5038_50381102_82_dialog_content = "누, 누나. 빠. 빨리이... 얼른 주방에서 가서 불 쬘래...",
  ui_story_5038_50381102_83_dialog_content = "응, 서두를게.",
  ui_story_5038_50381102_84_dialog_content = "(역시 월백 씨는 우리보다 노를 훨씬 더 잘 젓는구나. 배가 미끄러지듯 움직이고 있어.)",
  ui_story_5038_50381102_85_dialog_content = "(주위가 온통 안개로 뿌예서 방향도 모르겠고,\n이 배가 지금 전진하는 게 맞는지도 모르겠어.)",
  ui_story_5038_50381102_86_dialog_content = "(아무리 월백 씨라도 진짜로 이런 안개 속에서 방향을 구분할 수 있을까?)",
  ui_story_5038_50381102_87_dialog_content = "(하긴, 그 넓은 바다에서 우리가 타고 있던 조각배도 찾았는데,\n신풍호처럼 커다란 배를 못 찾을 리가.)",
  ui_story_5038_50381102_88_dialog_content = "으엣취──!",
  ui_story_5038_50381102_89_dialog_content = "으으우... 돌아가면 약 좀 달여 먹어야지...",
  ui_story_5038_50381102_90_dialog_content = "어? 저건...",
  ui_story_5038_50381102_91_dialog_content = "우와아아! 신풍호다! 드디어 돌아왔어!",
  ui_story_5038_50381102_92_dialog_content = "그러네. 안개 때문에 이렇게 가까이 와서야 알았잖아.",
  ui_story_5038_50381102_93_dialog_content = "그러고 보니까 신풍호를 이런 각도에서 보는 건 처음인 것 같아.",
  ui_story_5038_50381102_94_dialog_content = "진짜 웅장하네.",
  ui_story_5038_50381102_95_dialog_content = "얼른 사람들한테 올려달라고 하자.",
  ui_story_5038_50381102_96_dialog_content = "선원들! 여기야!",
  ui_story_5038_50381102_97_dialog_content = "우리 여기 있어!",
  ui_story_5038_50381102_98_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5038_50381102_99_dialog_content = "왜 아무도 안 나와? 다 자러 갔나?",
  ui_story_5038_50381102_100_dialog_content = "그러게. 왜 이렇게 조용하지?",
  ui_story_5038_50381102_101_dialog_content = "저기요! 아무도 없어요?",
  ui_story_5038_50381102_102_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5038_50381102_103_dialog_content = "이상하네? 이렇게 크게 소리를 질렀는데 아무 반응도 없어.",
  ui_story_5038_50381102_104_dialog_content = "안개 때문에 잘 안 보이는 건 그렇다 쳐도, 소리까지 안 들리는 건 아닐 거잖아?",
  ui_story_5038_50381102_105_dialog_content = "이 배...",
  ui_story_5038_50381102_106_dialog_content = "월백 씨, 대체 어떻게 된 걸까요?",
  ui_story_5038_50381102_107_dialog_content = "일단 올라가서 확인해 보자.",
  ui_story_5038_50381102_108_dialog_content = "앞쪽에 밧줄이 하나 있으니까, 그걸 타고 올라가면 될 거야.",
  ui_story_5038_50381201_1_dialog_content = "갑자기 안개가 이리 자욱해지다니, 이상하네.",
  ui_story_5038_50381201_2_dialog_content = "그러게요. 선장님이랑 리청, PlayerName 공자 세 사람 전부 바다에 있는데,\n이러다 배를 못 찾고 헤매기라도 하면...",
  ui_story_5038_50381201_3_dialog_content = "이 넓은 바다에서 무슨 일이 있을지...",
  ui_story_5038_50381201_4_dialog_content = "그 셋이 바다에 있다고? 그게 무슨 말이지?",
  ui_story_5038_50381201_5_dialog_content = "아까 옛 신풍호의 단서를 발견했다면서, 배를 찾아보겠다고 바다로 내려갔거든요.",
  ui_story_5038_50381201_6_dialog_content = "그런데 하필 이럴 때 안개가 낄 줄은...",
  ui_story_5038_50381201_7_dialog_content = "모두에게 횃불을 들고 갑판 주변을 지키라고 해.",
  ui_story_5038_50381201_8_dialog_content = "배가 최대한 움직이지 않게 돛은 접어 뒀어.",
  ui_story_5038_50381201_9_dialog_content = "선장님은 방향 감각이 좋으시니, 안개가 끼었더라도 찾아오실 수 있을 거야.",
  ui_story_5038_50381201_10_dialog_content = "하지만 두 꼬마들은...",
  ui_story_5038_50381201_11_dialog_content = "천하의 사기꾼이 나와 구를 무슨 연유로 불러냈을까?",
  ui_story_5038_50381201_12_dialog_content = "지금 세 사람의 행방이 묘연해졌다 하여 도우러 가려던 참이었는데.",
  ui_story_5038_50381201_13_dialog_content = "안개가 이리 자욱하니 전하께서 나서신다 한들 큰 도움이 되진 않을 겁니다.",
  ui_story_5038_50381201_14_dialog_content = "그보다 선실로 가서 소생의 용기를 좀 북돋아 주시는 것은 어떠하실지요?",
  ui_story_5038_50381201_15_dialog_content = "용기를 북돋아? 또 무슨 수작을 부리려고?",
  ui_story_5038_50381201_16_dialog_content = "소생, 종서 대인을 만나고자 합니다.",
  ui_story_5038_50381201_17_dialog_content = "음? 만나면 그만이지, 무슨 용기가 필요해?",
  ui_story_5038_50381201_18_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5038_50381201_19_dialog_content = "종 대인, 여기 계셨군요.",
  ui_story_5038_50381201_20_dialog_content = "안개가 자욱하군. 무슨 일이라도 생겼는가.",
  ui_story_5038_50381201_21_dialog_content = "선원들 말로는 목 선장과 리청, 그리고 PlayerName 공자가 옛 신풍호를 찾아\n바다로 나갔다가 지금까지 행방을 알 수 없다고 하더군요...",
  ui_story_5038_50381201_22_dialog_content = "공교롭게 이런 때에 안개가 끼다니.",
  ui_story_5038_50381201_23_dialog_content = "세 사람이 옛 신풍호를 찾아냈다면 다행이겠지.",
  ui_story_5038_50381201_24_dialog_content = "허나 바다란 흉흉한 곳이니만큼, 찾아내지 못했다면 여간 큰일이 아니오.",
  ui_story_5038_50381201_25_dialog_content = "맞습니다. 게다가 이 근처에는 교룡어들이 몰려다니고 있으니,\n무슨 변고를 당할지도 모르고 말입니다.",
  ui_story_5038_50381201_26_dialog_content = "지금은 바닷속의 동향을 파악할 수도 없고,\n자칫하면 이 신풍호까지 위태로워질 수 있습니다.",
  ui_story_5038_50381201_27_dialog_content = "맞아... 그렇게 보면 우리도 결코 안전하지 못한 상황이야...",
  ui_story_5038_50381201_28_dialog_content = "지금 신풍호는 한 번의 공격을 버텨낼 여력도 남아있지 않아.",
  ui_story_5038_50381201_29_dialog_content = "상황이 이렇게 된 이상, 소생이 신풍호의 운명을 점쳐 보도록 하지요.",
  ui_story_5038_50381201_30_dialog_content = "습격의 연유를 알 수 있다면, 대응하기도 훨씬 수월하지 않겠습니까.",
  ui_story_5038_50381201_31_dialog_content = "점으로 그런 것도 알 수 있어?",
  ui_story_5038_50381201_32_dialog_content = "괘를 뽑아 천시를 따르려면 지금이 가장 좋은 때입니다.",
  ui_story_5038_50381201_33_dialog_content = "소생처럼 배움이 얕은 이라 해도, 편린을 보고 전체를 추측할 수 있는 것이지요.",
  ui_story_5038_50381201_34_dialog_content = "그럼 이 불초한 이천간이 하찮은 재주를 한번 부려 보겠습니다.",
  ui_story_5038_50381201_35_dialog_content = "<color=#e8d9bb>사사삭── 사사삭──</color>",
  ui_story_5038_50381201_36_dialog_content = "어떻게 됐어? 어떤 괘가 나왔지?",
  ui_story_5038_50381201_37_dialog_content = "하늘이 도우시어 제게 묘수를 내리셨습니다.",
  ui_story_5038_50381201_38_dialog_content = "「모든 것이 시작된 곳으로 돌아가면 진실이 밝혀질 것이니」.",
  ui_story_5038_50381201_39_dialog_content = "신풍호가 이러한 고난을 겪게 된 연유가 바로 이곳에 있었군요.",
  ui_story_5038_50381201_40_dialog_content = "종 대인, 이 괘가 가리키는 사람은 바로 대인입니다!",
  ui_story_5038_50381201_41_dialog_content = "읏챠...!",
  ui_story_5038_50381201_42_dialog_content = "PlayerName, 밧줄 하나 타고 올라오는 것도 내가 당겨줘야 된다니,\n진짜 안쓰러운 체력이네.",
  ui_story_5038_50381201_43_dialog_content = "참 죄송하게 됐네요! 누구나 다 밧줄을 잘 타는 건 아니거든!",
  ui_story_5038_50381201_44_dialog_content = "아무튼 올라오긴 했는데...",
  ui_story_5038_50381201_45_dialog_content = "왜 배에 아무도 없지?",
  ui_story_5038_50381201_46_dialog_content = "우릴 찾으러 다들 바다로 내려갔나?",
  ui_story_5038_50381201_47_dialog_content = "선창 쪽을 살펴보자. 안개를 피하려고 거기 있을 수도 있잖아.",
  ui_story_5038_50381201_48_dialog_content = "어? 선창 입구는 이쪽에 있었던 것 같은데...",
  ui_story_5038_50381201_49_dialog_content = "음, 올라오고 나서 방향을 바꿨나? 여긴...",
  ui_story_5038_50381201_50_dialog_content = "아니야.",
  ui_story_5038_50381201_51_dialog_content = "네?",
  ui_story_5038_50381201_52_dialog_content = "전부 다 아니야.",
  ui_story_5038_50381201_53_dialog_content = "돛대, 난간, 갑판까지...",
  ui_story_5038_50381201_54_dialog_content = "이 배는 신풍호가 아니야.",
  ui_story_5038_50381201_55_dialog_content = "?! 뒤를 조심해요!",
  ui_story_5038_50381201_56_dialog_content = "배에 암귀가 있어요...",
  ui_story_5038_50381201_57_dialog_content = "수도 꽤 많아.",
  ui_story_5038_50381201_58_dialog_content = "이런... 벌써 포위당했어요...",
  ui_story_5038_50381201_59_dialog_content = "월백 씨! 우선 왼쪽 녀석부터 처치하세요!",
  ui_story_5038_50381201_60_dialog_content = "응.",
  ui_story_5038_50381201_61_dialog_content = "당신은 이런 돌발 상황에 대처하는 데 익숙한 모양이구나.",
  ui_story_5038_50381201_62_dialog_content = "그럼요. 자다가 꿈에서까지 암귀가 나온다니까요.",
  ui_story_5038_50381201_63_dialog_content = "이제 신경 써야 할 건...",
  ui_story_5038_50381201_64_dialog_content = "이제 알겠어!",
  ui_story_5038_50381201_65_dialog_content = "응? 뭘?",
  ui_story_5038_50381201_66_dialog_content = "나 여기 알아! 와 본 적 있어!",
  ui_story_5038_50381201_67_dialog_content = "이 배가 바로 신풍호야! 그 원래 신풍호라구!",
  ui_story_5038_50381201_68_dialog_content = "뭐?!",
  ui_story_5038_50381201_69_dialog_content = "역시...",
  ui_story_5038_50381201_70_dialog_content = "이렇게 우연히... 옛 신풍호를 찾아냈다고?!",
  ui_story_5038_50381201_71_dialog_content = "그래, 확실해! 여기 이 난간을 부러트린 게 나였거든!",
  ui_story_5038_50381201_72_dialog_content = "좋았어! 드디어 찾았어!",
  ui_story_5038_50381201_73_dialog_content = "찾은 건 다행이긴 한데, 지금 이 상황을 좋다고 하긴 좀...",
  ui_story_5038_50381201_74_dialog_content = "「나침반」은 선창 안에 있어. 내가 어디 있는지 알아.",
  ui_story_5038_50381201_75_dialog_content = "얼른 따라와. 내가 안내해 줄게!",
  ui_story_5038_50381201_76_dialog_content = "야! 혼자 막 가면 어떡해! 안에 암귀가 있을 수도 있잖아!",
  ui_story_5038_50381201_77_dialog_content = "기다렸다 우리랑 같이...",
  ui_story_5038_50381201_78_dialog_content = "이런, 벌써 멀리도 갔네...",
  ui_story_5038_50381201_79_dialog_content = "뭐 하고 있어! 빨리 따라 와!",
  ui_story_5038_50381201_80_dialog_content = "당신 말을 들을 생각은 없어 보여.",
  ui_story_5038_50381201_81_dialog_content = "가자. 쫓아가야지.",
  ui_story_5038_50381201_82_dialog_content = "암귀 따위에 발목이 잡힐 내가 아니야.",
  ui_story_5038_50381202_1_dialog_content = "신풍호에게 일어난 사건들의 원흉이 종 공이라니?! 그게 무슨...",
  ui_story_5038_50381202_2_dialog_content = "그 점괘, 정말 믿을 만한 거야?",
  ui_story_5038_50381202_3_dialog_content = "허허, 이천간, 그대는 애당초 종 모를 노리고 온 것이로군.",
  ui_story_5038_50381202_4_dialog_content = "점괘도 아마 미리 준비해 둔 것이겠지.",
  ui_story_5038_50381202_5_dialog_content = "대인께서는 역시 명민하십니다.",
  ui_story_5038_50381202_6_dialog_content = "교룡어가 다시 모습을 드러냈을 때, 소생은 점을 쳐 보았습니다.",
  ui_story_5038_50381202_X6_dialog_content = "그때 나온 괘상은 입을 벌리고 있는 호랑이를 뜻하는 「음호」였습니다.",
  ui_story_5038_50381202_X7_dialog_content = "소생은 아무리 생각해 보아도 그 괘가 무엇을 가리키는지 알 수가 없었습니다.",
  ui_story_5038_50381202_X8_dialog_content = "그러다 갑자기 「장군이란 호랑이를 지닌 자」라는 옛말이 생각나더군요.",
  ui_story_5038_50381202_X9_dialog_content = "대인께서는 과거 대장군으로서 호부를 쥐고 천군을 호령하셨지요.\n그 괘가 시사하는 바에 대인보다 부합하는 이는 없습니다.",
  ui_story_5038_50381202_X10_dialog_content = "흥미롭군. 더 말해보게.",
  ui_story_5038_50381202_X11_dialog_content = "또한 대인의 존명에는 「나비」라는 뜻이 담겨 있습니다.",
  ui_story_5038_50381202_7_dialog_content = "어쩌면 대인께서 그때 하신 날갯짓이 오늘날의 이 폭풍을 몰고 온 것이 아니겠는지요.",
  ui_story_5038_50381202_8_dialog_content = "대인, 전에 옛 신풍호가 변을 당했을 때의 상황을 설명해 주셨던 것을 기억하십니까?",
  ui_story_5038_50381202_9_dialog_content = "당시 린 가문의 상선이 가문의 보물을 가지고 출항을 했으나,\n보물을 노린 무뢰배들에게 습격을 받았다고 하셨지요.",
  ui_story_5038_50381202_10_dialog_content = "허나 공교롭게도 살아남은 사람은 린 가문의 상객인 종 대인과 리청 단 둘뿐이었습니다.",
  ui_story_5038_50381202_11_dialog_content = "그렇다면 그날의 그 사건에서 두 분은 어떤 역할을 하셨던 것입니까?",
  ui_story_5038_50381202_12_dialog_content = "부디 대인께서 소생의 이런저런 의문을 풀어 주셨으면 합니다.",
  ui_story_5038_50381202_13_dialog_content = "책문하러 온 이가 그리 겸손할 필요가 있겠는가.",
  ui_story_5038_50381202_14_dialog_content = "단당 공주와 구를 함께 데려온 것은 이 종 모가 역정이라도 낼까 염려한 것인가?",
  ui_story_5038_50381202_15_dialog_content = "요, 용기를 북돋아 달라느니 운운한 이유를 이제야 알겠구나.",
  ui_story_5038_50381202_16_dialog_content = "종 대인께서는 두 다리가 불편하시지만, 기백은 여전하십니다.",
  ui_story_5038_50381202_17_dialog_content = "만일 소생 혼자서 찾아왔더라면, 위압감에 입도 열지 못했겠지요.",
  ui_story_5038_50381202_18_dialog_content = "좋소. 기왕 물어보았으니, 내 몇 마디 하리다.",
  ui_story_5038_50381202_19_dialog_content = "실은 종 모 역시 교룡어가 이 사람을 찾아온 것은 아닌지 의심하던 참이었소.",
  ui_story_5038_50381202_20_dialog_content = "어쩌면 저들의 이상한 행동이 종 모로 인한 것일 수도 있겠지.",
  ui_story_5038_50381202_21_dialog_content = "그게 무슨 말씀이신지?",
  ui_story_5038_50381202_22_dialog_content = "우선 옛 신풍호 이야기부터 해 보겠소.",
  ui_story_5038_50381202_23_dialog_content = "당시 린 가문의 상선이 가문의 보물을 가지고 출항을 했으나,\n보물을 노린 무뢰배들에게 습격을 받았다고 한 것은 한 치의 거짓도 없는 사실이오.",
  ui_story_5038_50381202_24_dialog_content = "허나 당시 종 모는 옛 신풍호에 타고 있던 것이 아니라, 그 무뢰배들을 뒤쫓고 있었소.",
  ui_story_5038_50381202_25_dialog_content = "뒤쫓다니요?",
  ui_story_5038_50381202_26_dialog_content = "린 가문의 가업을 지켜 주겠노라고 린 가문의 가주와 약조했기 때문이오.",
  ui_story_5038_50381202_27_dialog_content = "그 약조를 지키기 위해 종 모는 저들을 쫓았고, 그 뒤를 따라 옛 신풍호에 올랐소.",
  ui_story_5038_50381202_28_dialog_content = "본래는 나침반을 회수한 뒤, 조각배를 타고 용주로 돌아갈 심산이었지.",
  ui_story_5038_50381202_29_dialog_content = "허나 그날 밤의 상황은 이 사람의 생각보다 더 심각했소.",
  ui_story_5038_50381202_30_dialog_content = "무뢰배들은 옛 신풍호를 장악했으나, 「나침반」을 찾아내진 못하였소.",
  ui_story_5038_50381202_31_dialog_content = "이윽고 저들은 「나침반」의 행방을 알아내고자,\n수를 가리지 않고 린 가문의 선원들을 학대하기 시작했소.",
  ui_story_5038_50381202_32_dialog_content = "망망대해에는 법도 인의도 없다고들 하지.\n그 무뢰배들은 물을 만난 고기와도 같았소.",
  ui_story_5038_50381202_33_dialog_content = "이 종 모가 옛 신풍호에 당도하였을 때,\n변을 당하지 않은 린 가문의 자제는 단 한 명도 없었소.",
  ui_story_5038_50381202_34_dialog_content = "그제야 이 사람은 「나침반」만을 회수해 돌아가는 것만으로는\n아무런 소용도 없다는 것을 깨달았소.",
  ui_story_5038_50381202_35_dialog_content = "린 가문의 세가 약해진 이상, 「나침반」을 품고 있으면 화를 불러올 테니 말이오.",
  ui_story_5038_50381202_36_dialog_content = "진정으로 「나침반」을 지키는 유일한 방도는,\n「나침반」을 사라지게 만드는 것뿐이었소.",
  ui_story_5038_50381202_37_dialog_content = "사라지게 만들었다? 그걸 바다에 던져 버리기라도 하신 겁니까?",
  ui_story_5038_50381202_38_dialog_content = "「나침반」은 린 가문의 사업 기반이자, 가문 재건의 유일한 희망이오.\n내 어찌 그런 짓을 했겠소.",
  ui_story_5038_50381202_39_dialog_content = "이 종 모는 「나침반」을 반드시 지켜 내고,\n「나침반」이 다시는 세인들의 입에 오르내리지 않길 바랐소.",
  ui_story_5038_50381202_40_dialog_content = "입에 오르내리지 않길 바랐다...",
  ui_story_5038_50381202_41_dialog_content = "설마, 대인께선...!",
  ui_story_5038_50381202_42_dialog_content = "그렇소. 그 무뢰배 모두의 입을 막는 수밖에 없었소.",
  ui_story_5038_50381202_43_dialog_content = "내 지금까지 많은 전장을 겪어 왔으나, 그때처럼 마음이 갑갑한 전투는 없었소.",
  ui_story_5038_50381202_44_dialog_content = "그 무뢰배들은 애초에 전사라고 할 만한 자들도 아니었소.\n승기가 보이면 몰려들었다가, 패색이 짙어지면 무릎을 꿇고 목숨을 애걸했지.",
  ui_story_5038_50381202_45_dialog_content = "욕지거리를 퍼붓다가도, 울며 비명을 지르고... 절망에 빠지니 온갖 추태를 보였소.",
  ui_story_5038_50381202_46_dialog_content = "저들은 그저 목숨을 부지하고자 발버둥만 칠 뿐,\n이 종 모를 쓰러트리려는 자는 아무도 없었소.",
  ui_story_5038_50381202_47_dialog_content = "저들 중에는 성정이 고약하여 온갖 죄를 범한 이들도 있겠으나,\n삶이 어려워 저도 모르게 도적이 된 자도 있었을 것이오.",
  ui_story_5038_50381202_48_dialog_content = "허나 그때는 이를 구분할 여지가 없었기에, 전부 제거하는 수밖에 없었소.",
  ui_story_5038_50381202_49_dialog_content = "...「나침반」을 보호하기 위해서 말입니까?",
  ui_story_5038_50381202_50_dialog_content = "그렇소. 그렇게 자신을 설득하며 검을 휘둘렀소.",
  ui_story_5038_50381202_51_dialog_content = "허나 문득 스스로가 자제심을 잃었다는 느낌이 들더군.",
  ui_story_5038_50381202_52_dialog_content = "검에 피를 묻힌 순간부터, 이미 돌아올 수 없는 강을 건넌 것이었지만 말이오.",
  ui_story_5038_50381202_53_dialog_content = "그랬던 것이로군요...",
  ui_story_5038_50381202_54_dialog_content = "배가 폭풍을 만나 조난을 당했다는 이야기는, 이 종 모가 모두를 속인 것이 맞소.",
  ui_story_5038_50381202_55_dialog_content = "리청 아우와 바다에 떨어져 표류하게 된 연유는 사실 교룡어 무리의 습격 때문이었소.",
  ui_story_5038_50381202_56_dialog_content = "또 그 녀석들이었습니까?",
  ui_story_5038_50381202_57_dialog_content = "그래서 말하지 않았소. 교룡어가 이 사람을 따라오는 것 같다고 말이오.",
  ui_story_5038_50381202_58_dialog_content = "지금 이 신풍호에서 일어나고 있는 상황은 옛 신풍호에서 겪었던 것과 너무나도 닮았소.",
  ui_story_5038_50381202_59_dialog_content = "허나 이는 「나침반」을 찾는 일과는 관계가 없는 일이니,\n굳이 이 이야기를 꺼내고 싶진 않았던 것이오.",
  ui_story_5038_50381202_60_dialog_content = "오늘 기어코 이 일을 물었으니, 내 옛이야기를 들려준 셈이라 여기겠소.",
  ui_story_5038_50381202_61_dialog_content = "어느 누가 그런 이야기를 꺼내고 싶었겠습니까. 전부 소생의 실책입니다!",
  ui_story_5038_50381202_62_dialog_content = "되었소. 이러한 난국에선 모두가 일심으로 힘을 합쳐야 하는 법,\n이로써 불신의 싹을 없앨 수 있다면 그것으로 족하오.",
  ui_story_5038_50381202_63_dialog_content = "암요, 그렇지요. 모두가 한마음으로 힘을 합쳐야지요. 종 대인 말씀이 옳습니다.",
  ui_story_5038_50381202_64_dialog_content = "그럼 소생도 이 난국을 어찌 해결할지 좀 더 머리를 써 보겠습니다.",
  ui_story_5038_50381202_65_dialog_content = "안개가 이토록 짙게 끼었으니, 무엇을 하려 해도 여의치 않을 것이오.",
  ui_story_5038_50381202_66_dialog_content = "허나 리청 아우는 「나침반」을 찾는 일에 힘쓰고 있고,\n수요령으로서 영력도 적지 않게 가지고 있소.",
  ui_story_5038_50381202_67_dialog_content = "리청 아우가 직접 배를 타고 나가 찾겠다고 한 것이라면,\n진정 옛 신풍호가 이 근처에 있을지도 모르는 일이오.",
  ui_story_5038_50381202_68_dialog_content = "혹여 안개가 걷히고 나면 아우가 「나침반」을 가지고 돌아올 수도 있겠지.",
  ui_story_5038_50381202_69_dialog_content = "정말 일이 그렇게 순조롭게 해결된다면 여한이 없겠습니다만...",
  ui_story_5038_50381202_70_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5038_50381202_71_dialog_content = "무슨...",
  ui_story_5038_50381202_72_dialog_content = "<size=45><color=#e8d9bb>콰아아앙──!</color></size>",
  ui_story_5038_50381202_73_dialog_content = "꺄아악!",
  ui_story_5038_50381202_74_dialog_content = "갑자기 선체가 요동치다니, 이게 무슨 일입니까?!",
  ui_story_5038_50381202_75_dialog_content = "종 대인, 괜찮으십니까...?",
  ui_story_5038_50381202_76_dialog_content = "이 사람은 괜찮소. 어서 갑판 위로 올라가 보시오!",
  ui_story_5038_50381202_77_dialog_content = "예! 곧 돌아오겠습니다...",
  ui_story_5038_50381202_78_dialog_content = "<size=45>꺄아아아아아아!</size>",
  ui_story_5038_50381202_79_dialog_content = "무슨 일입니까?! 왜 또 비명을...",
  ui_story_5038_50381202_80_dialog_content = "배, 배가...",
  ui_story_5038_50381202_81_dialog_content = "<size=50>신풍호를 들이받았어요!</size>",
  ui_story_5038_50381301_1_dialog_content = "<color=#e8d9bb>콰아아앙──!</color>",
  ui_story_5038_50381301_2_dialog_content = "으아아앗, 뭐야?!",
  ui_story_5038_50381301_3_dialog_content = "뱃머리에 뭔가 충돌한 모양이야. 괜찮니?",
  ui_story_5038_50381301_4_dialog_content = "괘, 괜찮아요. 배가 흔들리는 것 정도는 이제 익숙해요...",
  ui_story_5038_50381301_5_dialog_content = "근데 충돌이라니... 뭐에 부딪힌 거죠? 암초일까요?",
  ui_story_5038_50381301_6_dialog_content = "빨리들 와. 바로 이 앞이야.",
  ui_story_5038_50381301_7_dialog_content = "음... 근데... 누구 혹시 문 딸 수 있는 사람?",
  ui_story_5038_50381301_8_dialog_content = "문이 잠겨 있는 것 같...",
  ui_story_5038_50381301_9_dialog_content = "내 검이 할 수 있어.",
  ui_story_5038_50381301_10_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5038_50381301_11_dialog_content = "으아아앗! 나까지 베어 버릴 뻔했잖아!",
  ui_story_5038_50381301_12_dialog_content = "안 들어갈 거야?",
  ui_story_5038_50381301_13_dialog_content = "흥...",
  ui_story_5038_50381301_14_dialog_content = "자, 따라와. 모두가 애타게 찾아다니던 보물을 내가 보여 줄 테니까.",
  ui_story_5038_50381301_15_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5038_50381301_16_dialog_content = "우와!",
  ui_story_5038_50381301_17_dialog_content = "엄청 정교하게 꾸며져 있네!",
  ui_story_5038_50381301_18_dialog_content = "요, 용주 부자들은 이렇게 꾸며 놓고 지내는구나!",
  ui_story_5038_50381301_19_dialog_content = "이 장식들...",
  ui_story_5038_50381301_20_dialog_content = "내가 기억하는 린 가문 저택과 팔 할 정도는 비슷해.",
  ui_story_5038_50381301_21_dialog_content = "가세가 기울고 나서 몇몇 골동품과 서화들을 이 배에 숨겨 뒀던 모양이네.",
  ui_story_5038_50381301_22_dialog_content = "린 가문 저택이요? 월백 씨가 거기 살았어요?",
  ui_story_5038_50381301_23_dialog_content = "어렸을 때 잠깐 거기 살았어.",
  ui_story_5038_50381301_24_dialog_content = "그러다 린 가문 상회가 몰락하면서 재산도 다 저당 잡히고,\n저택도 다른 사람 손에 넘어갔지.",
  ui_story_5038_50381301_25_dialog_content = "그 옛날 모습을 여기서 다시 보게 될 줄은 몰랐어.",
  ui_story_5038_50381301_26_dialog_content = "어린 시절을 보냈던 곳이라면 추억이 정말 많겠네요...",
  ui_story_5038_50381301_27_dialog_content = "이 얘기는 그만하자.",
  ui_story_5038_50381301_28_dialog_content = "리청, 이 보물들 중에 「나침반」은 어디...",
  ui_story_5038_50381301_29_dialog_content = "...이럴 리가 없는데, 이러면 안 되는데...",
  ui_story_5038_50381301_30_dialog_content = "어? 왜 그래?",
  ui_story_5038_50381301_31_dialog_content = "없어졌어. 어떻게 없어질 수가 있지...?",
  ui_story_5038_50381301_32_dialog_content = "없어졌다고?",
  ui_story_5038_50381301_33_dialog_content = "다른 곳에 숨겨둔 거 아닐까?",
  ui_story_5038_50381301_34_dialog_content = "그 「나침반」이 어떻게 생겼는지 설명해 줄래? 같이 찾아보자.",
  ui_story_5038_50381301_35_dialog_content = "하지만... 다른 곳에 숨길 데가 어디 있다고?",
  ui_story_5038_50381301_36_dialog_content = "이 어항에 둘 수밖에 없단 말이야...",
  ui_story_5038_50381301_37_dialog_content = "어항?",
  ui_story_5038_50381301_38_dialog_content = "잠깐만, 혹시 「나침반」이라는 게 내가 아는 나침판을 말하는 게 아니라...",
  ui_story_5038_50381301_39_dialog_content = "응, 「나침반」은 물고기야.",
  ui_story_5038_50381301_40_dialog_content = "뭐?!",
  ui_story_5038_50381301_41_dialog_content = "히힛.",
  ui_story_5038_50381301_42_dialog_content = "<color=#e8d9bb>쨍그랑!</color>",
  ui_story_5038_50381301_43_dialog_content = "<color=#e8d9bb>쨍그랑!</color>",
  ui_story_5038_50381301_44_dialog_content = "뭐, 뭐야?! 어디 뭐가 깨졌나?",
  ui_story_5038_50381301_45_dialog_content = "도자기가 깨지는 소리야. 그런데 어디인지는 안 보여...",
  ui_story_5038_50381301_46_dialog_content = "이런! 방금 누가 뛰쳐나갔어!",
  ui_story_5038_50381301_47_dialog_content = "누가?! 여기 우리 말고 누가 또 있었어?",
  ui_story_5038_50381301_48_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_5038_50381301_49_dialog_content = "어? 왜 문이 닫혔지?!",
  ui_story_5038_50381301_50_dialog_content = "밖에 있나 봐!",
  ui_story_5038_50381301_51_dialog_content = "그러니까 대체 누가...",
  ui_story_5038_50381301_52_dialog_content = "모...",
  ui_story_5038_50381301_53_dialog_content = "?!",
  ui_story_5038_50381301_54_dialog_content = "모. 두. 고. 마. 워.",
  ui_story_5038_50381301_55_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5038_50381301_56_dialog_content = "저건...",
  ui_story_5038_50381301_57_dialog_content = "도망쳐 버렸어! 빨리 쫓아가야 돼!",
  ui_story_5038_50381301_58_dialog_content = "이 문... 선장 누나, 아까처럼 열 수 있겠어?",
  ui_story_5038_50381301_59_dialog_content = "시도는 해 봤지만 안 열려. 반대편에서 무언가로 막아버린 것 같아.",
  ui_story_5038_50381301_60_dialog_content = "망했다! 큰일이야! 어떡하지! 빨리 쫓아가야 되는데!",
  ui_story_5038_50381301_61_dialog_content = "뭔가 방법이...",
  ui_story_5038_50381301_62_dialog_content = "아니면 우리 셋이 같이 문에 부딪혀 보자!",
  ui_story_5038_50381301_63_dialog_content = "우리 세 사람 힘으론 무리야.",
  ui_story_5038_50381301_64_dialog_content = "일단 진정해.",
  ui_story_5038_50381301_65_dialog_content = "상황이 이런데 어떻게 진정하라구! 이러다 도망가 버리면 어떡해!",
  ui_story_5038_50381301_66_dialog_content = "밖은 망망대해인데, 어딜 가서 다시 찾겠냐구...",
  ui_story_5038_50381301_67_dialog_content = "저기, 어쩌면 이 문을 열 수 있을 것 같아.",
  ui_story_5038_50381301_68_dialog_content = "뭐? 진짜?!",
  ui_story_5038_50381301_69_dialog_content = "응, 대신 시간이 좀 걸릴 거야.",
  ui_story_5038_50381301_70_dialog_content = "조금만 기다려 줘...",
  ui_story_5038_50381301_71_dialog_content = "(조금 말도 안 되는 방법이긴 하지만...)",
  ui_story_5038_50381301_72_dialog_content = "(한번 해 보는 수밖에!)",
  ui_story_5038_50381301_73_option_content = "(강제 감응!)",
  ui_story_5038_50381301_74_dialog_content = "갑자기 가만히 있는 걸 보니 그 능력을 쓰고 있는 모양이네.",
  ui_story_5038_50381301_X74_dialog_content = "기다리는 동안 넌 「나침반」 얘기부터 해 봐. 대체 어떻게 된 거야?",
  ui_story_5038_50381301_75_dialog_content = "방금 도망친 사람은 또 누구야?",
  ui_story_5038_50381301_76_dialog_content = "음... 어디서부터 말을 해야 되나...",
  ui_story_5038_50381301_77_dialog_content = "사실 나도 아까 그 모습은 처음 봤어.",
  ui_story_5038_50381301_78_dialog_content = "하지만 이 방에 있다는 건 한 가지 가능성밖에 없어.",
  ui_story_5038_50381301_79_dialog_content = "저 애가 바로 「나침반」이야.",
  ui_story_5038_50381301_80_dialog_content = "저 사람이 「나침반」이라고?!",
  ui_story_5038_50381301_81_dialog_content = "처음에는 「나침반」이 물고기라고 했다가, 이제는 사람이라니?\n대체 뭐가 어떻게 된 거야?",
  ui_story_5038_50381301_82_dialog_content = "「나침반」은 확실히 물고기야. 그것도 아주 특별한 교룡어였어.",
  ui_story_5038_50381301_83_dialog_content = "물고기라고 항상 물고기 모습만 하고 있을 필요는 없잖아?",
  ui_story_5038_50381301_84_dialog_content = "내가 고양이였다는 거 잊었어?",
  ui_story_5038_50381301_85_dialog_content = "그러니까... 아까 그 사람도 수요령이란 거야?",
  ui_story_5038_50381301_86_dialog_content = "응, 그것 말고는 말이 안 돼.",
  ui_story_5038_50381301_87_dialog_content = "옛 신풍호가 바다에서 표류하는 동안, 녀석은 물고기에서 수요령이 됐을 거야.",
  ui_story_5038_50381301_88_dialog_content = "새로운 힘을 얻어서 물의 속박에서 벗어났으니까,\n더는 어항 안에만 있을 필요가 없어진 거겠지.",
  ui_story_5038_50381301_89_dialog_content = "하지만 이 선창의 문이 잠겨 있어서 밖으로는 못 나오고 있었던 거고.",
  ui_story_5038_50381301_90_dialog_content = "근데 우리가 지금 그 문을 열고 들어와 버린 거야...",
  ui_story_5038_50381301_91_dialog_content = "...그렇구나.",
  ui_story_5038_50381301_92_dialog_content = "「나침반」이 물고기였다니...\n그런데 물고기가 어떻게 항로를 인도할 수 있었던 거야?",
  ui_story_5038_50381301_93_dialog_content = "선장 누나도 린 가문 사람이니까, 린 가문의 신물에 대해 잘 알 거라고 생각해.",
  ui_story_5038_50381301_94_dialog_content = "교룡어는 무리 중의 개체를 위해 집단행동을 하는 녀석들이잖아?",
  ui_story_5038_50381301_95_dialog_content = "「나침반」은 그 교룡어 무리의 대장이야.",
  ui_story_5038_50381301_96_dialog_content = "대장?!",
  ui_story_5038_50381301_97_dialog_content = "어쩐지... 교룡어들이 비정상적으로 이 해역을 맴돌던 이유가 있었어.",
  ui_story_5038_50381301_98_dialog_content = "교룡어가 근처에 있다고 종 대인과 네가 판단했던 이유도 그래서였겠지.",
  ui_story_5038_50381301_99_dialog_content = "응, 맞아.",
  ui_story_5038_50381301_100_dialog_content = "잠깐, 왠지 알 것 같아...",
  ui_story_5038_50381301_101_dialog_content = "교룡어는 두 대륙 사이를 오가는 방법을 알고 있어.",
  ui_story_5038_50381301_102_dialog_content = "그리고 옛 신풍호는 이 점에 착안해서, 교룡어들의 대장을 조종했던 거겠지.",
  ui_story_5038_50381301_103_dialog_content = "그렇게 해서 교룡어 무리 전체가 선박의 대양 횡단을 돕게 만든 거였어...",
  ui_story_5038_50381301_104_dialog_content = "맞아, 그 말 그대로야.",
  ui_story_5038_50381301_105_dialog_content = "린 가문은 아주 오랫동안 교룡어의 대장을 배에 가둬 뒀어.",
  ui_story_5038_50381301_106_dialog_content = "그렇게 몇 대가 지나고, 교룡어들은 옛 신풍호 그 자체를 자기들 대장이라고 여기게 됐어.",
  ui_story_5038_50381301_107_dialog_content = "항해에 나설 때마다, 교룡어 무리가 몰려와서 배를 밀어줬어.",
  ui_story_5038_50381301_108_dialog_content = "그래서 린 가문은 항로를 이탈할 걱정도, 풍랑에 발이 묶일 걱정도 할 필요가 없었던 거지.",
  ui_story_5038_50381301_109_dialog_content = "어차피 교룡어들이 목적지까지 데려다 줄 테니까.",
  ui_story_5038_50381301_110_dialog_content = "...그럼 왜 지금껏 아무도 내게 이 사실을 말하지 않았던 거지?",
  ui_story_5038_50381301_111_dialog_content = "린 가문 사람들, 종 대인, 그리고 너까지도.",
  ui_story_5038_50381301_112_dialog_content = "으, 그건 종서 형님이 전에 말씀해 주신 적 있는데,\n난 무슨 얘긴지 이해가 잘 안 되더라구.",
  ui_story_5038_50381301_113_dialog_content = "「전가의 보물은 드러내지 않는 법」? 「린 가문의 명예를 위해」?\n뭐 그런 복잡한 이유였던 것 같아.",
  ui_story_5038_50381301_114_dialog_content = "그러니 침묵을 지키는 편이 가장 좋은 선택이었던 거야.",
  ui_story_5038_50381301_115_dialog_content = "......",
  ui_story_5038_50381301_116_dialog_content = "그래 놓고 난 왜 「나침반」을 찾겠다고 유난을 떨었냐면...\n양심의 가책 때문이었어.",
  ui_story_5038_50381301_117_dialog_content = "옛 신풍호에 탄 그날부터 나도 저 애를 부려 먹는 사람들이랑 공범이 된 거잖아.",
  ui_story_5038_50381301_118_dialog_content = "바다 날씨는 항상 변덕스러우니까,\n비열한 짓이란 걸 알면서도 저 애한테 의지하는 수밖에 없었어.",
  ui_story_5038_50381301_119_dialog_content = "저 녀석을 계속 「나침반」이라고 부른 건 마음이라도 조금 편하려고 그랬던 거고.",
  ui_story_5038_50381301_120_dialog_content = "양심의 가책...",
  ui_story_5038_50381301_121_dialog_content = "그런 감정을 느꼈다는 것만으로도 이미 훌륭한 마음가짐이야.",
  ui_story_5038_50381301_122_dialog_content = "어쩌면 난 저 애를 계속 친구라고 생각해서 그런 마음이 든 걸지도 몰라.",
  ui_story_5038_50381301_123_dialog_content = "참! 이름도 있어. 「우룡」이라고 해.",
  ui_story_5038_50381301_124_dialog_content = "우룡. 알겠어, 기억해 둘게.",
  ui_story_5038_50381301_125_dialog_content = "저기, 대화에 끼어들어서 미안한데...",
  ui_story_5038_50381301_126_dialog_content = "문 여는 데 성공한 것 같아요.",
  ui_story_5038_50381301_127_dialog_content = "진짜? 그럼 이제 밖으로 나갈 수 있어?!",
  ui_story_5038_50381301_128_dialog_content = "응, 이제 곧 열릴 거야.",
  ui_story_5038_50381301_129_dialog_content = "이야! 꽤 하잖아!",
  ui_story_5038_50381301_130_dialog_content = "대신 둘 다 준비해야 돼요.",
  ui_story_5038_50381301_131_dialog_content = "준비? 무슨 뜻이야?",
  ui_story_5038_50381301_132_dialog_content = "왔어요!",
  ui_story_5038_50381301_133_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5038_50381301_134_dialog_content = "크오오!",
  ui_story_5038_50381301_135_dialog_content = "으아악! 깜짝 놀랐잖아!",
  ui_story_5038_50381301_136_dialog_content = "암귀가 여긴 어떻게 온 거야...?",
  ui_story_5038_50381301_137_dialog_content = "잠깐만, 설마 문 여는 방법이 이거였던 건 아니지?",
  ui_story_5038_50381301_138_dialog_content = "암귀들로 문을 부수려던 거야?",
  ui_story_5038_50381301_139_dialog_content = "음... 좀 거칠긴 했지만 효과는 있었잖아?",
  ui_story_5038_50381301_140_dialog_content = "나쁘지 않았어. 이 문보다는 암귀 쪽이 상대하기 수월하니까.",
  ui_story_5038_50381301_141_dialog_content = "어서 해치우자!",
  ui_story_5038_50381302_1_dialog_content = "무, 무슨 일입니까? 대체 뭡니까?!",
  ui_story_5038_50381302_2_dialog_content = "암귀가 갑판으로 올라왔어요!",
  ui_story_5038_50381302_3_dialog_content = "저 뒤에 있는 배에서 넘어온 거예요!",
  ui_story_5038_50381302_4_dialog_content = "캬악──!",
  ui_story_5038_50381302_5_dialog_content = "지저분한 것들! 물러나라!",
  ui_story_5038_50381302_6_dialog_content = "그어어...",
  ui_story_5038_50381302_7_dialog_content = "수가 이렇게 많다니...",
  ui_story_5038_50381302_8_dialog_content = "전하, 물러나 주십시오.",
  ui_story_5038_50381302_9_dialog_content = "거친 일은 이 구에게 맡기시면 됩니다.",
  ui_story_5038_50381302_10_dialog_content = "모두 선미로 모이시오!",
  ui_story_5038_50381302_11_dialog_content = "암귀들이 날뛰지 못하도록 막아 내야 하오!",
  ui_story_5038_50381302_12_dialog_content = "예!",
  ui_story_5038_50381302_13_dialog_content = "종 공, 이게 어찌 된 일인가요?",
  ui_story_5038_50381302_14_dialog_content = "암귀를 가득 태운 배가 충돌해 오다니...",
  ui_story_5038_50381302_15_dialog_content = "저 거대한 배는...",
  ui_story_5038_50381302_16_dialog_content = "안개가 짙어 확실치는 않으나, 우연히 풍랑에 떠밀려 온 것일지도 모르오.",
  ui_story_5038_50381302_17_dialog_content = "이런! 녀석들이 돛대를 부수고 있다!",
  ui_story_5038_50381302_18_dialog_content = "조심해요! 갑판도 잔뜩 부서졌어요!",
  ui_story_5038_50381302_19_dialog_content = "아이고오! 이러다 큰일 나겠습니다! 이걸 어쩝니까!",
  ui_story_5038_50381302_20_dialog_content = "가증스러운 놈들!",
  ui_story_5038_50381302_21_dialog_content = "구! 어서 도우러 가자!",
  ui_story_5038_50381302_22_dialog_content = "잠깐 기다리시오.",
  ui_story_5038_50381302_23_dialog_content = "네?",
  ui_story_5038_50381302_24_dialog_content = "계속 신풍호에서 전투를 치른다면, 선체가 입는 피해만 커질 뿐이오.",
  ui_story_5038_50381302_25_dialog_content = "반드시 전장을 다른 곳으로 옮겨야만 하오.",
  ui_story_5038_50381302_26_dialog_content = "전장을 옮긴다? 그 말씀은...",
  ui_story_5038_50381302_27_dialog_content = "나무판자를 가져와 맞은편 배로 건너갈 수 있는 다리를 만드는 것이오.",
  ui_story_5038_50381302_28_dialog_content = "불태울 것은 이 배가 아닌 저 배이니 말이오.",
  ui_story_5038_50381401_1_dialog_content = "종 공께서는 거동이 불편하니 이 신풍호에 남아 있도록 하세요.",
  ui_story_5038_50381401_2_dialog_content = "이쪽은 저희가 있으니 충분히 암귀들을 상대할 수 있어요.",
  ui_story_5038_50381401_3_dialog_content = "맞습니다. 다치시기라도 한다면 큰일입니다.",
  ui_story_5038_50381401_4_dialog_content = "염려치 마시오.",
  ui_story_5038_50381401_5_dialog_content = "종 모는 모두에게 누가 되지 않으리라는 판단이 있었기에 함께 온 것이오.",
  ui_story_5038_50381401_6_dialog_content = "(틀림없군. 이 배는 옛 신풍호다.)",
  ui_story_5038_50381401_7_dialog_content = "(「나침반」도 이 근처에 있을 터, 반드시 되찾아야 한다.)",
  ui_story_5038_50381401_8_dialog_content = "(린 형, 내 결코 식언은 하지 않을 것이오.)",
  ui_story_5038_50381401_9_dialog_content = "전하, 암귀들이 다가오고 있습니다.",
  ui_story_5038_50381401_10_dialog_content = "게다가 그 수도 신풍호 쪽보다 훨씬 많습니다.",
  ui_story_5038_50381401_11_dialog_content = "오히려 잘 됐어. 이 자리에서 암귀들을 모조리...",
  ui_story_5038_50381401_12_dialog_content = "조급해할 것 없소. 우선 몇 걸음 물러나 주시오.",
  ui_story_5038_50381401_13_dialog_content = "곁에 있으면 다칠 것이오.",
  ui_story_5038_50381401_14_dialog_content = "네? 종 공, 그게 무슨...",
  ui_story_5038_50381401_15_dialog_content = "<size=50>염화분진, 제악단멸!</size>",
  ui_story_5038_50381401_16_dialog_content = "전하! 조심하십시오!",
  ui_story_5038_50381401_17_dialog_content = "캬아아아아악!",
  ui_story_5038_50381401_18_dialog_content = "저, 정말 거대한 불꽃이네!",
  ui_story_5038_50381401_19_dialog_content = "주변의 암귀들이 모조리 불길에 휩싸여 버렸어...",
  ui_story_5038_50381401_20_dialog_content = "게다가 안개까지 걷히고 있어!",
  ui_story_5038_50381401_21_dialog_content = "종 대인께서 함께 이 배에 오겠다고 고집하신 이유가 있었군요.",
  ui_story_5038_50381401_22_dialog_content = "이 정도의 위력을 지닌 기술을... 신풍호에서 펼쳤다간 무슨 탈이 있을지 모르니까요.",
  ui_story_5038_50381401_23_dialog_content = "이 낡은 배는 오랜 시간 바다를 표류하며, 파도와 바람을 견뎌 왔소.",
  ui_story_5038_50381401_24_dialog_content = "배의 뼈대는 이미 썩어 문드러졌고, 남은 것이라곤 앙상한 선체뿐이지.",
  ui_story_5038_50381401_25_dialog_content = "그러니 불을 살짝 더하면 자연스레 타오르게 되는 것이오.",
  ui_story_5038_50381401_26_dialog_content = "정말 잘됐네요! 종 공의 불꽃 덕분에 빠르게 암귀를 소탕할 수 있었어요!",
  ui_story_5038_50381401_27_dialog_content = "이제 신풍호로 돌아가 선원들을 도와야 해요.",
  ui_story_5038_50381401_28_dialog_content = "전하, 조심하십시오. 불꽃이 갑판을 불태워 무너질 위험이 있습니다.",
  ui_story_5038_50381401_29_dialog_content = "아, 그것도 그렇구나...",
  ui_story_5038_50381401_30_dialog_content = "구, 우리 서로 붙잡고 건너는 게 좋겠어.",
  ui_story_5038_50381401_31_dialog_content = "그래야 하나가 발을 헛디뎌도, 다른 하나가 잡아 줄 수 있잖니.",
  ui_story_5038_50381401_32_dialog_content = "서로를...",
  ui_story_5038_50381401_33_dialog_content = "예, 전하의 말씀대로 하겠습니다.",
  ui_story_5038_50381401_34_dialog_content = "자, 소생이 두 분을 위해 길을 터 드리지요!",
  ui_story_5038_50381401_35_dialog_content = "잠깐, 이 배를 조금 더 돌아보는 것은 어떻겠소?",
  ui_story_5038_50381401_36_dialog_content = "이 종 모는 암귀를 멸하는 일 외에도 아직 하려는 일이 남아 있소.",
  ui_story_5038_50381401_37_dialog_content = "네? 꼭 이 배에서 해야 하는 일인가요?",
  ui_story_5038_50381401_38_dialog_content = "내가 잘못 본 것이 아니라면, 이 배가 바로 옛 신풍호요.",
  ui_story_5038_50381401_39_dialog_content = "이 배는 종 모와 인연이 조금 있소.",
  ui_story_5038_50381401_40_dialog_content = "아, 그럼 이 배가 바로 사고를 당했던 그 배인 거군요...",
  ui_story_5038_50381401_41_dialog_content = "물건 하나가 아직 이곳에 남아 있소.",
  ui_story_5038_50381401_42_dialog_content = "종 모는 이 배가 잿더미로 변하기 전에 그 물건을 회수해 가고자 하오.",
  ui_story_5038_50381401_43_dialog_content = "무척 중요한 물건인가요?",
  ui_story_5038_50381401_44_dialog_content = "그렇소. 우리가 용주로 돌아가는 것을 도와줄 물건이오.",
  ui_story_5038_50381401_45_dialog_content = "(오랫동안 돌보는 이가 없었으니, 「나침반」이 무탈할지 모르겠군.)",
  ui_story_5038_50381401_46_dialog_content = "(아아, 돌이켜 보면 실로 우스운 일이 아닌가.)",
  ui_story_5038_50381401_47_dialog_content = "(드넓은 두 대륙 사이를 잇는 유대의 존망이 물고기 한 마리에게 달려 있다니.)",
  ui_story_5038_50381401_48_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5038_50381401_49_dialog_content = "으음?",
  ui_story_5038_50381401_50_dialog_content = "잠깐만요, 무슨 소리가 들리는 것 같은데요?",
  ui_story_5038_50381401_51_dialog_content = "어디 또 암귀가 숨어 있는 건가?",
  ui_story_5038_50381401_52_dialog_content = "아닙니다, 전하. 이 소리는...",
  ui_story_5038_50381401_53_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅...</color>",
  ui_story_5038_50381401_54_dialog_content = "사람 발소리입니다.",
  ui_story_5038_50381401_55_dialog_content = "발소리?! 우리 말고 다른 사람이 또 있는 거야?",
  ui_story_5038_50381401_56_dialog_content = "당신, 이구나.",
  ui_story_5038_50381401_57_dialog_content = "!!!",
  ui_story_5038_50381401_58_dialog_content = "이건 사람 목소리 아닙니까?! 대체 누가 여기에...",
  ui_story_5038_50381401_59_dialog_content = "누구냐! 어서 밖으로...",
  ui_story_5038_50381401_60_dialog_content = "「속(束)」.",
  ui_story_5038_50381401_61_dialog_content = "으악──!",
  ui_story_5038_50381401_62_dialog_content = "전하! 제가 잡았습니다!",
  ui_story_5038_50381401_63_dialog_content = "저, 저기 좀 봐!",
  ui_story_5038_50381401_64_dialog_content = "종 공, 저자는...",
  ui_story_5038_50381401_65_dialog_content = "윽...",
  ui_story_5038_50381401_66_dialog_content = "누구냐.",
  ui_story_5038_50381401_67_dialog_content = "나, 당신, 알아.",
  ui_story_5038_50381401_68_dialog_content = "허나 나는 너를 본 적이...",
  ui_story_5038_50381401_69_dialog_content = "잠깐... 그 꼬리!",
  ui_story_5038_50381401_70_dialog_content = "당신, 배에, 있었어.",
  ui_story_5038_50381401_71_dialog_content = "교룡어의 꼬리로구나.",
  ui_story_5038_50381401_72_dialog_content = "교룡어의 꼬리는 린 가문 사람들의 특징이거늘... 린 가문 사람인 것이냐?",
  ui_story_5038_50381401_73_dialog_content = "당신. 린. 가문. 도왔어.",
  ui_story_5038_50381401_74_dialog_content = "아니, 네가 린 가문의 사람일 리 없다.",
  ui_story_5038_50381401_75_dialog_content = "그 사건이 일어난 날, 이 배에 산 자는 하나도 남지 않았다.",
  ui_story_5038_50381401_76_dialog_content = "이곳에 나타날 수 있는 것은, 오직 린 가문의 물건뿐일 터.",
  ui_story_5038_50381401_77_dialog_content = "당신, 이름.",
  ui_story_5038_50381401_78_dialog_content = "종, 서.",
  ui_story_5038_50381401_79_dialog_content = "네가 바로 그 물건인 모양이로구나.",
  ui_story_5038_50381401_80_dialog_content = "린 가문의 가장 귀중한 보물.",
  ui_story_5038_50381401_81_dialog_content = "「우룡」 말이다.",
  ui_story_5038_50381401_82_dialog_content = "종 대인! 저 아이는 또 어디서 나타난 겁니까! 괜찮으십니까?!",
  ui_story_5038_50381401_83_dialog_content = "조심하십시오. 저자는 강합니다.",
  ui_story_5038_50381401_84_dialog_content = "저런 어린 소년이 어째서...",
  ui_story_5038_50381401_85_dialog_content = "혹, 혹시 수요령인가?!",
  ui_story_5038_50381401_86_dialog_content = "그런 모습으로 변할 줄이야...",
  ui_story_5038_50381401_87_dialog_content = "어찌 나를 공격한 것이냐.",
  ui_story_5038_50381401_88_dialog_content = "린, 가문, 죽어, 마땅해.",
  ui_story_5038_50381401_89_dialog_content = "...역시, 그들을 증오하고 있었느냐.",
  ui_story_5038_50381401_90_dialog_content = "저들이 널 가두어 두었기 때문이겠지.",
  ui_story_5038_50381401_91_dialog_content = "배에, 탄, 사람, 모두.",
  ui_story_5038_50381401_92_dialog_content = "죽어, 마땅해.",
  ui_story_5038_50381401_93_dialog_content = "나와 린 가문은 오래전부터 네가 증오를 품으리라 예견했다.",
  ui_story_5038_50381401_94_dialog_content = "허나 그 증오를 직접 마주할 날이 올 줄은 몰랐지.",
  ui_story_5038_50381401_95_dialog_content = "배, 가장, 죽어, 마땅해.",
  ui_story_5038_50381401_96_dialog_content = "마음껏 증오하거라. 네게는 그리할 권리가 있다.",
  ui_story_5038_50381401_97_dialog_content = "선대의 유산은 후대가 받고, 선대의 빚은 후대가 갚아 마땅하다.",
  ui_story_5038_50381401_98_dialog_content = "헌데 다소 불운한 아무개는 둘 사이에 낀 신세로구나.",
  ui_story_5038_50381401_99_dialog_content = "린 형. 이 종 모가 거듭 큰 도움을 드리게 되었소이다.",
  ui_story_5038_50381401_100_dialog_content = "너희, 모두.",
  ui_story_5038_50381401_101_dialog_content = "바다의, 적.",
  ui_story_5038_50381401_102_dialog_content = "너희, 그리고, 배.",
  ui_story_5038_50381401_103_dialog_content = "바다에, 가라, 앉아.",
  ui_story_5038_50381401_104_dialog_content = "으악! 발밑이...",
  ui_story_5038_50381401_105_dialog_content = "멈춰! 우룡!",
  ui_story_5038_50381401_106_dialog_content = "응? 리, 리청 목소리야!",
  ui_story_5038_50381401_107_dialog_content = "허억, 헉... 드디어 따라잡았네!",
  ui_story_5038_50381401_108_dialog_content = "리, 청...",
  ui_story_5038_50381401_109_dialog_content = "「나침반」이라는 건 이렇게 생긴 것이었구나.",
  ui_story_5038_50381401_110_dialog_content = "어? 왜 다 여기 있어요? 무슨 일 있었어요?",
  ui_story_5038_50381401_111_dialog_content = "여기들 계셨군요!",
  ui_story_5038_50381401_112_dialog_content = "무슨 일이 있었던 겁니까? 저 아이는 또 누굽니까?",
  ui_story_5038_50381401_113_dialog_content = "저 아이가 바로 우리가 계속 찾아다니던 「나침반」이에요.",
  ui_story_5038_50381401_114_dialog_content = "「나침반」?!",
  ui_story_5038_50381401_115_dialog_content = "하늘의 뜻은 인간이 헤아릴 수 없다고는 해도...\n어째서 소생의 점괘가 빗나간 것인지...",
  ui_story_5038_50381401_116_dialog_content = "...아, 아니지! 그 점괘들!",
  ui_story_5038_50381401_117_dialog_content = "그 괘라는 것이 얼마나 기이한지, 각각 갈팡질팡하는 쥐를 뜻하는 「수서양단」,\n분수를 모르고 날뛰다 물에 빠진 원숭이를 뜻하는 「원후취월」,\n꾀가 많아 굴을 세 개 파 놓는 토끼를 뜻하는 「교토삼굴」이었지 뭡니까.",
  ui_story_5038_50381401_118_dialog_content = "이른바 가짜를 진짜라 여기는 순간, 진짜는 가짜가 되는 것 아니겠습니까.\n그러니 적당한 <color=#FFB400>대체품</color>을 찾아야 한다는 것이지요.",
  ui_story_5038_50381401_119_dialog_content = "알았습니다! 그 진짜 의미를 이제야 알겠습니다!",
  ui_story_5038_50381401_120_dialog_content = "네? 뭐가요?",
  ui_story_5038_50381401_121_dialog_content = "그 세 괘는 이번 여정의 시작과 끝을 예언했던 것입니다!",
  ui_story_5038_50381401_122_dialog_content = "첫 번째 괘인 「수서양단」은 목 선장님이 「나침반」을 찾으며 「갈팡질팡」하는 모습...",
  ui_story_5038_50381401_123_dialog_content = "세 번째 괘인 「교토삼굴」은 「정체」와 「용도」,\n그리고 「소재지」가 불명확했던 「나침반」을...",
  ui_story_5038_50381401_124_dialog_content = "그리고 두 번째 괘인 「원후취월」은 두 괘의 내용을 잇는 과정이었던 것이지요.",
  ui_story_5038_50381401_125_dialog_content = "가서는 아니 될 길을 가고, 해서는 아니 될 일을 해야,\n비로소 시작에서 끝에 이를 수 있는 법...",
  ui_story_5038_50381401_126_dialog_content = "그리고 이 세 괘가 가리키는 진정한 대체품은 선박의 부품이 아니었습니다...",
  ui_story_5038_50381401_127_dialog_content = "새로운 신풍호 그 자체였던 겁니다!",
  ui_story_5038_50381401_128_dialog_content = "우룡! 지금 뭐 하는 거야?!",
  ui_story_5038_50381401_129_dialog_content = "종서 형님을 해칠 생각이야?",
  ui_story_5038_50381401_130_dialog_content = "......",
  ui_story_5038_50381401_131_dialog_content = "그뿐만이 아니다. 저 아이는 신풍호까지 가라앉힐 생각이다.",
  ui_story_5038_50381401_132_dialog_content = "왜 그러는 거야...?",
  ui_story_5038_50381401_133_dialog_content = "네가 그 작은 어항에 갇혀서 분하고 답답했을 거 나도 알아.",
  ui_story_5038_50381401_134_dialog_content = "네가 가졌을 불만과 분노, 심지어 증오도 이해할 수 있어.",
  ui_story_5038_50381401_135_dialog_content = "그치만 모든 사람이 다 똑같진 않아! 널 해치려는 사람만 있는 건 아니라구.",
  ui_story_5038_50381401_136_dialog_content = "나쁜 사람들의 죗값을 무고한 사람들이 치르게 하면 안 되는 거잖아!",
  ui_story_5038_50381401_137_dialog_content = "넌, 나오지, 말았어야, 해.",
  ui_story_5038_50381401_138_dialog_content = "어째서?",
  ui_story_5038_50381401_139_dialog_content = "나오면, 죽으, 니까.",
  ui_story_5038_50381401_140_dialog_content = "<color=#e8d9bb>콰지직──!</color>",
  ui_story_5038_50381401_141_dialog_content = "으아아악! 갑판이 갈라지고 있잖아!",
  ui_story_5038_50381401_142_dialog_content = "그만해, 우룡! 진짜 이래야겠어?!",
  ui_story_5038_50381401_143_dialog_content = "여기 있는 사람들은 아무 잘못도 없어! 특히 난 더더욱 그렇고!",
  ui_story_5038_50381401_144_dialog_content = "내가 맨날 너 밥도 챙겨 줬었는데, 기억 안 나?!",
  ui_story_5038_50381401_145_dialog_content = "<color=#e8d9bb>콰지직──!</color>",
  ui_story_5038_50381401_146_dialog_content = "너 진짜!",
  ui_story_5038_50381401_X146_dialog_content = "지금은 그 누구의 말도 듣지 않을 것이다.\n허나 계속 날뛰게 둔다면 모두가 목숨을 잃고 말겠지.",
  ui_story_5038_50381401_X147_dialog_content = "일단 저 아이를 막을 방법부터 찾아야 한다.",
  ui_story_5038_50381401_147_dialog_content = "부질없는 일이다. 저 아이가 아우에게 호의를 가지고 있다 한들,\n그것이 뿌리 깊은 증오를 희석하진 못한다.",
  ui_story_5038_50381401_148_dialog_content = "고작 그 알량한 기대로 모두의 목숨을 위태롭게 만들 셈이냐?",
  ui_story_5038_50381401_149_dialog_content = "하지만...",
  ui_story_5038_50381401_150_dialog_content = "신풍호가 가만히 앉아서 당하고 있을 것 같아?",
  ui_story_5038_50381401_151_dialog_content = "누구 마음대로 신풍호에 행패를 부리겠다는 거야?",
  ui_story_5038_50381401_152_dialog_content = "그래! 이 신풍호에 손을 대는 건 절대 용납할 수 없어!",
  ui_story_5038_50381401_153_dialog_content = "하아... 어린아이에게 손을 쓰는 건 도의가 아닌 듯하나...",
  ui_story_5038_50381401_154_dialog_content = "저자는 수요령입니다. 겉모습은 앳되어도, 실제로는 당신 조부뻘일지도 모르지요.",
  ui_story_5038_50381401_155_dialog_content = "공격하려는 것 같아요!",
  ui_story_5038_50381401_156_dialog_content = "모두 준비해 주세요!",
  ui_story_5038_50381402_1_dialog_content = "저리, 비켜.",
  ui_story_5038_50381402_2_dialog_content = "힘이 많이 약해졌어요!",
  ui_story_5038_50381402_3_dialog_content = "이젠 공격하는 것도 버거워 보여요!",
  ui_story_5038_50381402_4_dialog_content = "음, 수요령이 된 지 얼마 되지 않아 아직 힘을 다루는 법을 잘 모르는 것이겠지.",
  ui_story_5038_50381402_5_dialog_content = "목표 없이 막무가내로 공격하다 보니 오히려 힘이 빠르게 소진된 것 같소.",
  ui_story_5038_50381402_6_dialog_content = "궁지에 몰리면 발악을 할 거예요. 지금 당장 녀석을 붙잡아야 해요.",
  ui_story_5038_50381402_7_dialog_content = "응! 나도 도울게!",
  ui_story_5038_50381402_8_dialog_content = "가라, 앉아.",
  ui_story_5038_50381402_9_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5038_50381402_10_dialog_content = "이, 이번엔 배를 공격하고 있어요!",
  ui_story_5038_50381402_11_dialog_content = "그리고 잘못 본 게 아니라면... 지금 교룡어들이 잔뜩 몰려오고 있어요!",
  ui_story_5038_50381402_12_dialog_content = "리청, 어서 해.",
  ui_story_5038_50381402_13_dialog_content = "알고 있다구!",
  ui_story_5038_50381402_14_dialog_content = "우룡, 친구였던 우리가 이런 모습이 될 줄은 몰랐어.",
  ui_story_5038_50381402_15_dialog_content = "리, 청...",
  ui_story_5038_50381402_16_dialog_content = "너도 사람 말을 배웠구나.",
  ui_story_5038_50381402_17_dialog_content = "나를, 막지, 마.",
  ui_story_5038_50381402_18_dialog_content = "근데 서로 이야기를 나눌 기회가 없었던 게 너무 아쉬워.",
  ui_story_5038_50381402_19_dialog_content = "저리, 비켜.",
  ui_story_5038_50381402_20_dialog_content = "어허! 수요령으로선 내가 그래도 선배거든!",
  ui_story_5038_50381402_21_dialog_content = "넌 아직 갈 길이 멀어!",
  ui_story_5038_50381402_22_dialog_content = "선배로서 더 많은 걸 가르쳐 주고 싶지만...",
  ui_story_5038_50381402_23_dialog_content = "일단은 널 쓰러트리는 게 먼저야!",
  ui_story_5038_50381402_24_dialog_content = "(월백 씨! 지금이에요!)",
  ui_story_5038_50381402_25_dialog_content = "!!!",
  ui_story_5038_50381402_26_dialog_content = "내 배에 손댈 생각 하지 마.",
  ui_story_5038_50381402_27_dialog_content = "으... 윽...",
  ui_story_5038_50381402_28_dialog_content = "힘이 빠진 것 같군요! 어서 제압해야 합니다!",
  ui_story_5038_50381402_29_dialog_content = "알겠어! 내가 왼팔을 잡을게!",
  ui_story_5038_50381402_30_dialog_content = "전하, 오른팔은 제게 맡겨 주세요.",
  ui_story_5038_50381402_31_dialog_content = "그, 그렇게 애쓸 필요 없어.",
  ui_story_5038_50381402_32_dialog_content = "그 앤 이미 힘을 잃었으니까.",
  ui_story_5038_50381402_33_dialog_content = "응? 정말?",
  ui_story_5038_50381402_34_dialog_content = "키이... 키이익...",
  ui_story_5038_50381402_35_dialog_content = "...물고기는 울음소리를 안 내.\n아플 때 어떤 소리를 내야 하는지는 아직 못 배운 모양이야.",
  ui_story_5038_50381402_36_dialog_content = "휴우... 드디어 이겼네요.",
  ui_story_5038_50381402_37_dialog_content = "그럼 이제 「나침반」을 되찾은 게 되는 건가요?",
  ui_story_5038_50381402_38_dialog_content = "그렇소. 그가 바로 「나침반」이니 말이오.",
  ui_story_5038_50381402_39_dialog_content = "수요령으로 변했다고는 하나, 「나침반」으로서의 기능은 여전하오.",
  ui_story_5038_50381402_40_dialog_content = "그럼... 이제 어떻게 하죠?",
  ui_story_5038_50381402_41_dialog_content = "......",
  ui_story_5038_50381402_42_dialog_content = "......",
  ui_story_5038_50381402_43_dialog_content = "「나침반」의 사용법을 따르자면, 먼저 그를 신풍호에 가두어야 하오.",
  ui_story_5038_50381402_44_dialog_content = "그 후 교룡어 무리에게 「귀향」하라는 신호를 보내도록 해야 하지.",
  ui_story_5038_50381402_45_dialog_content = "그리하면 대장의 신호를 받은 교룡어 떼가 신풍호 주위에 몰려들어\n우리를 용주까지 밀어줄 것이오.",
  ui_story_5038_50381402_46_dialog_content = "이제 우리의 여정에는 그 어떤 위험도 존재하지 않소.\n이전에도 수없이 반복되었던 항해들처럼 말이오.",
  ui_story_5038_50381402_47_dialog_content = "으음...",
  ui_story_5038_50381402_48_dialog_content = "이런 어린아이를 가두어 두어야만 하는 건가요?",
  ui_story_5038_50381402_49_dialog_content = "이런 이런, 순풍에 돛 단 듯 용주까지 간다는 점은 훌륭합니다만,\n그 방식이라는 것이 참으로 마음이 편치 않군요.",
  ui_story_5038_50381402_50_dialog_content = "지당하오. 하물며 우리는 조금 전 이 아이의 증오를 두 눈으로 직접 보지 않았소.",
  ui_story_5038_50381402_51_dialog_content = "린 가문의 선조로부터 비롯된 이 아이의 증오는,\n배에 오르는 사람이 많아질수록 점차 더 깊어졌을 것이오.",
  ui_story_5038_50381402_52_dialog_content = "배에 오른 모든 이가 그저 요행만을 바랄 뿐이었고,\n일개 물고기에 불과한 「나침반」이 증오를 품을 리 없다 재단했소.",
  ui_story_5038_50381402_53_dialog_content = "증오하지 않는다면 잘못 또한 없을 터이니, 가책을 느끼지도 않았던 것이오.",
  ui_story_5038_50381402_54_dialog_content = "쌓여 왔던 증오를 목도한 지금에야 후회한들 이미 늦은 것이지.",
  ui_story_5038_50381402_55_dialog_content = "...종 공께서도 후회하시나요?",
  ui_story_5038_50381402_56_dialog_content = "종 공 역시 「나침반」을 가두어 두는 것은 그릇된 일이라 여기시는 것이겠지요.",
  ui_story_5038_50381402_57_dialog_content = "이 종 모가 후회하는 일이 어찌 이뿐이겠소.",
  ui_story_5038_50381402_58_dialog_content = "비록 악업을 지은 자들이라고는 하나, 그 많은 이들의 목숨을 빼앗은 것도,\n「나침반」에 집착한 것도 모두 종 모의 실책이오.",
  ui_story_5038_50381402_59_dialog_content = "육지에서 해결하였어야 마땅한 문제를 바다로 끌고 오는 바람에,\n끝내 이 판국을 만들고 만 것이오.",
  ui_story_5038_50381402_60_dialog_content = "그럼 그 과오를... 우리가 계속 이어가야 하는 건가요?",
  ui_story_5038_50381402_61_dialog_content = "이 종 모, 이미 충분히 살아왔소. 죄과를 씻을 수 있다면 목숨도 아깝지 않소.",
  ui_story_5038_50381402_62_dialog_content = "허나 이곳에는 종 모 한 사람만 있는 것이 아니오.",
  ui_story_5038_50381402_63_dialog_content = "「나침반」을 쓰지 않는다면, 신풍호가 용주에 돌아갈 방법이 어디 있겠소.",
  ui_story_5038_50381402_64_dialog_content = "하지만...",
  ui_story_5038_50381402_65_dialog_content = "으음, 신풍호는 몇 차례고 충돌을 겪었고,\n파손의 정도를 가늠하는 것조차 어려운 형편이지요...",
  ui_story_5038_50381402_66_dialog_content = "형님 뜻은 저도 이해해요. 저도 계속해서 고민했던 문제인걸요.",
  ui_story_5038_50381402_67_dialog_content = "바다에선 뜻대로, 생각대로 안 되는 일이 정말 많죠.",
  ui_story_5038_50381402_68_dialog_content = "전 우룡을 친구라고 생각하고, 우룡한테 다시 자유를 주고 싶다고 생각해 왔어요...",
  ui_story_5038_50381402_69_dialog_content = "하지만... 전 그 대가를 감당할 자신은 없어요...",
  ui_story_5038_50381402_70_dialog_content = "대가...",
  ui_story_5038_50381402_71_dialog_content = "(아무도 섣불리 입을 열지 않았다.)",
  ui_story_5038_50381402_72_dialog_content = "(허공에서 얽히는 서로의 시선이 무력감만을 더하고 있었다.)",
  ui_story_5038_50381402_73_dialog_content = "(마치 침묵을 통해 곧 이루어질 선택을 참회하겠다는 것처럼.)",
  ui_story_5038_50381402_74_dialog_content = "(모두가 옳지 않다는 것은 알고 있었지만, 다른 선택의 여지가 없었다.)",
  ui_story_5038_50381402_75_dialog_content = "다들 그렇게 침울해할 거 없어요.",
  ui_story_5038_50381402_76_dialog_content = "「나침반」을 찾고 목표를 달성했으니 기뻐해야죠.",
  ui_story_5038_50381402_77_dialog_content = "...목 선장, 항해를 순조롭게 마칠 희망이 생긴 건 물론 기뻐해야 마땅한 일이야.",
  ui_story_5038_50381402_78_dialog_content = "하지만 이제부터 이 아이를 가두어 놓게 된다고 생각하면 아무래도...",
  ui_story_5038_50381402_79_dialog_content = "누가 가둔대요? 그럴 필요가 있나요?",
  ui_story_5038_50381402_80_dialog_content = "뭐?!",
  ui_story_5038_50381402_81_dialog_content = "월백, 그게 무슨 말이야?",
  ui_story_5038_50381402_82_dialog_content = "우리가 「나침반」을 찾으려던 건, 그게 용주로 돌아갈 유일한 방법이기 때문이었죠.",
  ui_story_5038_50381402_83_dialog_content = "하지만 그걸 찾은 뒤에 어떻게 활용할지는 여러 가지 선택지가 남아 있어요.",
  ui_story_5038_50381402_84_dialog_content = "여러분 모두 린 가문의 선조들이 내린 선택이 마음에 들지 않으신 거겠죠.",
  ui_story_5038_50381402_85_dialog_content = "그렇다면 전 새로운 선택을 하겠어요.",
  ui_story_5038_50381402_86_dialog_content = "정말? 우룡을 안 가둬도 되는 거야?",
  ui_story_5038_50381402_87_dialog_content = "......",
  ui_story_5038_50381402_88_dialog_content = "네게 묻고 싶은 게 있어. 신풍호의 승객이 되지 않겠니?",
  ui_story_5038_50381402_89_dialog_content = "...싫어.",
  ui_story_5038_50381402_90_dialog_content = "당연, 히, 싫어.",
  ui_story_5038_50381402_91_dialog_content = "그럼 신풍호와 네 인연도 여기까지인 모양이네.",
  ui_story_5038_50381402_92_dialog_content = "이 배는 곧 가라앉을 거야. 어서 바다로 돌아가도록 해.",
  ui_story_5038_50381402_93_dialog_content = "이 아이를 풀어주세요. 우린 이제 우리의 신풍호로 돌아가죠.",
  ui_story_5038_50381402_94_dialog_content = "저, 정말 괜찮겠습니까?",
  ui_story_5038_50381402_95_dialog_content = "풀어주는 것은 쉽지만, 다시 찾기는 무척 어려울 겁니다.",
  ui_story_5038_50381402_96_dialog_content = "이 아이, 물고기잖아요. 배에 있는 것보다는 바다로 돌아가는 게 훨씬 잘 어울려요.",
  ui_story_5038_50381402_97_dialog_content = "모두 가시죠. 안개도 걷혔으니 이제 돛을 펴고 출발해야겠어요.",
  ui_story_5038_50381402_98_dialog_content = "잘 생각한 것이오?",
  ui_story_5038_50381402_99_dialog_content = "네.",
  ui_story_5038_50381402_100_dialog_content = "종 대인, 절 막으실 건가요?",
  ui_story_5038_50381402_101_dialog_content = "이 종 모, 린 가문의 가업을 지켜주겠노라 린 형과 약조를 했소.",
  ui_story_5038_50381402_102_dialog_content = "이제 「나침반」을 린 가문의 다음 세대에 전해 주었으니,\n그 약조는 이미 지킨 것이오.",
  ui_story_5038_50381402_103_dialog_content = "선장이 이 선택의 무게를 확실히 알고 있다면, 종 모는 선장의 선택을 존중하겠소.",
  ui_story_5038_50381402_104_dialog_content = "자, 선장이 명을 내렸으니 그럼 우리도 가자.",
  ui_story_5038_50381402_105_dialog_content = "항해에 필요한 것이 무엇인지 누구보다 가장 잘 아는 게 선장이잖니.",
  ui_story_5038_50381402_106_dialog_content = "아, 그러게 말입니다. 저희가 공연한 걱정을 했군요.",
  ui_story_5038_50381402_107_dialog_content = "자, 가시죠. PlayerName 공, 얼른 안 오고 뭐 하십니까?",
  ui_story_5038_50381402_108_dialog_content = "아, 바닷속에 있는 교룡어들 보고 있었어요.",
  ui_story_5038_50381402_109_dialog_content = "정말 장관이네요. 다 같이 배 주위를 계속 맴돌고 있어요.",
  ui_story_5038_50381402_110_dialog_content = "꼭 이 배가 침몰하길 기다리고 있는 것처럼요...",
  ui_story_5038_50381402_111_dialog_content = "감상은 그쯤하고 갑시다. 신풍호에서도 똑같이 볼 수 있지 않습니까.",
  ui_story_5038_50381402_112_dialog_content = "자, 자, 어서요.",
  ui_story_5038_50381402_113_dialog_content = "하하, 알겠어요.",
  ui_story_5038_50381402_114_dialog_content = "축하해, 우룡! 이제 넌 자유야!",
  ui_story_5038_50381402_115_dialog_content = "자, 유...",
  ui_story_5038_50381402_116_dialog_content = "잘 모르겠어? 널 풀어 준다는 거야.",
  ui_story_5038_50381402_117_dialog_content = "모처럼 수요령이 됐으니까, 앞으론 말하는 연습도 많이 해야 돼!",
  ui_story_5038_50381402_118_dialog_content = "너랑 말하는 거 너무 힘들단 말이야.",
  ui_story_5038_50381402_119_dialog_content = "나를, 풀어, 줘?",
  ui_story_5038_50381402_120_dialog_content = "그래. 이해가 잘 안돼?",
  ui_story_5038_50381402_121_dialog_content = "이제 네가 가고 싶은 곳에 가면 돼.",
  ui_story_5038_50381402_122_dialog_content = "난...",
  ui_story_5038_50381402_123_dialog_content = "그럼 난 갈게. 난 바다에 빠지는 건 질색이니까.",
  ui_story_5038_50381402_124_dialog_content = "그래도 내가 너 친구라는 거 잊으면 안 돼!",
  ui_story_5038_50381402_125_dialog_content = "잘 있어!",
  ui_story_5038_50381402_126_dialog_content = "아이고! 선장님! 드디어 돌아오셨군요!",
  ui_story_5038_50381402_127_dialog_content = "안 계신 동안 신풍호가 다른 배와 충돌하고,\n암귀들의 습격까지 받아 이곳저곳 파손됐습니다.",
  ui_story_5038_50381402_128_dialog_content = "모두 최선을 다해 수리 중이긴 합니다만...",
  ui_story_5038_50381402_129_dialog_content = "알겠어. 수리는 계속 진행하고, 지금 바로 돛을 펼치도록 해.",
  ui_story_5038_50381402_130_dialog_content = "지금 바로 출발할 거니까.",
  ui_story_5038_50381402_131_dialog_content = "지금 말씀이십니까? 잠깐 재정비도 안 하고 말입니까?",
  ui_story_5038_50381402_132_dialog_content = "기다려 줄 시간이 없어.",
  ui_story_5038_50381402_133_dialog_content = "교룡어들이 곧 움직일 거야. 녀석들을 쫓아가야 해.",
  ui_story_5038_50381402_134_dialog_content = "교룡어요?",
  ui_story_5038_50381402_135_dialog_content = "오! 정말이네! 교룡어들이 움직이기 시작했어!",
  ui_story_5038_50381402_136_dialog_content = "모두 한 방향을 향해 이동하고 있어!",
  ui_story_5038_50381402_137_dialog_content = "용주를 향해 가는 거예요.",
  ui_story_5038_50381402_138_dialog_content = "이 바다에서 교룡어만큼 간절히 고향으로 돌아가고 싶어 하는 존재는 없을 테니까요.",
  ui_story_5038_50381402_139_dialog_content = "아! 무슨 말인지 알 것 같아요!",
  ui_story_5038_50381402_140_dialog_content = "월백 씨가 우룡을 풀어주면, 교룡어들도 다시 고향으로 돌아가려 하겠죠.",
  ui_story_5038_50381402_141_dialog_content = "교룡어들을 쫓아가면 신풍호도 최단 시간에 용주로 돌아갈 수 있을 테고요!",
  ui_story_5038_50381402_142_dialog_content = "이론은 간단하지만, 교룡어의 뒤를 쫓는 건 말처럼 쉬운 일은 아니야.",
  ui_story_5038_50381402_143_dialog_content = "이게 이번 여정의 마지막 항해가 될 거야.\n배의 모두가 힘을 보태 줘야만 해.",
  ui_story_5038_50381402_144_dialog_content = "네! 저도 최대한 도울게요!",
  ui_story_5038_50381402_145_dialog_content = "아이고오! 바닥에 물이 계속 찹니다!",
  ui_story_5038_50381402_146_dialog_content = "얼른 사람들 좀 불러 주세요!",
  ui_story_5038_50381402_147_dialog_content = "다들 눈코 뜰 새 없이 바빠서 여기 올 사람이 없어요.",
  ui_story_5038_50381402_148_dialog_content = "파도도 너무 세고, 신풍호도 여기저기가 부서진 상태라\n지금 이렇게 움직이는 것도 버거워요.",
  ui_story_5038_50381402_149_dialog_content = "여긴 얼마나 더 버틸 것 같아요?",
  ui_story_5038_50381402_150_dialog_content = "전에 토끼 귀로 덧대 놓았던 틈에서 또 물이 새고 있습니다.",
  ui_story_5038_50381402_151_dialog_content = "모두 최선을 다해 물을 퍼내고 있지만, 수위가 계속 높아지고 있어요.",
  ui_story_5038_50381402_152_dialog_content = "물이 계속... 그럼 이제 어떡하죠...",
  ui_story_5038_50381402_153_dialog_content = "뭐, 됐습니다. 다들 바쁠 테니 우리 쪽은 신경 쓰지 마세요.",
  ui_story_5038_50381402_154_dialog_content = "지금보다 더 빨리 퍼내면 될 일 아닙니까.",
  ui_story_5038_50381402_155_dialog_content = "보이십니까? 지금은 양동이를 한 손에 하나씩 들고 있지요.",
  ui_story_5038_50381402_156_dialog_content = "이제 소생이 입에도 양동이를 하나 물겠습니다.\n그럼 혼자서 세 양동이나 퍼낼 수 있겠지요!",
  ui_story_5038_50381402_157_dialog_content = "그, 그게 진짜 돼요?",
  ui_story_5038_50381402_158_dialog_content = "안 될 일이 어디 있겠습니까.\n이제 마지막 고비만 남았고, 모두 최선을 다하고 있지 않습니까.",
  ui_story_5038_50381402_159_dialog_content = "배가 전속력으로 이동하고 있는 한, 두려워할 게 없습니다.",
  ui_story_5038_50381402_160_dialog_content = "자, 자, 이제 가 보시지요. 소생은 바쁩니다!",
  ui_story_5038_50381402_161_dialog_content = "누구 빈 양동이 남은 거 있으면 소생에게 좀 주십쇼!",
  ui_story_5038_50381402_162_dialog_content = "PlayerName 공자! 이쪽이야. 이쪽으로 와!",
  ui_story_5038_50381402_163_dialog_content = "당신 도움이 필요해!",
  ui_story_5038_50381402_164_dialog_content = "단당 씨? 무슨 일이에요? 지금 뭘...",
  ui_story_5038_50381402_165_dialog_content = "돛을 고정하는 권양기가 고장이 났어.\n그래서 사람이 직접 밧줄을 잡아당기며 조정해야 해.",
  ui_story_5038_50381402_166_dialog_content = "줄곧 내가 밧줄을 붙잡고 있었지만...",
  ui_story_5038_50381402_167_dialog_content = "바람이 세져서 혼자서는 힘들어.",
  ui_story_5038_50381402_168_dialog_content = "아! 알겠어요! 저도 도울게요!",
  ui_story_5038_50381402_169_dialog_content = "이렇게 계속 잡고만 있으면 되나요?",
  ui_story_5038_50381402_170_dialog_content = "그래. 계속 붙잡고 있어.",
  ui_story_5038_50381402_171_dialog_content = "단당 씨 손바닥이 빨간데 괜찮아요?",
  ui_story_5038_50381402_172_dialog_content = "괜찮아. 평소 단련에 소홀했던 탓인걸.",
  ui_story_5038_50381402_173_dialog_content = "이런 사소한 일 하나도 제대로 못 한다니, 나도 참 무용하구나.",
  ui_story_5038_50381402_174_dialog_content = "이 상태로 얼마나 버텨야 할지도 모르는데, 더 붙잡고 있다간 단당 씨 손이...",
  ui_story_5038_50381402_175_dialog_content = "그게 뭐 대수라고, 신풍호도 버텨 주고 있잖니.",
  ui_story_5038_50381402_176_dialog_content = "상자를 전부 바다에 버려라!",
  ui_story_5038_50381402_177_dialog_content = "예!",
  ui_story_5038_50381402_178_dialog_content = "우와, 팍팍 집어 던지니까 기분 좋은데!",
  ui_story_5038_50381402_179_dialog_content = "그리고 이것도! 전부 다 던져 버려!",
  ui_story_5038_50381402_180_dialog_content = "침구도 다 버리는 건가요? 그럼 이제 잘 때 뭘 덮고...",
  ui_story_5038_50381402_181_dialog_content = "다 필요 없어. 이제 잠잘 시간이 있겠어?",
  ui_story_5038_50381402_182_dialog_content = "좋아. 그럼 이 상자도 버릴게!",
  ui_story_5038_50381402_183_dialog_content = "배가 조금이라도 가벼워지려면 중요한 물건 빼곤 전부 다 버려야 해.",
  ui_story_5038_50381402_184_dialog_content = "우리는 지금 바다와 시간 싸움 중이니까.",
  ui_story_5038_50381402_185_dialog_content = "그것도 그렇네요...",
  ui_story_5038_50381402_186_dialog_content = "그래요! 다 버려요!",
  ui_story_5038_50381402_187_dialog_content = "가구도 버려라! 탁자, 의자, 옮길 수 있는 건 모조리 바다에 던져라!",
  ui_story_5038_50381402_188_dialog_content = "(신풍호의 모두가 지금까지 봐왔던 모습 중 가장 분주하게 움직였다.)",
  ui_story_5038_50381402_189_dialog_content = "(모든 사람, 모든 도구가 최대의 힘을 발휘하고 있었다.)",
  ui_story_5038_50381402_190_dialog_content = "(침몰, 또는 용주로의 귀환, 신풍호를 기다리고 있는 것은 두 개의 종점이다.)",
  ui_story_5038_50381402_191_dialog_content = "(이 순간, 현실과 소망이 그 무엇보다 치열하게 맞부딪히고 있었다.)",
  ui_story_5038_50381402_192_dialog_content = "(우리는 머나먼 육지 방향을 바라보았다.\n태양은 지평선 위로 떠오르고, 배는 해수면 아래로 가라앉는 중이었다.)",
  ui_story_5038_50381402_193_dialog_content = "(운명은 안달이라도 난 듯 빠르게 결말을 선포하려 하고 있었다.)",
  ui_story_5038_50381402_194_dialog_content = "안 되겠습니다! 이젠 안 돼요! 선창 전체에 물이 들어찼어요!",
  ui_story_5038_50381402_195_dialog_content = "선원 여러분, 뭔가 방법이 없겠습니까?",
  ui_story_5038_50381402_196_dialog_content = "다 잠긴 건가...",
  ui_story_5038_50381402_197_dialog_content = "이래서야 무슨 방법이 있겠나, 선창까지 잠겼으면 이제 곧...",
  ui_story_5038_50381402_198_dialog_content = "으아악! 갑판에 물이 찬다아아!",
  ui_story_5038_50381402_199_dialog_content = "이런, 이제 어떻게 해야...",
  ui_story_5038_50381402_200_dialog_content = "우, 우리 이대로 침몰하는 건가?",
  ui_story_5038_50381402_201_dialog_content = "대체 어떻게 하면 좋단 말인가...",
  ui_story_5038_50381402_202_dialog_content = "선장님! 선장님!",
  ui_story_5038_50381402_203_dialog_content = "어디 가십니까? 지금 상황이...",
  ui_story_5038_50381402_204_dialog_content = "다들 당황하지 말고, 갑판에 제대로 서 있어.",
  ui_story_5038_50381402_205_dialog_content = "신풍호는 가라앉지 않으니까.",
  ui_story_5038_50381402_206_dialog_content = "<color=#e8d9bb>쿵! 쿵, 쿵, 쿵──!</color>",
  ui_story_5038_50381402_207_dialog_content = "이, 이건 또 뭡니까?!",
  ui_story_5038_50381402_208_dialog_content = "무언가 배의 바닥에 부딪힌 것 같은데...",
  ui_story_5038_50381402_209_dialog_content = "자, 잠깐만요! 지금 배가 떠오르고 있는 것 같지 않아요?",
  ui_story_5038_50381402_210_dialog_content = "정말이군요! 이게 대체 어찌 된...",
  ui_story_5038_50381402_211_dialog_content = "<color=#e8d9bb>촤아아악──!</color>",
  ui_story_5038_50381402_212_dialog_content = "우와아아! 배가 날고 있어요!",
  ui_story_5038_50381402_213_dialog_content = "아, 아래 좀 봐! 교룡어야! 교룡어가 잔뜩 있어!",
  ui_story_5038_50381402_214_dialog_content = "교룡어들이 신풍호를 받쳐 주고 있는 거야!",
  ui_story_5038_50381402_215_dialog_content = "정말이군요! 실로 장관입니다!",
  ui_story_5038_50381402_216_dialog_content = "내가 그랬잖아. 교룡어는 배에 있는 것보다는 바다로 돌아가는 게 훨씬 잘 어울린다고.",
  ui_story_5038_50381402_217_dialog_content = "그래! 우룡이 우릴 도와주고 있는 건가 봐!",
  ui_story_5038_50381402_218_dialog_content = "우룡! 너 거기 있지?",
  ui_story_5038_50381402_219_dialog_content = "고마워!",
  ui_story_5038_50381402_220_dialog_content = "월백 씨, 우룡을 풀어 줄 때 이렇게 될 줄 아셨던 건가요?",
  ui_story_5038_50381402_221_dialog_content = "아니. 바다는 변화무쌍해서 예측할 수 없는 곳이야.\n그 누구도 바다에서 일어날 일을 미리 알 순 없어.",
  ui_story_5038_50381402_222_dialog_content = "내가 아는 건 그저 우리가 모든 목표를 달성했고,\n이 항해를 위해 충분한 노력도 했다는 거야.",
  ui_story_5038_50381402_223_dialog_content = "우린 반드시 용주에 도착할 거야.",
  ui_story_5038_50381501_1_dialog_content = "종 공, 오셨군요.",
  ui_story_5038_50381501_2_dialog_content = "얼른 종 대인을 이쪽으로 모시세요.",
  ui_story_5038_50381501_3_dialog_content = "예~ 예~ 갑니다~ 다들 도와줄 것도 아니면서 보채지 좀 말라구.",
  ui_story_5038_50381501_4_dialog_content = "리청 아우, 이게 무슨 일이냐.",
  ui_story_5038_50381501_5_dialog_content = "다들 형님이 선실에만 계시느라 이렇게 멋진 광경을 못 보실까\n걱정하고 있었거든요.",
  ui_story_5038_50381501_6_dialog_content = "자, 형님, 우리가 어딜 왔는지 보세요.",
  ui_story_5038_50381501_7_dialog_content = "이건...",
  ui_story_5038_50381501_8_dialog_content = "우리가 돌아온 것이냐.",
  ui_story_5038_50381501_9_dialog_content = "네! 돌아왔어요! 드디어 용주로 돌아왔다구요!",
  ui_story_5038_50381501_10_dialog_content = "그리우셨어요?",
  ui_story_5038_50381501_11_dialog_content = "용주라...",
  ui_story_5038_50381501_12_dialog_content = "수십 년을 살아오며 「용주」라는 이름으로 발아래 땅을 부른 적은 드물었지.",
  ui_story_5038_50381501_13_dialog_content = "아우에게서 용주라는 이름을 듣고 보니 이토록 그리울 줄이야.",
  ui_story_5038_50381501_14_dialog_content = "우리가 오래 떠나 있었긴 한 모양이로구나.",
  ui_story_5038_50381501_15_dialog_content = "맞아요. 그동안 그 많은 일을 겪었고, 그렇게 먼 곳까지 갔으니까요.",
  ui_story_5038_50381501_16_dialog_content = "오가는 사이에 배도 바뀌었고, 이륜거도 타게 되었지.",
  ui_story_5038_50381501_17_dialog_content = "조정에 나아가 황상을 알현하는 것도 이제는 쉽지 않을 것 같구나.",
  ui_story_5038_50381501_18_dialog_content = "형님은 용주에서 그리웠던 게 조정밖에 없으세요?",
  ui_story_5038_50381501_19_dialog_content = "이 나이까지 살고 나면 쉽게 추억에 빠져들게 되는 법이다.",
  ui_story_5038_50381501_20_dialog_content = "조정이든, 천지 사해든, 한 번 가 보았던 곳에는 모두 추억이 남기 마련이지.",
  ui_story_5038_50381501_21_dialog_content = "형님은 매번 빙빙 돌려 말씀하시니까, 이해하기가 너무 힘들어요.",
  ui_story_5038_50381501_22_dialog_content = "그냥 쉽게 말해서, 갑판에서 이런 멋진 경치를 보니까 좋으세요? 안 좋으세요?",
  ui_story_5038_50381501_23_dialog_content = "하하, 실로 좋구나.",
  ui_story_5038_50381501_24_dialog_content = "저기 보세요! 교룡어들이 떠나기 시작했어요!",
  ui_story_5038_50381501_25_dialog_content = "하긴, 우리랑 같이 땅으로 올라갈 순 없잖아.",
  ui_story_5038_50381501_26_dialog_content = "우릴 항구까지 데려다줬으니까, 이제 교룡어들도 자기들 할 일을 해야지.",
  ui_story_5038_50381501_27_dialog_content = "교룡어들이 한참을 태워 줘서 그런지, 이렇게 헤어지려니까 조금 아쉬운걸.",
  ui_story_5038_50381501_28_dialog_content = "어느새 벌써 익숙해진 모양이야.",
  ui_story_5038_50381501_29_dialog_content = "스승님도 그러셨어. 헤어짐은 항상 아쉬운 법이라고.",
  ui_story_5038_50381501_30_dialog_content = "녀석들을 계속 붙잡아 둘 순 없으니까, 제대로 작별 인사를 해 주자.",
  ui_story_5038_50381501_31_dialog_content = "그래. 종점에 도착하면 지금까지 동행했던 사람들과도 헤어져야 하는 거니까.",
  ui_story_5038_50381501_32_dialog_content = "고마웠어! 잘 가!",
  ui_story_5038_50381501_33_dialog_content = "흑...흑흑... 드디어 돌아왔어...",
  ui_story_5038_50381501_34_dialog_content = "그러게 말이야. 진짜로 바다에서 영영 못 돌아오는 줄 알았다니까.",
  ui_story_5038_50381501_35_dialog_content = "이제 좀 살 것 같네. 육지가 보이니까 안심이 되기 시작했어.",
  ui_story_5038_50381501_36_dialog_content = "다 선장님 덕분이에요.\n선장님이 아니었으면 벌써 몇 번이나 침몰하고도 남았을 거예요.",
  ui_story_5038_50381501_37_dialog_content = "당연하지! 우리 선장님이 최고라니까!",
  ui_story_5038_50381501_38_dialog_content = "게다가 선장님이 우릴 이끌고 해내신 게 어디 보통 일이야?",
  ui_story_5038_50381501_39_dialog_content = "린 가문의 항로를 다시 개통하셨다 이 말이야!",
  ui_story_5038_50381501_40_dialog_content = "앗! 선장님 오셔요!",
  ui_story_5038_50381501_41_dialog_content = "선장님! 얼른 오세요! 다들 선장님 칭찬을 얼마나 했는데요!",
  ui_story_5038_50381501_42_dialog_content = "당신들...",
  ui_story_5038_50381501_43_dialog_content = "왜 여기 모여서 노닥거리고 있어? 빨리 원위치로 돌아가.",
  ui_story_5038_50381501_44_dialog_content = "접안 준비해야지. 마지막까지 와서 삐끗하진 마.",
  ui_story_5038_50381501_45_dialog_content = "다들 들었나! 선장님 명령이다! 삐끗하지 마라!",
  ui_story_5038_50381501_46_dialog_content = "예!",
  ui_story_5038_50381501_47_dialog_content = "조, 조금 긴장되기 시작했어요...",
  ui_story_5038_50381501_48_dialog_content = "이따 배에서 내리면 전 뭘 해야 하죠?",
  ui_story_5038_50381501_49_dialog_content = "저흴 따라오시면 됩니다. 긴장하실 게 뭐 있습니까!",
  ui_story_5038_50381501_50_dialog_content = "바다에서 그 모진 풍파를 겪었는데, 육지에 그보다 두려운 일이 어디 있겠습니까?",
  ui_story_5038_50381501_51_dialog_content = "그렇지만... 용주는 처음 와 보는 곳이라 모르는 것도 많고 낯설어서요.",
  ui_story_5038_50381501_52_dialog_content = "익숙한 구석이 있을지도 모르겠고, 게다가 이번엔 혼자니까...",
  ui_story_5038_50381501_53_dialog_content = "왜 혼자라는 거야? 공자 곁에는 우리가 있잖아.",
  ui_story_5038_50381501_54_dialog_content = "옳으신 말씀입니다.",
  ui_story_5038_50381501_55_dialog_content = "용주에 도착하고 나면 만물박사인 소생이 최고의 진미만 엄선해서 맛보여 드리지요.",
  ui_story_5038_50381501_56_dialog_content = "그래, 그래, 됐으니까 그대는 어서 가서 행장이나 정리해라.",
  ui_story_5038_50381501_57_dialog_content = "선장이 서두르라고 하잖니. 어서 하선 준비를 해야지!",
  ui_story_5038_50381501_58_dialog_content = "맛있는── 탕후루── 사세요──",
  ui_story_5038_50381501_59_dialog_content = "달콤하고── 맛있는── 탕후루──",
  ui_story_5038_50381501_60_dialog_content = "주인장, 탕후루 하나 얼마요?",
  ui_story_5038_50381501_61_dialog_content = "저쪽에 설탕 인형 부는 사람도 있네! 얼른 가 보자!",
  ui_story_5038_50381501_62_dialog_content = "이거 탕원 냄새 아냐?",
  ui_story_5038_50381501_63_dialog_content = "우와! 거리가 엄청 시끌벅적하네요!",
  ui_story_5038_50381501_64_dialog_content = "사람이 엄청 많아요!",
  ui_story_5038_50381501_65_dialog_content = "어때? 재미있니?",
  ui_story_5038_50381501_66_dialog_content = "아, 아직 잘 모르겠어요. 용주의 거리는 언제나 이렇게 사람이 많나요?",
  ui_story_5038_50381501_67_dialog_content = "그렇지는 않아. 지금은 마침 「춘삭절」의 끝자락이거든.",
  ui_story_5038_50381501_68_dialog_content = "춘삭절은 용주에서 가장 큰 명절이야.\n그래서 거리엔 먹거리와 놀거리가 가득하단다.",
  ui_story_5038_50381501_69_dialog_content = "자, 저기 저 아이가 들고 있는 것은 「탕후루」라는 거야. 새콤달콤하고 맛있어.",
  ui_story_5038_50381501_70_dialog_content = "그리고 저 탁자에 길게 늘어놓은 건 「설탕 인형」이라는 거야.\n설탕을 녹여서 공기를 불어 넣어 만드는 건데, 눈으로만 감상해야 해.",
  ui_story_5038_50381501_71_dialog_content = "또 저기 커다란 솥에서 끓이고 있는 건 「탕원」인데, 찹쌀떡 안에 소를 넣은 거야.\n이 무렵에만 맛볼 수 있는 간식이란다.",
  ui_story_5038_50381501_72_dialog_content = "우와, 뭐가 엄청 많네요!",
  ui_story_5038_50381501_73_dialog_content = "궁금한 게 있다면 뭐든 내게 물어봐도 좋아.",
  ui_story_5038_50381501_74_dialog_content = "그럼 어디...",
  ui_story_5038_50381501_75_dialog_content = "저기 누가 자리를 깔고 통 안의 막대기를 막 흔들고 있는데, 저건 뭐 하는...",
  ui_story_5038_50381501_76_dialog_content = "아이고오! 저건 좋은 게 아닙니다! 공갈해 돈을 뜯는 겁니다!",
  ui_story_5038_50381501_77_dialog_content = "돈을 뜯어요?",
  ui_story_5038_50381501_78_dialog_content = "그렇습니다. 저건 「산명」이라는 것인데, 좋은 게 못 됩니다.",
  ui_story_5038_50381501_79_dialog_content = "저런 사람들은 신이니 귀신이니 하면서 길흉화복을 점쳐 준다고 말하곤 하지요.",
  ui_story_5038_50381501_80_dialog_content = "허나 실상은 그럴듯한 말로 사람을 꾀어 돈을 뜯어내는 것입니다.",
  ui_story_5038_50381501_81_dialog_content = "네? 그렇게 나쁜 짓을 하는 사람을 왜 저렇게 놔두는 거죠?",
  ui_story_5038_50381501_82_dialog_content = "음, 거기에는 말로는 표현하기 무척 곤란한 그런...\n복잡미묘한 이유가 있다고나 할까요?",
  ui_story_5038_50381501_83_dialog_content = "아무튼 저런 사람들은 믿으시면 안 됩니다.\n정말로 앞날이 궁금하시다면 소생에게 부탁하시면 됩니다!",
  ui_story_5038_50381501_84_dialog_content = "처, 천간 씨한테요?",
  ui_story_5038_50381501_85_dialog_content = "근데 방금 그건 나쁜 거라고 하지 않았어요?",
  ui_story_5038_50381501_86_dialog_content = "세상만사는 그리 간단한 게 아닙니다. 사람을 가려야지요.",
  ui_story_5038_50381501_87_dialog_content = "후훗, 우리 용주에는 「동종업자는 원수」라는 옛말이 있어.",
  ui_story_5038_50381501_88_dialog_content = "PlayerName 공자, 곰곰이 잘 생각해 봐~",
  ui_story_5038_50381501_89_dialog_content = "아이, 참! 좀 비켜 주세요! 잠깐 지나갈게요!",
  ui_story_5038_50381501_90_dialog_content = "여기 몸이 불편한 분이 계신 거 안 보여요?",
  ui_story_5038_50381501_91_dialog_content = "리청 아우, 다른 이들에게 방해가 되지 않도록 천천히 가세.",
  ui_story_5038_50381501_92_dialog_content = "그럴 순 없어요. 온갖 고생을 하다가 드디어 돌아왔는데, 당당하게 가야죠!",
  ui_story_5038_50381501_93_dialog_content = "근데 선장 누나, 우리 지금 다 지금 어디 가는 거야?",
  ui_story_5038_50381501_94_dialog_content = "신풍호는 린 가문의 상선이야. 입항을 했으면 당연히 린 가문 저택으로 가야지.",
  ui_story_5038_50381501_95_dialog_content = "다들 괜찮다면 며칠 묵고 가세요.",
  ui_story_5038_50381501_96_dialog_content = "명절이고 하니 가주님께서도 손님이 많은 걸 좋아하실 테니까요.",
  ui_story_5038_50381501_97_dialog_content = "형님, 가실 거죠?",
  ui_story_5038_50381501_98_dialog_content = "저 배고파요.",
  ui_story_5038_50381501_99_dialog_content = "당연히 가야지. 초대해 주지 않았어도 갈 생각이었네.",
  ui_story_5038_50381501_100_dialog_content = "린 가문 가주께서 이 종 모에게 빚을 단단히 지셨으니 말이오.",
  ui_story_5038_50381501_101_dialog_content = "종 대인, 춘삭절에 집까지 찾아오는 빚쟁이가 어디 있나요.",
  ui_story_5038_50381501_102_dialog_content = "게다가 가세가 기운 지금의 린 가문이 위용을 떨치는 장군의 요구를\n어떻게 감당하겠어요.",
  ui_story_5038_50381501_103_dialog_content = "치르지 못하는 편이 더 좋소.",
  ui_story_5038_50381501_104_dialog_content = "종 모는 가주께 이 빚을 평생 달아두고 싶으니 말이오.",
  ui_story_5038_50381501_105_dialog_content = "돌아왔습니다! 신풍호 사람들이 돌아왔어요!",
  ui_story_5038_50381501_106_dialog_content = "아이고! 얼마나 고생들을 하셨습니까! 어서 들어오시지요!",
  ui_story_5038_50381501_107_dialog_content = "다들 피로하진 않으십니까?",
  ui_story_5038_50381501_108_dialog_content = "우와, 여기가 바로 린 가문 저택인가요?",
  ui_story_5038_50381501_109_dialog_content = "신풍호처럼 커다란 배를 만들 정도면 으리으리할 줄 알았는데,\n생각보다 평범하네요.",
  ui_story_5038_50381501_110_dialog_content = "가세가 기울었으니까요.",
  ui_story_5038_50381501_111_dialog_content = "예전에는 아주 대단했다고 들었습니다.",
  ui_story_5038_50381501_112_dialog_content = "대저택은 적막하기만 하지 좋을 거 하나 없어.",
  ui_story_5038_50381501_113_dialog_content = "지금 정도면 명절 분위기도 내고 좋은걸!",
  ui_story_5038_50381501_114_dialog_content = "모두 돌아왔으니 안으로 들게.",
  ui_story_5038_50381501_115_dialog_content = "언제까지 문 앞에 계속 서 있을 참인가.",
  ui_story_5038_50381501_116_dialog_content = "어라, 이 어르신은...",
  ui_story_5038_50381501_117_dialog_content = "가주님, 어찌 나오셨습니까.",
  ui_story_5038_50381501_118_dialog_content = "신풍호의 귀환이라는 대사를 두고 내 어찌 집 안에 가만히 앉아 있을 수 있겠느냐.",
  ui_story_5038_50381501_119_dialog_content = "이 자리의 모두가 린 가문의 공신이자 귀한 손님들이거늘,\n항구에 나가 영접하지 못한 무례를 부디 용서해 주시오.",
  ui_story_5038_50381501_120_dialog_content = "그러게나 말이오.\n성대한 연회도 준비하고 백 리 밖까지 맞이하러 나오라 할 것을 그랬소.",
  ui_story_5038_50381501_121_dialog_content = "그리하였다면 집에 앉아 편안히 지낸 면목이 있었을 것 아니오.",
  ui_story_5038_50381501_122_dialog_content = "종 형, 돌아왔는가!",
  ui_story_5038_50381501_123_dialog_content = "다리가... 어찌...",
  ui_story_5038_50381501_124_dialog_content = "그저 조금 다쳤을 뿐이오.",
  ui_story_5038_50381501_125_dialog_content = "돌이켜 보면 이 종 모가 조정을 위해 출정할 무렵에는 몸에 생채기나 남고 말 뿐이었소.",
  ui_story_5038_50381501_126_dialog_content = "헌데 린 가문을 위해 나서니 두 다리가 부러졌지 뭐요.",
  ui_story_5038_50381501_127_dialog_content = "우리 린 형의 체면은 황상보다도 살라기 어렵구려.",
  ui_story_5038_50381501_128_dialog_content = "종 형, 내 어찌 책임을 져야 할지 모르겠소...",
  ui_story_5038_50381501_129_dialog_content = "우선 여기 머물며 요양을 하는 게 어떻겠나?\n내 명의를 수소문해 볼 터이니, 치료를 받으며 호전되는지 지켜 보도록 하세.",
  ui_story_5038_50381501_130_dialog_content = "괜찮소. 이륜거에 앉아 지내는 것도 한가하고 좋으니 말이오.",
  ui_story_5038_50381501_131_dialog_content = "게다가 다른 의원이 이 사람의 다리를 낫게 해 버리면,\n우리 리청 아우의 체면이 뭐가 되겠소.",
  ui_story_5038_50381501_132_dialog_content = "고칠 수 있는 사람은 없어요!",
  ui_story_5038_50381501_133_dialog_content = "형님 다리는 못 고쳐요! 누가 와도 소용없다니까요!",
  ui_story_5038_50381501_134_dialog_content = "이, 이 친구 말이 너무 심하지 않은가?",
  ui_story_5038_50381501_135_dialog_content = "하하, 괘념치 마시오. 리청 아우는 항상 입바른 소리를 잘하니 말이오.",
  ui_story_5038_50381501_136_dialog_content = "이번 여정을 통해 참으로 많은 경험을 했소만...",
  ui_story_5038_50381501_137_dialog_content = "린 형, 내 결국 「나침반」은 지키지 못했소.",
  ui_story_5038_50381501_138_dialog_content = "종 형...",
  ui_story_5038_50381501_139_dialog_content = "날 얼마나 더 난처하게 만들려고 그런 말씀을 하는 게요?",
  ui_story_5038_50381501_140_dialog_content = "종 형이 이렇게 돌아온 것만 해도 여간 어려운 일이 아니었소.",
  ui_story_5038_50381501_141_dialog_content = "모두 이 사람이 부덕하여 가업을 지키지 못하고 벗까지 말려들게 만든 것이네.",
  ui_story_5038_50381501_142_dialog_content = "이 자리를 빌려 종 형과 모두에게 사죄하겠소.",
  ui_story_5038_50381501_143_dialog_content = "괜찮소, 괜찮대도.",
  ui_story_5038_50381501_144_dialog_content = "공도 없이 녹을 받을 순 없는 일이오.\n이 종 모, 「나침반」을 지키지 못했으니 우리 서로 빚진 것으로 하세.",
  ui_story_5038_50381501_145_dialog_content = "허나 린 가문에는 이제 「나침반」 없이도 바다를 오갈 수 있는\n훌륭한 신예가 있더군.",
  ui_story_5038_50381501_146_dialog_content = "그 이야기는 직접 듣는 편이 좋겠소.",
  ui_story_5038_50381501_147_dialog_content = "그러고 보니 모두 「나침반」 없이도 무사히 돌아왔구려.",
  ui_story_5038_50381501_148_dialog_content = "월백, 아주 잘해 주었구나.",
  ui_story_5038_50381501_149_dialog_content = "가주님, 사죄드릴 일이 있습니다.",
  ui_story_5038_50381501_150_dialog_content = "실은 「나침반」을 손에 넣었습니다. 다만 그 후 바다에 풀어준 것입니다.",
  ui_story_5038_50381501_151_dialog_content = "풀어 주었다...?",
  ui_story_5038_50381501_152_dialog_content = "전 선조님들이 「나침반」을 이용해 바다를 건너는 방식이\n옳지 못하다고 생각했고, 이에 그러한 결정을 내렸습니다.",
  ui_story_5038_50381501_153_dialog_content = "제 결정에 부끄러움은 없으나, 가문의 보물을 제 손으로 망가트린 것도 사실입니다.",
  ui_story_5038_50381501_154_dialog_content = "따라서 가주님께 사죄드리고자 합니다.",
  ui_story_5038_50381501_155_dialog_content = "하하하하, 그 말은 이 늙은이를 책망하는 것이지, 어딜 봐서 사죄란 말이냐.",
  ui_story_5038_50381501_156_dialog_content = "말속에 뼈가 든 것이, 종 형에게 배운 것이더냐?",
  ui_story_5038_50381501_157_dialog_content = "...그럴 뜻은 없었습니다.",
  ui_story_5038_50381501_158_dialog_content = "보물은 무슨, 바다를 건너고자 어쩔 수 없이 궁리해 냈던 방편일 뿐이다.",
  ui_story_5038_50381501_159_dialog_content = "네가 나침반에 의지하지 않아도 된다니, 오히려 그것이 더 기쁘구나.",
  ui_story_5038_50381501_160_dialog_content = "너그러이 용서해 주셔서 감사합니다.",
  ui_story_5038_50381501_161_dialog_content = "얘야, 뭘 그리 예를 차리는 것이냐.",
  ui_story_5038_50381501_162_dialog_content = "넌 가문을 위해 자신만을 항로를 개척해 주었다.\n시간이 흐르고 나면 네가 가주의 자리에 앉을지도 모르겠구나.",
  ui_story_5038_50381501_163_dialog_content = "예?!",
  ui_story_5038_50381501_164_dialog_content = "가주님, 칭찬이 너무 과하십니다...",
  ui_story_5038_50381501_165_dialog_content = "과찬이 아니라 네가 마땅히 받아야 할 평가다.",
  ui_story_5038_50381501_166_dialog_content = "앞으로는 네가 출신에 연연하지 않았으면 좋겠구나.\n결국 모두 지난 일이 아니더냐.",
  ui_story_5038_50381501_167_dialog_content = "잊지 말거라.\n숲도 나무가 될 수 있고, 나무도 숲이 될 수 있음을.",
  ui_story_5038_50381501_168_dialog_content = "네, 명심하겠습니다.",
  ui_story_5038_50381501_169_dialog_content = "자, 됐다. 늙은이가 말이 길었구나.",
  ui_story_5038_50381501_170_dialog_content = "날이 차니 어서들 안으로 들어오시게.\n좋은 술과 요리를 내올 테니, 마음껏 드시오.",
  ui_story_5038_50381501_171_dialog_content = "자, 계속 멀뚱히 서 있지 마시구요. 가주님께서도 어서 들어오라 하셨잖아요.",
  ui_story_5038_50381501_172_dialog_content = "얼른 들어가죠! 이야기는 안에 들어가서 하기로 해요!",
  ui_story_5038_50381501_173_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5038_50381501_174_dialog_content = "저, 저도 들어가는 건가요?",
  ui_story_5038_50381501_175_dialog_content = "당연하지. 다른 곳에 볼일이라도 있는 거야?",
  ui_story_5038_50381501_176_dialog_content = "아니요, 그런 건 아닌데...",
  ui_story_5038_50381501_177_dialog_content = "저는 린 가문이랑 아무 상관도 없는데, 왠지 신세를 지기가 좀 그래서요...",
  ui_story_5038_50381501_178_dialog_content = "아무 상관도 없다니? 여기 모두가 신풍호를 도와준 은인들인걸.",
  ui_story_5038_50381501_179_dialog_content = "봐. 다른 사람들은 벌써 들어가서 먹느라 바쁘잖아.",
  ui_story_5038_50381501_180_dialog_content = "좋은 술과 요리가 기다리고 있으니 소생도 얼른 들어가 봐야겠습니다.",
  ui_story_5038_50381501_181_dialog_content = "부유한 가문의 요리라면 분명히 대단하겠지. 구, 우리도 맛을 보자!",
  ui_story_5038_50381501_182_dialog_content = "전하! 문지방에 걸리지 않도록 조심하십시오!",
  ui_story_5038_50381501_183_dialog_content = "우와, 순식간에 다들 가 버렸네요...",
  ui_story_5038_50381501_184_dialog_content = "그러니까 그런 쓸데없는 걱정은 하지 마.",
  ui_story_5038_50381501_185_dialog_content = "용주에 머무는 동안은 린 가문에 묵으면 돼.",
  ui_story_5038_50381501_186_dialog_content = "그리고 신풍호가 다음번에 출항할 때 내가 다시 아스트라로 데려다줄게.",
  ui_story_5038_50381501_187_dialog_content = "그럼 그동안 계속 린 가문의 손님으로 지내라는 건가요?\n그건 아무래도 너무 민폐 같은데요...",
  ui_story_5038_50381501_188_dialog_content = "용주 사람들처럼 예의상 사양하는 건 안 배워도 돼.",
  ui_story_5038_50381501_189_dialog_content = "들어가자. 이러다 맛있는 건 한 입도 못 먹을 거야.",
  ui_story_5038_50381501_190_dialog_content = "(용주는 무척이나 떠들썩한 곳이었다.)",
  ui_story_5038_50381501_191_dialog_content = "(집 안 가득 울려 퍼지는 웃음소리 때문인지 외로움은 조금도 느껴지지 않았다.)",
  ui_story_5038_50381501_192_dialog_content = "<color=#e8d9bb>며칠 뒤</color>",
  ui_story_5038_50381501_193_dialog_content = "신풍호에 가 보라니요? 지금 당장 말입니까?",
  ui_story_5038_50381501_194_dialog_content = "네. 월백 씨가 다들 모여달라고 했거든요. 지금 천간 씨 빼고 다 모였어요.",
  ui_story_5038_50381501_195_dialog_content = "허나 소생은 출항하고 싶은 마음이 없습니다. 배에서 뭘 하겠다는 겁니까?",
  ui_story_5038_50381501_196_dialog_content = "걱정 마세요. 바다로 나가려는 게 아니니까요.\n천간 씨를 아스트라 대륙으로 납치하지도 않을 거예요.",
  ui_story_5038_50381501_197_dialog_content = "구체적으로 뭐 때문인진 저도 못 들었어요. 아무튼 가 보면 알겠죠!",
  ui_story_5038_50381501_198_dialog_content = "알겠습니다. 어차피 항구까지는 멀지도 않으니 한 번 다녀오면 되겠지요.",
  ui_story_5038_50381501_199_dialog_content = "그래야죠!",
  ui_story_5038_50381501_200_dialog_content = "그나저나 PlayerName 공, 용주에서 지내는 동안 즐거우셨습니까?",
  ui_story_5038_50381501_201_dialog_content = "아직도 좀 낯설어서 용주 사람들한테 말을 걸진 못하고 있어요.",
  ui_story_5038_50381501_202_dialog_content = "그리고 어디 가서 뭘 해야 재미있을지도 잘 모르겠고요.",
  ui_story_5038_50381501_203_dialog_content = "아이고, 이거 린 가문도 참 손님 대접이 엉망이로군요.",
  ui_story_5038_50381501_204_dialog_content = "나중에 소생을 찾아오십시오. 제가 제대로 구경시켜 드리겠습니다.",
  ui_story_5038_50381501_205_dialog_content = "하하하, 좋아요!",
  ui_story_5038_50381501_206_dialog_content = "아, 참! 그러고 보니 이상한 일이 하나 있었어요.",
  ui_story_5038_50381501_207_dialog_content = "이상한 일?",
  ui_story_5038_50381501_208_dialog_content = "사실 제가 부탁받은 일이 있어서 용주에 편지를 한 통 가져왔거든요.",
  ui_story_5038_50381501_209_dialog_content = "근데 어제오늘 아무리 살펴봐도 받는 사람 주소를 못 찾겠더라고요.",
  ui_story_5038_50381501_210_dialog_content = "그러다 어제 편지를 정리하다가 실수로 그 편지 위에 물을 엎었거든요.",
  ui_story_5038_50381501_211_dialog_content = "그랬더니 밀랍이 다 젖어서 봉투가 열리고,\n안에서 <color=#FFB400>빨간 종이</color>가 잔뜩 나와서 날아갔지 뭐예요.",
  ui_story_5038_50381501_212_dialog_content = "빨간 종이 말입니까?!",
  ui_story_5038_50381501_213_dialog_content = "네, 빨간 종이를 잘라 만든 나비 같았어요.\n한곳에 모이더니 순식간에 날아가 버렸다니까요.",
  ui_story_5038_50381501_214_dialog_content = "편지 봉투 속에 다른 건 아무것도 없었어요.\n이래서야 편지를 전했다고 할 수 있을지 모르겠어요.",
  ui_story_5038_50381501_215_dialog_content = "아, 그런 것이라면...",
  ui_story_5038_50381501_216_dialog_content = "천간 씨, 뭔가 짚이는 게 있나요?",
  ui_story_5038_50381501_217_dialog_content = "흐으으음, 아주 심오하군요.",
  ui_story_5038_50381501_218_dialog_content = "일단 편지를 보낸 이의 뜻은 이미 이루어졌으니, 더는 신경 쓰지 않으셔도 됩니다.",
  ui_story_5038_50381501_X218_dialog_content = "나비는 꽃을 연모하니, 그 빨간 종이들은 저절로 받는 이에게 향할 겁니다.",
  ui_story_5038_50381501_219_dialog_content = "그것으로 끝난 일이지요.",
  ui_story_5038_50381501_220_dialog_content = "어? 그럼 저도 배달을 마친 건가요?",
  ui_story_5038_50381501_221_dialog_content = "믈론이지요.",
  ui_story_5038_50381501_X221_dialog_content = "그게 바다 건너 이곳까지 올 줄은 정말 몰랐습니다.",
  ui_story_5038_50381501_X222_dialog_content = "<size=35>복과 화는 바늘과 실 같다더니,\n역시 이번 난관에서 살아남을 수 있었던 복도 거저 얻은 것은 아니었나 봅니다.</size>",
  ui_story_5038_50381501_X223_dialog_content = "<size=35>그렇다면 이제...</size>",
  ui_story_5038_50381501_X224_dialog_content = "네? 복과 화가 어쨌다구요?",
  ui_story_5038_50381501_X225_dialog_content = "아, 그저 혼잣말일 뿐, 아무것도 아닙니다.",
  ui_story_5038_50381501_222_dialog_content = "오, 마침 부둣가에 다 왔군요.",
  ui_story_5038_50381501_223_dialog_content = "PlayerName 공, 어서 가시지요.",
  ui_story_5038_50381501_224_dialog_content = "난간 쪽 판자 못질은 다 됐나?",
  ui_story_5038_50381501_225_dialog_content = "물론이지! 못이 좀 남았는데 필요한 사람 있어?",
  ui_story_5038_50381501_226_dialog_content = "오, 마지막 두 사람이 드디어 왔구나!",
  ui_story_5038_50381501_227_dialog_content = "자, 빨리 와. 기다리다 목 빠지는 줄 알았잖아.",
  ui_story_5038_50381501_228_dialog_content = "선장 누나! 사람 다 모였어!",
  ui_story_5038_50381501_229_dialog_content = "다 온 거야?",
  ui_story_5038_50381501_230_dialog_content = "좋아. 그럼 시작하자.",
  ui_story_5038_50381501_231_dialog_content = "선장님, 사람들을 다 불러 모아서 무슨 일을 꾸미시는 것인지요?",
  ui_story_5038_50381501_232_dialog_content = "우린 모두 함께 수많은 풍파를 겪은 사이야.",
  ui_story_5038_50381501_233_dialog_content = "그러니까 지금 이 순간을 모두와 함께해야 한다고 생각했어.",
  ui_story_5038_50381501_234_dialog_content = "네? 지금 이 순간이요?",
  ui_story_5038_50381501_235_dialog_content = "선장님! 보고드립니다!",
  ui_story_5038_50381501_236_dialog_content = "수리 작업을 마쳤고, 선체 검사도 끝났습니다.",
  ui_story_5038_50381501_237_dialog_content = "신풍호는 완전히 복구되었습니다!",
  ui_story_5038_50381501_238_dialog_content = "<size=45>우오오오오오!</size>",
  ui_story_5038_50381501_239_dialog_content = "우와! 그럼 신풍호를 다 고친 거예요?!",
  ui_story_5038_50381501_240_dialog_content = "그래. 드디어 다 고쳤어.",
  ui_story_5038_50381501_241_dialog_content = "신풍호의 이번 여정도 비로소 진정한 막을 내린 거야.",
  ui_story_5038_50381501_242_dialog_content = "파손과 수리를 끊임없이 반복하다, 이제야 원래의 모습으로 돌아왔군.",
  ui_story_5038_50381501_243_dialog_content = "모든 일이 원만히 끝났구려.",
  ui_story_5038_50381501_244_dialog_content = "정말 다행이구나! 하마터면 신풍호의 본모습도 까맣게 잊을 뻔했어!",
  ui_story_5038_50381501_245_dialog_content = "온통 반들반들하고 덧댄 부분도 없는 걸 보니 오히려 낯설게 느껴지는군요.",
  ui_story_5038_50381501_246_dialog_content = "모두 구경은 잠시 후에 다시 해 주세요.",
  ui_story_5038_50381501_247_dialog_content = "우선 모두와 함께 마치고 싶은 일이 하나 있어요.",
  ui_story_5038_50381501_248_dialog_content = "함께 마친다고요? 어떤 일인데요?",
  ui_story_5038_50381501_249_dialog_content = "장인들은 마음에 드는 작품에 자신의 이름을 새기는 습관이 있죠.",
  ui_story_5038_50381501_250_dialog_content = "이 신풍호는 항해 중에 우리 손으로 조금씩 수리해 여기까지 왔어요.\n그러니 우리 모두가 이 신풍호를 탄생시킨 장인이라 할 수 있어요.",
  ui_story_5038_50381501_251_dialog_content = "그러니 새롭게 태어난 신풍호를 여러분 모두의 이름으로 장식하고 싶어요.",
  ui_story_5038_50381501_252_dialog_content = "배에서 가장 상징적인 부분인 「토끼 귀」에 모두의 이름을 새기는 거예요.",
  ui_story_5038_50381501_253_dialog_content = "오, 그거 정말 재미있겠네!",
  ui_story_5038_50381501_254_dialog_content = "참으로 좋은 생각이십니다!",
  ui_story_5038_50381501_255_dialog_content = "나, 나 글씨 못 쓴다고 뭐라 하지 마!",
  ui_story_5038_50381501_256_dialog_content = "모두가 흔쾌히 받아들여 주시니 더할 나위 없이 기쁘네요.",
  ui_story_5038_50381501_257_dialog_content = "그럼, 이국타향에서 온 우리 친구부터 시작해 보자.",
  ui_story_5038_50381501_258_dialog_content = "네? 저요?!",
  ui_story_5038_50381501_259_dialog_content = "그래, 용주의 예법에선 항상 손님이 우선이거든.",
  ui_story_5038_50381501_260_dialog_content = "자, 조각칼 받아. 원하는 위치에 당신 이름을 새기도록 해.",
  ui_story_5038_50381501_261_dialog_content = "이, 이거 영 쑥스럽네요...",
  ui_story_5038_50381501_262_dialog_content = "게다가 제 이름을 써 봤자 다들 못 알아볼 텐데요...",
  ui_story_5038_50381501_263_dialog_content = "못 알아보면 더 좋지! 네가 글씨를 못 써도 알아볼 사람이 없잖아!",
  ui_story_5038_50381501_264_dialog_content = "우선 위치부터 정하는 게 좋겠어. 가장 눈에 띄는 곳을 골라봐.",
  ui_story_5038_50381501_265_dialog_content = "그럼요, 겁낼 필요 없습니다!",
  ui_story_5038_50381501_266_dialog_content = "아, 알겠어요...",
  ui_story_5038_50381501_267_dialog_content = "그럼 새겨 볼게요.",
  ui_story_5038_50381501_268_dialog_content = "그래. 어서 가 봐.",
  ui_story_5038_50381501_269_dialog_content = "(손이 안 떨리게 조각칼을 잘 쥐고.)",
  ui_story_5038_50381501_270_dialog_content = "(제일 가장자리를 고르자.)",
  ui_story_5038_50381501_271option_content = "PlayerName",
  ui_story_5038_50381501_272_dialog_content = "그래요! 바로 그겁니다! 아주 예쁘게 잘 새기셨군요!",
  ui_story_5038_50381501_273_dialog_content = "좀 더 크게 새기는 건 어떨까? 안 그러면 잘 안 보이잖아.",
  ui_story_5038_50381501_274_dialog_content = "(바닷물은 흔적을 남기지 못한다.)",
  ui_story_5038_50381501_275_dialog_content = "(평온함도, 거센 물결도 모두 순간일 뿐이다.)",
  ui_story_5038_50381501_276_dialog_content = "(그러나 사람들은 어떻게든 바다에 흔적을 남기고 싶어 한다.)",
  ui_story_5038_50381501_277_dialog_content = "(조각칼을 들고 자신의 이름을 손수 새겨 넣은 나처럼 말이다.)",
